export const PAGE_TEMPLATE: string = "<!doctype html>\n<html lang=\"ru\">\n<head>\n<meta charset=\"utf-8\">\n<meta name=\"viewport\" content=\"width=device-width, initial-scale=1\">\n<title>LAB — разбор сделок</title>\n<style>\n:root{--bg:#fafaf9;--card:#ffffff;--fg:#1c1b19;--mut:#6b6a66;--line:#e4e2dc;--acc:#2f6fed;--good:#16794a;--bad:#b3261e;--warn:#9a6a00;--w:#16794a;--l:#b3261e;--chip:#f0eee8}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--bg:#151514;--card:#1d1d1b;--fg:#ecebe6;--mut:#9b9a94;--line:#33322f;--acc:#6b9bff;--good:#4cc38a;--bad:#f2766d;--warn:#e0b04a;--w:#4cc38a;--l:#f2766d;--chip:#2a2a27}}\n:root[data-theme=\"dark\"]{--bg:#151514;--card:#1d1d1b;--fg:#ecebe6;--mut:#9b9a94;--line:#33322f;--acc:#6b9bff;--good:#4cc38a;--bad:#f2766d;--warn:#e0b04a;--w:#4cc38a;--l:#f2766d;--chip:#2a2a27}\n*{box-sizing:border-box}\nbody{margin:0;background:var(--bg);color:var(--fg);font:14px/1.45 system-ui,-apple-system,\"Segoe UI\",Roboto,sans-serif}\n.wrap{max-width:1180px;margin:0 auto;padding:12px 16px 60px}\nh1{font-size:19px;margin:6px 0 2px}\nh2{font-size:16px;margin:20px 0 8px}\nh3{font-size:14px;margin:16px 0 6px}\n.mut{color:var(--mut)}\n.small{font-size:12px}\n.bar{display:flex;flex-wrap:wrap;gap:8px;align-items:center;margin:10px 0}\nselect,input[type=text],input[type=number],button{font:inherit;color:var(--fg);background:var(--card);border:1px solid var(--line);border-radius:8px;padding:6px 9px}\ninput[type=number]{width:92px}\ninput[type=date]{font:inherit;color:var(--fg);background:var(--card);border:1px solid var(--line);border-radius:8px;padding:5px 8px}\nbutton{cursor:pointer}\nbutton.on,.chip.on{background:var(--acc);color:#fff;border-color:var(--acc)}\nbutton.pri{background:var(--acc);color:#fff;border-color:var(--acc)}\n.chip{display:inline-block;background:var(--chip);border:1px solid var(--line);border-radius:999px;padding:3px 10px;margin:2px 4px 2px 0;cursor:pointer;font-size:12.5px}\n.card{background:var(--card);border:1px solid var(--line);border-radius:12px;padding:12px 14px;margin:10px 0}\n.fl{display:flex;flex-wrap:wrap;gap:8px;align-items:center;padding:6px 0;border-bottom:1px dashed var(--line)}\n.fl:last-child{border-bottom:0}\n.kpis{display:grid;grid-template-columns:repeat(auto-fill,minmax(140px,1fr));gap:8px;margin:8px 0}\n.kpi{background:var(--card);border:1px solid var(--line);border-radius:10px;padding:8px 10px}\n.kpi b{display:block;font-size:18px}\n.kpi span{color:var(--mut);font-size:12px}\n.tw{overflow-x:auto;border:1px solid var(--line);border-radius:10px;background:var(--card)}\ntable{border-collapse:collapse;width:100%;font-size:13px}\nth,td{padding:5px 8px;text-align:right;white-space:nowrap;border-bottom:1px solid var(--line)}\nth{position:sticky;top:0;background:var(--card);cursor:pointer;color:var(--mut);font-weight:600;user-select:none}\nth.ns{cursor:default}\ntd.l,th.l{text-align:left}\ntr.click{cursor:pointer}\ntr.click:hover{background:var(--chip)}\n.pos{color:var(--good)}.neg{color:var(--bad)}.wr{color:var(--warn)}\n.note{background:var(--chip);border-radius:10px;padding:9px 12px;font-size:13px;margin:8px 0}\n.warn{border-left:3px solid var(--warn)}\n.grid2{display:grid;grid-template-columns:1fr 1fr;gap:12px}\n@media(max-width:760px){.grid2{grid-template-columns:1fr}}\nsvg text{fill:var(--mut);font-size:11px}\na{color:var(--acc)}\n.x{border:0;background:transparent;color:var(--mut);padding:2px 6px;font-size:16px}\ndetails summary{cursor:pointer;color:var(--acc)}\n.tabs{display:flex;gap:4px;margin:14px 0 6px;border-bottom:1px solid var(--line)}\n.tab{padding:9px 16px;border:0;border-bottom:3px solid transparent;border-radius:8px 8px 0 0;background:transparent;font-weight:600;color:var(--mut);font-size:14px}\n.tab:hover{color:var(--fg)}\n.tab.on{background:transparent;color:var(--acc);border-bottom-color:var(--acc)}\n.pg{display:flex;flex-wrap:wrap;align-items:center;gap:2px 0;margin:3px 0}\n.pgl{display:inline-block;min-width:104px;color:var(--mut);font-size:12px;margin-right:6px}\n.hero{border-color:var(--acc)}\n.goal{display:grid;grid-template-columns:repeat(auto-fill,minmax(190px,1fr));gap:10px}\n.goal label{display:flex;flex-direction:column;gap:3px;font-size:12px;color:var(--mut)}\n.goal input,.goal select{width:100%;color:var(--fg)}\n.top .th{display:flex;flex-wrap:wrap;gap:4px 10px;align-items:baseline;margin-bottom:8px}\n.top .th b{font-size:15px}\ntd.nm{white-space:normal;min-width:230px;max-width:340px;font-weight:500}\n.spark{display:block}\n.kpi b.pos{color:var(--good)}.kpi b.neg{color:var(--bad)}\ntr.click td:first-child{font-size:15px}\n.card{box-shadow:0 1px 2px rgba(0,0,0,.04)}\n\n.star{border:0;background:transparent;color:var(--warn);font-size:16px;padding:0 4px;cursor:pointer}\n.badge{display:inline-block;border-radius:999px;padding:1px 8px;font-size:11px;font-weight:600;background:var(--chip);border:1px solid var(--line)}\n.badge.live{color:var(--good);border-color:var(--good)}\n.tg{padding:3px 10px;font-size:12.5px;border-radius:999px}\n.cum{margin:12px 0}\n.cumsvg{display:block;margin:4px 0;background:var(--card);border:1px solid var(--line);border-radius:10px}\n.cumtip{min-height:18px;margin:2px 0 4px}\n.top td .mut.small{white-space:normal}\n\n/* ===== v4.4: оформление ===== */\n:root{--r:14px;--sh:0 1px 2px rgba(20,20,30,.05),0 6px 18px -8px rgba(20,20,30,.12);--acc2:#7c5cff}\n@media (prefers-color-scheme:dark){:root:not([data-theme=\"light\"]){--sh:0 1px 2px rgba(0,0,0,.4),0 8px 22px -10px rgba(0,0,0,.6)}}\n:root[data-theme=\"dark\"]{--sh:0 1px 2px rgba(0,0,0,.4),0 8px 22px -10px rgba(0,0,0,.6)}\nbody{background:var(--bg);background-image:radial-gradient(900px 300px at 85% -80px,color-mix(in srgb,var(--acc) 12%,transparent),transparent)}\n.wrap{max-width:1240px}\n.hd{display:flex;align-items:center;justify-content:space-between;gap:12px;flex-wrap:wrap;padding:10px 0 4px}\n.hd h1{font-size:22px;letter-spacing:-.01em;margin:0;display:flex;align-items:center;gap:10px}\n.hd h1 .lg{display:inline-grid;place-items:center;width:30px;height:30px;border-radius:9px;background:linear-gradient(135deg,var(--acc),var(--acc2));color:#fff;font-size:16px}\n.hd h1 small{font-weight:500;color:var(--mut);font-size:14px}\n#meta{margin:2px 0 6px}\n.theme{border-radius:999px;padding:5px 12px;font-size:13px}\n.card{border-radius:var(--r);box-shadow:var(--sh);padding:14px 16px}\nh3{font-size:15px;margin:18px 0 8px;display:flex;align-items:center;gap:6px}\nbutton{transition:background .12s,border-color .12s,transform .05s}\nbutton:hover{border-color:var(--acc)}\nbutton:active{transform:translateY(1px)}\nbutton:focus-visible,select:focus-visible,input:focus-visible{outline:2px solid var(--acc);outline-offset:1px}\nbutton.pri{background:linear-gradient(135deg,var(--acc),var(--acc2));border-color:transparent;font-weight:600}\nbutton.pri:hover{filter:brightness(1.07)}\nselect,input[type=text],input[type=number],input[type=date]{border-radius:9px}\n.tabs{gap:6px;border-bottom:0;background:var(--chip);padding:4px;border-radius:12px;width:fit-content;max-width:100%;overflow-x:auto;margin:14px 0 10px}\n.tab{padding:8px 16px;border:0;border-radius:9px;color:var(--mut);white-space:nowrap}\n.tab.on{background:var(--card);color:var(--fg);box-shadow:0 1px 3px rgba(0,0,0,.12);border-bottom-color:transparent}\n.kpis{grid-template-columns:repeat(auto-fill,minmax(150px,1fr));gap:10px}\n.kpi{border-radius:12px;padding:10px 12px;box-shadow:var(--sh);border-top:3px solid var(--line)}\n.kpi b{font-size:20px;letter-spacing:-.01em}\n.kpi b.pos{}\n.kpi:has(b.pos){border-top-color:var(--good)}\n.kpi:has(b.neg){border-top-color:var(--bad)}\n.tw{border-radius:12px;box-shadow:var(--sh)}\nth{text-transform:none;font-size:12px;letter-spacing:.01em;background:color-mix(in srgb,var(--card) 92%,var(--mut))}\ntbody tr:nth-child(even) td,table tr:nth-child(even) td{background:color-mix(in srgb,var(--card) 97%,var(--mut))}\ntr.click:hover td{background:color-mix(in srgb,var(--acc) 9%,var(--card))}\n.note{border-radius:12px;border:1px solid var(--line);background:color-mix(in srgb,var(--acc) 6%,var(--card))}\n.note.warn{border-left:4px solid var(--warn);background:color-mix(in srgb,var(--warn) 9%,var(--card))}\n.chip{transition:background .12s}\n.chip:hover{border-color:var(--acc)}\n.snav{position:sticky;top:0;z-index:20;display:flex;gap:6px;overflow-x:auto;padding:8px 2px;margin:8px 0;background:color-mix(in srgb,var(--bg) 88%,transparent);backdrop-filter:blur(8px);border-bottom:1px solid var(--line)}\n.snav button{border-radius:999px;padding:5px 13px;font-size:13px;white-space:nowrap;background:var(--card)}\n.snav button:hover{background:var(--acc);color:#fff;border-color:var(--acc)}\n.sec{scroll-margin-top:56px}\ndetails>summary{font-weight:600}\n@media(max-width:760px){.wrap{padding:8px 10px 50px}.kpis{grid-template-columns:repeat(2,1fr)}.hd h1{font-size:19px}}\n\n.xp .xh{display:flex;align-items:baseline;gap:10px;flex-wrap:wrap;margin-bottom:4px}\n.xr{display:flex;flex-wrap:wrap;align-items:center;gap:10px;padding:9px 0;border-bottom:1px solid var(--line)}\n.xr:last-of-type{border-bottom:0}\n.xr .xt{min-width:110px;font-weight:600}\n.xr input[type=number]{width:78px}\n.xr:not(.on) .xt{color:var(--mut);font-weight:500}\n.swt{position:relative;display:inline-block;width:38px;height:22px;flex:none}\n.swt input{opacity:0;width:0;height:0;position:absolute}\n.swt i{position:absolute;inset:0;background:var(--line);border-radius:999px;cursor:pointer;transition:background .15s}\n.swt i:before{content:\"\";position:absolute;left:3px;top:3px;width:16px;height:16px;border-radius:50%;background:#fff;transition:transform .15s;box-shadow:0 1px 2px rgba(0,0,0,.3)}\n.swt input:checked+i{background:var(--acc)}\n.swt input:checked+i:before{transform:translateX(16px)}\n.xsteps{display:flex;flex-direction:column;gap:6px;align-items:flex-start}\n.xs{display:flex;flex-wrap:wrap;align-items:center;gap:8px}\n.xadd{border-style:dashed;color:var(--acc);background:transparent;font-size:13px;padding:4px 12px}\n.xres{display:flex;flex-wrap:wrap;gap:22px;align-items:center;margin-top:10px;padding:10px 14px;background:var(--chip);border-radius:12px}\n.xres div{display:flex;flex-direction:column}\n.xres b{font-size:20px}\n.xres .xar{font-size:20px;color:var(--mut)}\n.pch{display:block;background:var(--card);border:1px solid var(--line);border-radius:12px}\n.tm{position:fixed;inset:0;background:rgba(0,0,0,.55);z-index:100;display:flex;align-items:flex-start;justify-content:center;overflow:auto;padding:24px 12px}\n.tmc{background:var(--card);border:1px solid var(--line);border-radius:16px;box-shadow:0 20px 60px rgba(0,0,0,.4);width:min(1080px,100%);padding:14px 16px}\n.tmh{display:flex;justify-content:space-between;align-items:center;margin-bottom:8px;font-size:16px}\n.kvs{display:grid;grid-template-columns:repeat(auto-fill,minmax(230px,1fr));gap:6px 18px;margin-top:10px}\n.kv{display:flex;justify-content:space-between;gap:10px;border-bottom:1px dashed var(--line);padding:3px 0;font-size:13px}\n.kv span{color:var(--mut)}\n</style>\n</head>\n<body>\n<div class=\"wrap\">\n<div class=\"hd\"><h1><span class=\"lg\">🧪</span>LAB <small>разбор сделок</small></h1><button class=\"theme\" id=\"themebtn\" type=\"button\">🌓 Тема</button></div>\n<div class=\"mut small\" id=\"meta\"></div>\n<div id=\"app\"><div class=\"note\">Загрузка…</div></div>\n</div>\n\n<script>\nconst D = /*__DATA__*/null;\nconst ROWS_B64 = \"/*__ROWS__*/\";\n// Строки сделок лежат в файле сжатыми (gzip+base64): так в файл помещаются ВСЕ сделки, а не выборка.\nasync function __loadRows(){\n  if(!ROWS_B64){return;}\n  var v=document.getElementById('app');if(v)v.innerHTML='<div class=\"note\">Распаковка данных…</div>';\n  if(typeof DecompressionStream==='undefined')throw new Error('браузер не поддерживает распаковку (нужен свежий Chrome/Edge/Safari/Firefox)');\n  var bin=atob(ROWS_B64),n=bin.length,u=new Uint8Array(n);\n  for(var i=0;i<n;i++)u[i]=bin.charCodeAt(i);\n  var stream=new Blob([u]).stream().pipeThrough(new DecompressionStream('gzip'));\n  var txt=await new Response(stream).text();\n  var o=JSON.parse(txt);\n  if(o&&o.c){var cc=o.c,nr=o.n,nc=cc.length,rr=new Array(nr);for(var i2=0;i2<nr;i2++){var r=new Array(nc);for(var j=0;j<nc;j++)r[j]=cc[j][i2];rr[i2]=r;}D.rows=rr;}\n  else D.rows=o;\n  D.paths=(o&&o.p)||D.paths||{};\n}\n__loadRows().then(function(){\n\"use strict\";\nconst NI=D.idCols.length, COLS=D.cols, CI={};\nCOLS.forEach((c,i)=>{CI[c.k]=NI+i;});\nconst C={ts:0,coin:1,side:2,won:3,idea:4,combo:5,wm:6,mk:7};\nconst OFF=D.offsets;\nconst COIN_SHORT={Bitcoin:'BTC',Ethereum:'ETH',Solana:'SOL',XRP:'XRP',Dogecoin:'DOGE'};\nconst TEMKA=new Set();D.ideas.forEach((id,i)=>{if(id.indexOf('temka:')===0)TEMKA.add(i);});\nconst ROWS=TEMKA.size?D.rows.filter(r=>!TEMKA.has(r[C.idea])):D.rows, N=ROWS.length;\n\nconst esc=s=>String(s).replace(/[&<>\"]/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','\"':'&quot;'}[c]));\nconst fmt=(x,d)=>(x===null||x===undefined||!isFinite(x))?'—':x.toFixed(d);\nconst pct=(x,d)=>(x===null||x===undefined||!isFinite(x))?'—':(x*100).toFixed(d===undefined?1:d)+'%';\nconst sgn=(x,d)=>(x===null||x===undefined||!isFinite(x))?'—':(x>0?'+':'')+x.toFixed(d);\nconst cls=x=>x>0?'pos':(x<0?'neg':'');\nconst money=x=>(x<0?'−':'+')+'$'+Math.abs(x).toFixed(Math.abs(x)>=100?0:2);\n\n// ---------- названия ----------\nfunction ideaTitle(id){\n  let m;\n  if(id==='model')return 'Модель цены';\n  if(id==='cdx')return 'Монета: прямой отрыв (без возврата к открытию)';\n  if(id==='cbk')return 'Монета: пробой максимума';\n  if(id==='cac')return 'Монета: рывок / разгон';\n  if(id==='cpb')return 'Монета: откат и возврат';\n  if(id==='cbd')return 'Монета: тело свечи';\n  if(id==='crv')return 'Монета: отрыв больше любого отката';\n  if(id==='fair1')return 'Справедливая цена (σ 60с)';\n  if(id==='fair2')return 'Справедливая цена (σ 120с)';\n  if((m=id.match(/^bot(\\d+)$/)))return 'Профиль бота '+m[1];\n  if((m=id.match(/^bot(\\d+)hi$/)))return 'Профиль '+m[1]+': ask ВЫШЕ потолка';\n  if(id==='margin')return 'Запас (z)';\n  if(id==='cheap')return 'Недооценка';\n  if(id==='panic')return 'Паника без разворота';\n  if(id==='impulse')return 'Импульс';\n  if(id==='psolo')return 'Соло пары BTC+ETH';\n  if(id.indexOf('temka:')===0){\n    const md=id.slice(6);\n    if(md==='m')return 'Темка: по рынку на открытии';\n    if((m=md.match(/^l([\\d.]+)w(\\d+)$/)))return 'Темка: лимит '+m[1]+', ждём '+m[2]+'с';\n    if((m=md.match(/^ct([\\d.]+)z([\\d.]+)$/)))return 'Темка: контртренд ≤'+m[1]+', рывок ≥'+m[2]+'σ';\n    return 'Темка: '+md;\n  }\n  return id;\n}\nconst famCache={};\nfunction famOf(id){\n  if(famCache[id])return famCache[id];\n  let f='Другое';\n  if(id==='model')f='Модель';\n  else if(id.indexOf('fair')===0)f='Справедливая';\n  else if(/^bot\\d+$/.test(id))f='Профили бота';\n  else if(/^bot\\d+hi$/.test(id))f='Выше потолка';\n  else if(id.indexOf('temka:')===0)f='Темка';\n  else if(id==='margin')f='Запас';\n  else if(id==='cheap')f='Недооценка';\n  else if(id==='panic')f='Паника';\n  else if(id==='impulse')f='Импульс';\n  else if(id==='psolo')f='Соло пары';\n  famCache[id]=f;return f;\n}\nconst FAMS=[...new Set(D.ideas.filter(id=>id.indexOf('temka:')!==0).map(famOf))];\n\n// ---------- справочник показателей для фильтров ----------\nconst NUMF=COLS.filter(c=>c.g==='entry'||c.g==='pre'||c.k==='mfe'||c.k==='mae').map(c=>({col:c.k,label:(c.k==='mfe'||c.k==='mae')?'⚠ '+c.label+' (знание задним числом — для анализа)':c.label,d:c.d,hint:c.hint}));\nconst NUMF_BY={};NUMF.forEach(f=>{NUMF_BY[f.col]=f;});\nconst CATF={\n  coin:{label:'Монета',vals:D.coins.map((c,i)=>[i,COIN_SHORT[c]||c]),get:r=>r[C.coin]},\n  side:{label:'Сторона',vals:[[0,'Up'],[1,'Down']],get:r=>r[C.side]},\n  wm:{label:'Окно',vals:[[5,'5 мин'],[15,'15 мин']],get:r=>r[C.wm]},\n  fam:{label:'Семейство идей',vals:FAMS.map(f=>[f,f]),get:r=>famOf(D.ideas[r[C.idea]])},\n  res:{label:'Итог сделки (задним числом — для анализа)',vals:[[1,'победа'],[0,'проигрыш']],get:r=>r[C.won]},\n  idea:{label:'Идея',vals:D.ideas.map((s,i)=>[i,ideaTitle(s)]).filter(v=>!TEMKA.has(v[0])),get:r=>r[C.idea]},\n};\n\n// ---------- состояние ----------\nconst S={minSm:0,goalP:0,goalL:0,flt:[],by:'idea',minN:30,stake:5,sort:'roi',dir:-1,show:150,sel:null,bucket:'z',tradeN:100,fit:null,showAll:false,one:true,tab:'an',back:null,dFrom:'',dTo:'',q:'',cumMode:'trade',favSort:'manual',ch:{steps:[{kind:'band',lo:0.6,hi:0.7,fam:''},{kind:'band',lo:0.8,hi:0.9,fam:''}],gap:''},top:{by:'cell',goal:5,maxLoss:0,cover:50,minN:20,trim:true,needOos:false,sort:'usdd',team:3,minSm:0,show:{}}};\ntry{const h=decodeURIComponent((location.hash||'').slice(1));if(h){const o=JSON.parse(h);if(Array.isArray(o.flt))S.flt=o.flt;if(o.by)S.by=o.by;if(o.minN)S.minN=o.minN;if(o.stake)S.stake=o.stake;if(o.one===false)S.one=false;if(['top','fav','chain'].indexOf(o.tab)>=0)S.tab=o.tab;if(typeof o.dFrom==='string')S.dFrom=o.dFrom;if(typeof o.dTo==='string')S.dTo=o.dTo;if(typeof o.q==='string')S.q=o.q;if(o.top&&typeof o.top==='object'){for(const k in o.top){if(k!=='show'&&k in S.top)S.top[k]=o.top[k];}}}}catch(e){}\ntry{const h2=decodeURIComponent((location.hash||'').slice(1));if(h2){const o2=JSON.parse(h2);if(o2.goalP>0)S.goalP=+o2.goalP;if(o2.goalL>0)S.goalL=+o2.goalL;if(o2.minSm>0)S.minSm=+o2.minSm;}}catch(e){}\nfunction saveHash(){try{history.replaceState(null,'','#'+encodeURIComponent(JSON.stringify({goalP:S.goalP,goalL:S.goalL,minSm:S.minSm,flt:S.flt,by:S.by,minN:S.minN,stake:S.stake,one:S.one,tab:S.tab,dFrom:S.dFrom,dTo:S.dTo,q:S.q,top:(function(){const t=Object.assign({},S.top);delete t.show;return t;})()})));}catch(e){}}\n\nlet rowsF=ROWS;\nfunction applyFilters(){\n  const num=S.flt.filter(f=>f.t==='num'&&CI[f.col]!==undefined).map(f=>({ci:CI[f.col],lo:f.lo,hi:f.hi,neg:!!f.neg,nul:!!f.nul}));\n  const cat=S.flt.filter(f=>f.t==='cat'&&CATF[f.f]&&f.vals.length).map(f=>({get:CATF[f.f].get,set:new Set(f.vals)}));\n  let tlo=null,thi=null;\n  if(S.dFrom){const t=Date.parse(S.dFrom+'T00:00:00Z');if(isFinite(t))tlo=t/1000;}\n  if(S.dTo){const t=Date.parse(S.dTo+'T00:00:00Z');if(isFinite(t))thi=t/1000+86400;}\n  if(!num.length&&!cat.length&&tlo===null&&thi===null){rowsF=ROWS;return;}\n  rowsF=ROWS.filter(r=>{\n    if(tlo!==null&&r[C.ts]<tlo)return false;\n    if(thi!==null&&r[C.ts]>=thi)return false;\n    for(let i=0;i<cat.length;i++)if(!cat[i].set.has(cat[i].get(r)))return false;\n    for(let i=0;i<num.length;i++){\n      const f=num[i],v=r[f.ci];\n      if(v===null){if(f.nul)continue;return false;}\n      const inr=(f.lo===null||v>=f.lo)&&(f.hi===null||v<=f.hi);\n      if(f.neg?inr:!inr)return false;\n    }\n    return true;\n  });\n}\n\n// ---------- статистика ----------\nconst XI=NI+COLS.length;\nconst roiOf=r=>{const x=r[XI];return(x!==undefined&&x!==null)?x:(r[C.won]?(1-r[CI.px])/r[CI.px]:-1);};\nfunction wilson(w,n){if(!n)return[0,1];const z=1.96,p=w/n,d=1+z*z/n,c=p+z*z/(2*n),m=z*Math.sqrt(p*(1-p)/n+z*z/(4*n*n));return[(c-m)/d,(c+m)/d];}\nfunction stats(rs){\n  const n=rs.length;let w=0,roi=0,px=0;const mk=new Set();\n  for(let i=0;i<n;i++){const r=rs[i];w+=r[C.won];px+=r[CI.px];roi+=roiOf(r);mk.add(r[C.mk]);}\n  const wr=n?w/n:0,apx=n?px/n:0,wl=wilson(w,n);\n  let verdict='мало';\n  if(n>=30)verdict=wl[0]>apx?'✅':(wl[1]<apx?'❌':'⚠️');\n  if(exOn())verdict='—';\n  return{n,w,wr,apx,roi:n?roi/n:0,edge:wr-apx,lo:wl[0],hi:wl[1],mk:mk.size,verdict,loss:n-w};\n}\n// стабильность: ROI в первой и второй половине (по времени)\nfunction halves(rs){\n  if(rs.length<10)return null;\n  const s=rs.slice().sort((a,b)=>a[C.ts]-b[C.ts]),h=s.length>>1;\n  const a=s.slice(0,h),b=s.slice(h);\n  const f=x=>{let t=0;for(const r of x)t+=roiOf(r);return t/x.length;};\n  return[f(a),f(b)];\n}\n\n// серии и ровность роста: самый частый винстрик, макс/средний, ровность кумулятивной (R² прямой линии при росте)\nfunction seqInfo(rs,sorted){\n  const n=rs.length;\n  const a=(sorted||n<2)?rs:rs.slice().sort((x,y)=>x[C.ts]-y[C.ts]);\n  const cnt=new Map();let cur=0,lcur=0,lmax=0,runs=0,sumRun=0,wmax=0;\n  let sx=0,sy=0,sxx=0,syy=0,sxy=0,cum=0;\n  const endRun=()=>{if(cur>0){cnt.set(cur,(cnt.get(cur)||0)+1);runs++;sumRun+=cur;if(cur>wmax)wmax=cur;}cur=0;};\n  for(let i=0;i<n;i++){\n    const r=a[i];\n    if(r[C.won]){cur++;lcur=0;}else{endRun();lcur++;if(lcur>lmax)lmax=lcur;}\n    cum+=roiOf(r);\n    sx+=i;sy+=cum;sxx+=i*i;syy+=cum*cum;sxy+=i*cum;\n  }\n  endRun();\n  let wmode=0,wmodeN=0;\n  cnt.forEach((c,len)=>{if(c>wmodeN||(c===wmodeN&&len>wmode)){wmode=len;wmodeN=c;}});\n  const dist=[...cnt.entries()].sort((x,y)=>x[0]-y[0]);\n  let wmed=0;\n  if(runs){let acc=0;const half=runs/2;for(const e of dist){acc+=e[1];if(acc>=half){wmed=e[0];break;}}}\n  let smooth=null;\n  if(n>=10){\n    const num=n*sxy-sx*sy,den=(n*sxx-sx*sx)*(n*syy-sy*sy);\n    smooth=(den>1e-12&&num>0)?(num*num)/den:0;\n  }\n  return{wmode:wmode,wmodeN:wmodeN,wmax:wmax,wavg:runs?sumRun/runs:0,wmed:wmed,wruns:runs,lmax:lmax,smooth:smooth,dist:dist};\n}\n\n// ---------- группировка ----------\nconst BY={\n  idea:{label:'Идея',key:r=>r[C.idea],name:k=>ideaTitle(D.ideas[k])},\n  cell:{label:'Идея + ячейка',key:r=>r[C.idea]+'|'+r[C.combo],name:k=>{const p=String(k).split('|');return ideaTitle(D.ideas[p[0]])+' · '+D.combos[p[1]];}},\n  coin:{label:'Монета',key:r=>r[C.coin],name:k=>COIN_SHORT[D.coins[k]]||D.coins[k]},\n  hour:{label:'Час суток (UTC)',key:r=>r[CI.hr],name:k=>k+':00'},\n  wm:{label:'Окно',key:r=>r[C.wm],name:k=>k+' мин'},\n  side:{label:'Сторона',key:r=>r[C.side],name:k=>k?'Down':'Up'},\n};\nBY.cellcoin={label:'Ячейка + монета',key:r=>r[C.idea]+'|'+r[C.combo]+'|'+r[C.coin],name:k=>{const p=String(k).split('|');return ideaTitle(D.ideas[p[0]])+' · '+D.combos[p[1]]+' · '+(COIN_SHORT[D.coins[p[2]]]||D.coins[p[2]]);}};\nBY.cellside={label:'Ячейка + сторона',key:r=>r[C.idea]+'|'+r[C.combo]+'|'+r[C.side],name:k=>{const p=String(k).split('|');return ideaTitle(D.ideas[p[0]])+' · '+D.combos[p[1]]+' · '+(p[2]==='1'?'Down':'Up');}};\n// один вход на рынок и сторону (самый ранний по времени): так же торгует бот, и сделки не дублируют друг друга\nfunction dedupe(rs){\n  const s=rs.slice().sort((a,b)=>a[C.ts]-b[C.ts]),seen=new Set(),out=[];\n  for(const r of s){const k=r[C.mk]*2+r[C.side];if(seen.has(k))continue;seen.add(k);out.push(r);}\n  return out;\n}\n// дневная цель: набрал цель за день (UTC) — до конца дня больше не входим; стоп-убыток — так же\nfunction goalOn(){return S.goalP>0||S.goalL>0;}\n// «после N проигрышей»: смотрим сигналы стратегии по порядку; пока не набралось N проигрышей подряд (уже закрытых) — не покупаем (виртуально наблюдаем), потом покупаем\nfunction afterCut(rs){return rs;}\nconst cutAll=rs=>goalCut(afterCut(rs));\n\nfunction goalCut(rs){\n  if(!goalOn())return rs;\n  const a=rs.slice().sort((x,y)=>x[C.ts]-y[C.ts]),out=[],P=S.goalP,L=S.goalL,st=S.stake,hs=CI.sec!==undefined?CI.sec:-1;\n  let day=-1,real=0,pend=[];\n  for(const r of a){\n    const t=r[C.ts],d=dayOf(t);\n    if(d!==day){day=d;real=0;pend=[];}\n    if(pend.length){const k=[];for(const q of pend){if(q[0]<=t)real+=q[1];else k.push(q);}pend=k;}\n    if(P>0&&real>=P-1e-9)continue;\n    if(L>0&&real<=-L+1e-9)continue;\n    out.push(r);\n    const p=r[CI.px],ro=roiOf(r),sc=hs>=0&&r[hs]!==null?r[hs]:0;\n    pend.push([t+sc,ro*st]);\n  }\n  return out;\n}\nfunction group(rs,by){\n  const g=new Map(),f=BY[by].key;\n  for(const r of rs){const k=f(r);let a=g.get(k);if(!a){a=[];g.set(k,a);}a.push(r);}\n  if(S.one)g.forEach((a,k)=>{g.set(k,dedupe(a));});\n  if(goalOn())g.forEach((a,k)=>{g.set(k,cutAll(a));});\n  return g;\n}\n\n// ---------- отрисовка: фильтры ----------\nconst crCache={};\nfunction colRange(col){\n  if(crCache[col]!==undefined)return crCache[col];\n  const ci=CI[col];let a=Infinity,b=-Infinity;\n  for(let i=0;i<N;i++){const v=ROWS[i][ci];if(v===null)continue;if(v<a)a=v;if(v>b)b=v;}\n  return crCache[col]=(a===Infinity?null:[a,b]);\n}\nconst pxP=(a,b)=>({t:a.toFixed(2)+'–'+b.toFixed(2),f:[{t:'num',col:'px',lo:a,hi:b}]});\nconst secP=(t,a,b)=>({t:t,f:[{t:'num',col:'sec',lo:a,hi:b}]});\nconst coinP=D.coins.map((c,i)=>({t:COIN_SHORT[c]||c,f:[{t:'cat',f:'coin',vals:[i]}]}));\nfunction lastDayIdx(){const m=D.meta||{};if(m.lastTs)return Math.floor(m.lastTs/1000/86400);let b=0;for(let i=0;i<N;i++){const d=Math.floor(ROWS[i][C.ts]/86400);if(d>b)b=d;}return b;}\nconst fromStrN=n=>new Date((lastDayIdx()-(n-1))*86400000).toISOString().slice(0,10);\nconst PRESET_GROUPS=[\n  {l:'Цена входа',p:[pxP(0.60,0.70),pxP(0.70,0.80),pxP(0.80,0.90),pxP(0.90,0.93),pxP(0.93,0.96),pxP(0.95,0.98)]},\n  {l:'До закрытия',p:[secP('≤60с',null,60),secP('60–120с',60,120),secP('120–180с',120,180),secP('180–240с',180,240),secP('≤180с',null,180)]},\n  {l:'Монета',p:coinP},\n  {l:'Сторона / окно',p:[{t:'Up',f:[{t:'cat',f:'side',vals:[0]}]},{t:'Down',f:[{t:'cat',f:'side',vals:[1]}]},{t:'5 мин',f:[{t:'cat',f:'wm',vals:[5]}]},{t:'15 мин',f:[{t:'cat',f:'wm',vals:[15]}]}]},\n  {l:'Биржи',p:[{t:'Binance против',f:[{t:'num',col:'bk',lo:0,hi:0}]},{t:'Хотя бы одна биржа против',f:[{t:'num',col:'nag',lo:1,hi:null}]},{t:'Ни одна не против',f:[{t:'num',col:'nag',lo:0,hi:0}]}]},\n  {l:'Период',p:[2,3,5,7].map(n=>({t:'Последние '+n+' дн.',d:n}))}\n];\nPRESET_GROUPS.forEach(g=>{g.p=g.p.filter(p=>!p.f||p.f.every(f=>f.t==='cat'||CI[f.col]!==undefined));});\nfunction sameNum(a,b){return a.t==='num'&&b.t==='num'&&a.col===b.col&&a.lo===b.lo&&a.hi===b.hi&&!a.neg;}\nfunction presetOn(p){\n  if(p.d)return S.dFrom===fromStrN(p.d)&&!S.dTo;\n  return p.f.every(f=>f.t==='num'?S.flt.some(x=>sameNum(x,f)):S.flt.some(x=>x.t==='cat'&&x.f===f.f&&f.vals.every(v=>x.vals.indexOf(v)>=0)));\n}\nfunction presetClick(p){\n  if(p.d){const s=fromStrN(p.d);if(S.dFrom===s&&!S.dTo){S.dFrom='';}else{S.dFrom=s;S.dTo='';}return;}\n  const on=presetOn(p);\n  p.f.forEach(f=>{\n    if(f.t==='cat'){\n      const ex=S.flt.find(x=>x.t==='cat'&&x.f===f.f);\n      if(on){if(ex){f.vals.forEach(v=>{const k=ex.vals.indexOf(v);if(k>=0)ex.vals.splice(k,1);});if(!ex.vals.length)S.flt.splice(S.flt.indexOf(ex),1);}}\n      else if(ex){f.vals.forEach(v=>{if(ex.vals.indexOf(v)<0)ex.vals.push(v);});}\n      else S.flt.push({t:'cat',f:f.f,vals:f.vals.slice()});\n    }else{\n      if(on)S.flt=S.flt.filter(x=>!sameNum(x,f));\n      else{S.flt=S.flt.filter(x=>!(x.t==='num'&&x.col===f.col&&!x.neg));S.flt.push(JSON.parse(JSON.stringify(f)));}\n    }\n  });\n}\nfunction fltRow(f,i){\n  let h='<div class=\"fl\" data-i=\"'+i+'\">';\n  if(f.t==='num'){\n    const nf=NUMF_BY[f.col],rg=colRange(f.col);\n    h+='<select data-act=\"fcol\">'+NUMF.map(x=>'<option value=\"'+x.col+'\"'+(x.col===f.col?' selected':'')+'>'+esc(x.label)+'</option>').join('')+'</select>';\n    h+=' от <input type=\"number\" step=\"any\" data-act=\"flo\" value=\"'+(f.lo===null?'':f.lo)+'\" placeholder=\"'+(rg?fmt(rg[0],nf?nf.d:2):'любое')+'\"> до <input type=\"number\" step=\"any\" data-act=\"fhi\" value=\"'+(f.hi===null?'':f.hi)+'\" placeholder=\"'+(rg?fmt(rg[1],nf?nf.d:2):'любое')+'\">';\n    h+=' <label class=\"small\"><input type=\"checkbox\" data-act=\"fneg\"'+(f.neg?' checked':'')+'> кроме этого диапазона</label> <label class=\"small\"><input type=\"checkbox\" data-act=\"fnul\"'+(f.nul?' checked':'')+'> с пустыми</label>';\n    if(nf&&nf.hint)h+=' <span class=\"mut small\">'+esc(nf.hint)+(rg?' · в данных: '+fmt(rg[0],nf.d)+' … '+fmt(rg[1],nf.d):'')+'</span>';\n  }else{\n    const cf=CATF[f.f];\n    h+='<b>'+esc(cf.label)+':</b> ';\n    cf.vals.forEach(v=>{h+='<span class=\"chip'+(f.vals.indexOf(v[0])>=0?' on':'')+'\" data-act=\"fval\" data-v=\"'+esc(v[0])+'\">'+esc(v[1])+'</span>';});\n    h+=' <span class=\"mut small\">пусто = любые</span>';\n  }\n  return h+' <button class=\"x\" data-act=\"fdel\" title=\"убрать\">×</button></div>';\n}\nfunction renderFilters(){\n  const nAct=S.flt.length+(S.dFrom?1:0)+(S.dTo?1:0);\n  let h='<div class=\"card\"><div class=\"bar\" style=\"margin:0 0 6px\"><b>Фильтры</b> <span class=\"mut small\">сделок после фильтров: <b>'+rowsF.length+'</b> из '+N+(nAct?' · включено условий: '+nAct:'')+'</span>';\n  h+=' <button data-act=\"fclear\">Сбросить всё</button></div>';\n  PRESET_GROUPS.forEach((g,gi)=>{h+='<div class=\"pg\"><span class=\"pgl\">'+esc(g.l)+'</span>'+g.p.map((p,i)=>'<span class=\"chip'+(presetOn(p)?' on':'')+'\" data-act=\"preset\" data-g=\"'+gi+'\" data-i=\"'+i+'\">'+esc(p.t)+'</span>').join('')+'</div>';});\n  h+='<div class=\"bar\" style=\"margin:8px 0 4px\"><label class=\"small\">Период с <input type=\"date\" id=\"dFrom\" value=\"'+esc(S.dFrom)+'\"></label><label class=\"small\">по <input type=\"date\" id=\"dTo\" value=\"'+esc(S.dTo)+'\"></label>';\n  h+='<label class=\"small\">Поиск по названию <input type=\"text\" id=\"q\" value=\"'+esc(S.q)+'\" placeholder=\"например: справедливая\" style=\"width:190px\"></label></div>';\n  S.flt.forEach((f,i)=>{h+=fltRow(f,i);});\n  h+='<div class=\"bar\" style=\"margin:8px 0 4px\"><b>🎯 Дневная цель</b> <label class=\"small\">прибыль $ в день <input type=\"number\" id=\"goalP\" min=\"0\" step=\"any\" value=\"'+(S.goalP||'')+'\" placeholder=\"выкл\" style=\"width:80px\"></label><label class=\"small\">стоп по убытку $ в день <input type=\"number\" id=\"goalL\" min=\"0\" step=\"any\" value=\"'+(S.goalL||'')+'\" placeholder=\"выкл\" style=\"width:80px\"></label>'+(goalOn()?'<span class=\"badge live\">включено: ТС'+(S.goalP>0?' останавливается на день после +$'+S.goalP:'')+(S.goalL>0?' · после −$'+S.goalL:'')+' (ставка $'+S.stake+', день по UTC)</span>':'<span class=\"mut small\">пусто = выкл. Достигла цели за день — до конца дня (UTC) новых входов нет</span>')+'</div>';\n  h+='<div class=\"bar\" style=\"margin:8px 0 0\"><select id=\"addnum\"><option value=\"\">+ показатель (цена, z, секунды, биржи…)</option>'+NUMF.map(x=>'<option value=\"'+x.col+'\">'+esc(x.label)+'</option>').join('')+'</select>';\n  h+='<select id=\"addcat\"><option value=\"\">+ категория (монета, сторона, окно…)</option>'+Object.keys(CATF).map(k=>'<option value=\"'+k+'\">'+esc(CATF[k].label)+'</option>').join('')+'</select>';\n  h+='<span class=\"mut small\">все условия работают вместе (И). Пустое поле = без ограничения. «Кроме диапазона» — наоборот, убирает этот диапазон.</span></div></div>';\n  return h;\n}\n\n// ---------- таблица стратегий ----------\nconst COLS_T=[\n  ['name','Стратегия',1],['n','Сделок'],['mk','Рынков'],['wr','Побед'],['apx','Ср. цена'],['usd','Прибыль'],['roi','ROI'],['edge','Edge'],['lo','Нижн. гр.'],['verdict','Вердикт',1],['stab','Устойчивость (1-я / 2-я половина)',1],['wmode','Частый винстрик'],['wmax','Макс. винстрик'],['smooth','Ровность роста']\n];\nfunction renderTable(){\n  const g=group(rowsF,S.by);\n  let rows=[];\n  g.forEach((rs,k)=>{\n    const st=stats(rs);st.key=k;st.name=BY[S.by].name(k);st.usd=st.roi*st.n*S.stake;st.h=halves(rs);st.stab=st.h?Math.min(st.h[0],st.h[1]):-9;Object.assign(st,seqInfo(rs));\n    rows.push(st);\n  });\n  const total=rows.length;\n  rows=rows.filter(r=>r.n>=S.minN);\n  if(S.minSm>0)rows=rows.filter(r=>r.smooth!=null&&r.smooth*100>=S.minSm);\n  if(S.q.trim()){const qq=S.q.trim().toLowerCase();rows=rows.filter(r=>String(r.name).toLowerCase().indexOf(qq)>=0);}\n  rows.sort((a,b)=>{\n    const x=a[S.sort],y=b[S.sort];\n    if(typeof x==='string')return S.dir*(x<y?1:(x>y?-1:0))*-1;\n    return S.dir*((x||0)-(y||0));\n  });\n  let h='<div class=\"card\"><div class=\"bar\" style=\"margin:0 0 6px\"><b>Стратегии</b>';\n  h+='<label class=\"small\">Группировать по <select id=\"by\">'+Object.keys(BY).map(k=>'<option value=\"'+k+'\"'+(S.by===k?' selected':'')+'>'+BY[k].label+'</option>').join('')+'</select></label>';\n  h+='<label class=\"small\">мин. сделок <input type=\"number\" id=\"minN\" min=\"1\" value=\"'+S.minN+'\" style=\"width:70px\"></label>';\n  h+='<label class=\"small\" title=\"Показывать только стратегии, у которых кумулятивная прибыль похожа на ровную линию вверх. 0 = не фильтровать\">ровность роста не ниже, % <input type=\"number\" id=\"minSm\" min=\"0\" max=\"100\" value=\"'+(S.minSm||'')+'\" placeholder=\"0\" style=\"width:70px\"></label>';\n  h+='<label class=\"small\">ставка $ <input type=\"number\" id=\"stake\" min=\"1\" value=\"'+S.stake+'\" style=\"width:70px\"></label>';\n  h+='<label class=\"small\" title=\"Если стратегия входит в один рынок несколько раз (разными ячейками), считаем только первый вход, как торгует бот. Иначе сделки одного рынка засчитываются много раз, и надёжность завышается.\"><input type=\"checkbox\" id=\"one\"'+(S.one?' checked':'')+'> один вход на рынок</label>';\n  h+='<span class=\"mut small\">показано '+Math.min(rows.length,S.show)+' из '+rows.length+' (скрыто с малым числом сделок: '+(total-rows.length)+')</span></div>';\n  h+='<div class=\"tw\"><table><thead><tr>';\n  COLS_T.forEach(c=>{if(c[0]==='stab')h+='<th class=\"l\" data-act=\"sort\" data-k=\"stab\">'+c[1]+(S.sort==='stab'?(S.dir<0?' ▼':' ▲'):'')+'</th>';else h+='<th'+(c[2]?' class=\"l\"':'')+' data-act=\"sort\" data-k=\"'+c[0]+'\">'+c[1]+(S.sort===c[0]?(S.dir<0?' ▼':' ▲'):'')+'</th>';});\n  h+='</tr></thead><tbody>';\n  rows.slice(0,S.show).forEach(r=>{\n    const hv=r.h?'<span class=\"'+cls(r.h[0])+'\">'+sgn(r.h[0]*100,1)+'%</span> / <span class=\"'+cls(r.h[1])+'\">'+sgn(r.h[1]*100,1)+'%</span>'+((r.h[0]>0&&r.h[1]>0)?' ✓':''):'—';\n    h+='<tr class=\"click\" data-act=\"open\" data-k=\"'+esc(r.key)+'\"><td class=\"l\">'+esc(r.name)+'</td><td>'+r.n+'</td><td>'+r.mk+'</td><td>'+pct(r.wr)+'</td><td>'+fmt(r.apx,3)+'</td><td class=\"'+cls(r.usd)+'\">'+money(r.usd)+'</td><td class=\"'+cls(r.roi)+'\">'+sgn(r.roi*100,1)+'%</td><td class=\"'+cls(r.edge)+'\">'+sgn(r.edge*100,1)+' п.п.</td><td>'+pct(r.lo)+'</td><td class=\"l\">'+r.verdict+'</td><td class=\"l\">'+hv+'</td><td title=\"самая частая длина серии побед подряд (сколько раз такая серия была)\">'+(r.wmode?r.wmode+' <span class=\"mut small\">×'+r.wmodeN+'</span>':'—')+'</td><td>'+(r.wmax||'—')+'</td><td>'+(r.smooth==null?'—':Math.round(r.smooth*100)+'%')+'</td></tr>';\n  });\n  h+='</tbody></table></div>';\n  if(rows.length>S.show)h+='<div class=\"bar\"><button data-act=\"more\">Показать ещё 200</button></div>';\n  h+='<div class=\"note small\">«Прибыль» — на ставку из поля «ставка $» без комиссий (победа даёт (1−цена)/цена, проигрыш −100%). ✅ — «Нижн. гр.» выше средней цены (плюс доказан при 95%), ⚠️ — не доказан, ❌ — минус доказан, «мало» — меньше 30 сделок. «Устойчивость» — ROI первой и второй половины периода: ✓ если обе положительные. <a href=\"#\" data-act=\"help\">Как читать подробнее</a></div></div>';\n  return h;\n}\n\n// ---------- подробности выбранной стратегии ----------\n// «перевернуть»: торгуем противоположную сторону. Цена входа ≈ 1 − bid нашей стороны = 1 − (ask − спред)\nlet FLIPPOST=null;\nfunction flipRows(rs){\n  if(!FLIPPOST){FLIPPOST=[];Object.keys(CI).forEach(k=>{if(/^d\\d+$/.test(k)||/^tp\\d+$/.test(k)||['mfe','mae','tmae','lost10','flip','end10','cm10','cm30','fin','finr'].indexOf(k)>=0)FLIPPOST.push(CI[k]);});}\n  const ip=CI.px,isp=CI.spr,out=[];\n  for(const r of rs){\n    const sp=(isp!==undefined&&r[isp]!==null&&r[isp]>=0)?r[isp]:0.01,p2=1-r[ip]+sp;\n    if(!(p2>0.01&&p2<0.99))continue;\n    const c=r.slice();c[C.won]=r[C.won]?0:1;c[C.side]=1-r[C.side];c[ip]=p2;\n    for(const j of FLIPPOST)c[j]=null;\n    out.push(c);\n  }\n  return out;\n}\nfunction selRows(){\n  if(!S.sel||!S.sel.flip)return selRowsBase();\n  const gp=S.goalP,gl=S.goalL;S.goalP=0;S.goalL=0;let rs;\n  try{\n    const f=S.sel.favId?FAVS.find(x=>x.id===S.sel.favId):null;\n    rs=f?favRows(f):selRowsBase();\n  }finally{S.goalP=gp;S.goalL=gl;}\n  return cutAll(flipRows(rs));\n}\nfunction selRowsBase(){\n  if(!S.sel)return[];\n  if(S.sel.rows)return applyExit(applyRe(applyEntry(S.sel.rows)));\n  const f=BY[S.sel.by].key,k=String(S.sel.key);\n  const x=rowsF.filter(r=>String(f(r))===k);\n  const xe=applyRe(applyEntry(x));\n  return cutAll(applyExit(S.one?dedupe(xe):xe));\n}\n// ---------- ВЫХОДЫ: тейк-профит, стоп, добор (независимые; всё считается по реальному пути bid после входа) ----------\nconst XK=XI+1;\nconst X={tp:{on:false,v:10,u:'pct'},sl:{on:false,v:20,u:'pct'},add:{on:false,steps:[{m:'c',v:10,usd:5}]},more:false};\nconst UPL=[3,5,10,15,20,30],DNL=[5,10,15,20,30,40,50],SLIP=0.02;\n// v4.6: «умные» условия: выход при обвале после роста; вход после выноса и возврата; вход после дна и отскока\nconst CR={on:false,h:90,l:50};\nconst RE={b:{on:false,peak:85,low:50,buy:80},c:{on:false,low:50,buy:85}};\nlet REOFF=false;\nlet EXOFF=false;\nconst isNul=v=>v===null||v===undefined;\nfunction exHave(){return CI.mae!==undefined&&CI.mfe!==undefined&&CI.tp3!==undefined;}\nfunction exOn(){return !EXOFF&&!entryOn()&&!reOn()&&exHave()&&(X.tp.on||X.sl.on||CR.on||(X.add.on&&X.add.steps.length>0));}\nfunction reOn(){return !REOFF&&!entryOn()&&exHave()&&(RE.b.on||RE.c.on);}\n// расстояние по цене (0..1) из «% от цены входа», «$ прибыли/убытка на базовую ставку» или «центов»\nfunction xDist(u,v,px,st){return u==='pct'?px*v/100:(u==='usd'?v*px/st:v/100);}\n// когда (секунд после входа) bid впервые дошёл на gc центов вверх (pre='tp') или вниз (pre='dn'); между записанными уровнями — по прямой\nfunction tLevel(r,pre,levels,gc){\n  let lo=0,tlo=0,hi=null,thi=null;\n  for(const L of levels){\n    const t=r[CI[pre+L]];\n    if(Math.abs(L-gc)<1e-6)return isNul(t)?0:t;\n    if(L<gc){lo=L;if(!isNul(t))tlo=t;}\n    else if(hi===null){hi=L;thi=isNul(t)?null:t;}\n  }\n  if(hi!==null&&thi!==null)return tlo+(thi-tlo)*(gc-lo)/(hi-lo);\n  return tlo+0.5;\n}\nfunction xSim(r,st){\n  const px=r[CI.px],mf=r[CI.mfe],ma=r[CI.mae];\n  if(isNul(mf)||isNul(ma))return null;\n  const sp=r[CI.spr],spr=isNul(sp)?0.01:Math.max(0,sp);\n  let kind='',tx=Infinity,ex=null;\n  if(X.sl.on&&X.sl.v>0){\n    const s=xDist(X.sl.u,X.sl.v,px,st);\n    if(s>0&&px-s>0.02&&ma<=-s+1e-9){tx=tLevel(r,'dn',DNL,s*100);kind='sl';ex=Math.max(0.01,px-s-SLIP);}\n  }\n  if(X.tp.on&&X.tp.v>0){\n    const g=xDist(X.tp.u,X.tp.v,px,st);\n    if(g>0&&px+g<=0.995&&mf>=g-1e-9){const tt=tLevel(r,'tp',UPL,g*100);if(tt<tx){tx=tt;kind='tp';ex=px+g;}}\n  }\n  if(CR.on&&CR.l<CR.h){const cc=crashT(r,px);if(cc&&cc.t<tx){tx=cc.t;kind='cr';ex=cc.ex;}}\n  if(!kind)ex=r[C.won]?1:0;\n  let pnl=(ex-px)/px;const steps=[];\n  if(X.add.on)X.add.steps.forEach((a,i)=>{\n    if(!(a.usd>0))return;\n    const ga=a.m==='p'?a.v-px:a.v/100;\n    if(!(ga>0.0049)||px+ga>0.99||mf<ga-1e-9)return;\n    const ta=tLevel(r,'tp',UPL,ga*100);\n    if(!(ta<tx))return;\n    const pa=Math.min(0.99,px+ga+spr),pp=(a.usd/st)*(ex-pa)/pa;\n    pnl+=pp;steps.push([i,pp]);\n  });\n  if(!kind&&!steps.length)return null;\n  return{pnl:pnl,kind:kind,steps:steps};\n}\n// путь bid после входа: по секундам (если сохранён) или по ключевым точкам\nfunction hasPath(r){return !!(D.paths&&D.paths[pkey(r)]);}\nfunction bidSer(r){\n  const px=r[CI.px];\n  const dense=D.paths&&D.paths[pkey(r)];\n  if(dense){const a=[];dense.forEach((b,i)=>{if(b!==null&&b>=0)a.push([i*2,b/100]);});if(a.length)return a;}\n  const T=isNul(r[CI.sec])?300:Math.max(30,r[CI.sec]);\n  const a=[[0,px]];\n  OFF.forEach(o=>{const v=r[CI['d'+o]];if(!isNul(v)&&o<=T)a.push([o,px+v]);});\n  if(!isNul(r[CI.end10])&&T>20)a.push([T-10,px+r[CI.end10]]);\n  UPL.forEach(L=>{const t=r[CI['tp'+L]];if(!isNul(t))a.push([t,px+L/100]);});\n  DNL.forEach(L=>{const t=r[CI['dn'+L]];if(!isNul(t))a.push([t,px-L/100]);});\n  if(CI.tmfe!==undefined&&!isNul(r[CI.tmfe])&&!isNul(r[CI.mfe]))a.push([r[CI.tmfe],px+r[CI.mfe]]);\n  if(!isNul(r[CI.tmae])&&!isNul(r[CI.mae]))a.push([r[CI.tmae],px+r[CI.mae]]);\n  a.sort((x,y)=>x[0]-y[0]);\n  return a;\n}\n// «обвал»: bid доходил до H, потом упал до L → продаём\nfunction crashT(r,px){\n  if(!hasPath(r))return null; // только по точному пути (по ключевым точкам результат завышался)\n  const H=CR.h/100,L=CR.l/100,ser=bidSer(r);\n  let iH=-1;for(let i=0;i<ser.length;i++){if(ser[i][1]>=H-1e-9){iH=i;break;}}\n  if(iH>=0)for(let j=iH+1;j<ser.length;j++){if(ser[j][1]<=L+1e-9)return{t:ser[j][0],ex:Math.max(0.01,Math.min(L,ser[j][1])-0.01)};}\n  return null;\n}\n// «вынос / дно»: peak===null — просто дно; иначе сначала рост до peak, потом падение до low, потом возврат до buy → покупаем\nfunction reFind(r,peak,low,buy){\n  const ser=bidSer(r);let st=peak===null?1:0;\n  for(let i=0;i<ser.length;i++){\n    const b=ser[i][1];\n    if(st===0){if(b>=peak-1e-9)st=1;}\n    else if(st===1){if(b<=low+1e-9)st=2;}\n    else if(b>=buy-1e-9)return ser[i][0];\n  }\n  return null;\n}\nfunction applyRe(rs){\n  if(!reOn()||(S.sel&&S.sel.flip))return rs;\n  const out=[];\n  for(const r of rs){\n    if(!hasPath(r))continue; // без точного пути «вынос/дно» считать нельзя: результат получался нереально красивым\n    const cand=[];\n    if(RE.b.on&&RE.b.low<RE.b.peak&&RE.b.buy>RE.b.low){const t=reFind(r,RE.b.peak/100,RE.b.low/100,RE.b.buy/100);if(t!==null)cand.push([t,RE.b.buy/100,'вынос и возврат']);}\n    if(RE.c.on&&RE.c.buy>RE.c.low){const t=reFind(r,null,RE.c.low/100,RE.c.buy/100);if(t!==null)cand.push([t,RE.c.buy/100,'дно и отскок']);}\n    if(!cand.length)continue;\n    cand.sort((a,b)=>a[0]-b[0]);const k=cand[0];\n    const sp=r[CI.spr],spr=isNul(sp)?0.01:Math.max(0,sp),np=Math.min(0.99,k[1]+spr),px0=r[CI.px],ta=k[0];\n    const c=r.slice();while(c.length<XK+5)c.push(null);\n    c[CI.px]=np;c[C.ts]=r[C.ts]+Math.round(ta);\n    if(!isNul(r[CI.sec]))c[CI.sec]=Math.max(0,r[CI.sec]-ta);\n    c[CI.mfe]=null;c[CI.mae]=null;\n    for(const kk of Object.keys(CI)){if(/^(d\\d+|tp\\d+|dn\\d+|tmae|tmfe|mnp|end10)$/.test(kk))c[CI[kk]]=null;}\n    c[XK+4]=[px0,Math.round(ta),k[2]];\n    out.push(c);\n  }\n  return out;\n}\nfunction selRowsNoRe(){const o=REOFF;REOFF=true;try{return selRows();}finally{REOFF=o;}}\nfunction applyExit(rs){\n  if(!exOn()||(S.sel&&S.sel.flip))return rs;\n  const st=S.stake,out=[];\n  for(const r of rs){\n    const x=xSim(r,st);\n    if(!x){out.push(r);continue;}\n    const c=r.slice();while(c.length<XI)c.push(null);\n    c[XI]=x.pnl;c[XK]=x.kind||'add';c[XK+1]=r[C.won];c[XK+2]=x.steps;c[XK+3]=(r[C.won]?(1-r[CI.px])/r[CI.px]:-1);\n    c[C.won]=x.pnl>0?1:0;out.push(c);\n  }\n  return out;\n}\nfunction selRowsPlain(){const o=EXOFF,o2=REOFF;EXOFF=true;REOFF=true;try{return selRows();}finally{EXOFF=o;REOFF=o2;}}\n\nfunction dayTable(rs){\n  const m=new Map();\n  for(const r of rs){const d=new Date(r[C.ts]*1000).toISOString().slice(0,10);let a=m.get(d);if(!a){a=[];m.set(d,a);}a.push(r);}\n  const days=[...m.keys()].sort();\n  let h='<h3>По дням (UTC)</h3><div class=\"tw\"><table><thead><tr><th class=\"l ns\">День</th><th class=\"ns\">Сделок</th><th class=\"ns\">Побед</th><th class=\"ns\">Проигрышей</th><th class=\"ns\">ROI</th><th class=\"ns\">Прибыль</th></tr></thead><tbody>';\n  days.forEach(d=>{const st=stats(m.get(d));h+='<tr><td class=\"l\">'+d+'</td><td>'+st.n+'</td><td>'+pct(st.wr)+'</td><td>'+st.loss+'</td><td class=\"'+cls(st.roi)+'\">'+sgn(st.roi*100,1)+'%</td><td class=\"'+cls(st.roi)+'\">'+money(st.roi*st.n*S.stake)+'</td></tr>';});\n  return h+'</tbody></table></div>';\n}\nfunction bucketTable(rs){\n  let opts='';NUMF.forEach(f=>{opts+='<option value=\"'+f.col+'\"'+(S.bucket===f.col?' selected':'')+'>'+esc(f.label)+'</option>';});\n  let h='<h3>Винрейт по корзинам показателя</h3><div class=\"bar\"><select id=\"bcol\">'+opts+'</select></div>';\n  const ci=CI[S.bucket];const arr=rs.filter(r=>r[ci]!==null).sort((a,b)=>a[ci]-b[ci]);\n  const k=Math.min(5,Math.floor(arr.length/8));\n  if(k<2)return h+'<div class=\"note\">Мало данных по этому показателю.</div>';\n  const dd=NUMF_BY[S.bucket].d;\n  h+='<div class=\"tw\"><table><thead><tr><th class=\"l ns\">Диапазон</th><th class=\"ns\">Сделок</th><th class=\"ns\">Побед</th><th class=\"ns\">Ср. цена</th><th class=\"ns\">ROI</th></tr></thead><tbody>';\n  for(let b=0;b<k;b++){const part=arr.slice(Math.floor(arr.length*b/k),Math.floor(arr.length*(b+1)/k));const st=stats(part);\n    h+='<tr><td class=\"l\">'+fmt(part[0][ci],dd)+' … '+fmt(part[part.length-1][ci],dd)+'</td><td>'+st.n+'</td><td>'+pct(st.wr)+'</td><td>'+fmt(st.apx,3)+'</td><td class=\"'+cls(st.roi)+'\">'+sgn(st.roi*100,1)+'%</td></tr>';}\n  return h+'</tbody></table></div>';\n}\nconst tz=sec=>{const d=new Date(sec*1000),p=x=>(x<10?'0':'')+x;return p(d.getMonth()+1)+'-'+p(d.getDate())+' '+p(d.getHours())+':'+p(d.getMinutes())+':'+p(d.getSeconds());};\nlet TRLIST=[];\nfunction tradesTable(rs){\n  const sorted=rs.slice().sort((a,b)=>b[C.ts]-a[C.ts]);TRLIST=sorted;\n  let h='<h3>Сделки <span class=\"mut small\" style=\"font-weight:400\">— нажми на сделку, чтобы увидеть график цены именно по ней</span></h3><div class=\"bar\"><button data-act=\"csv\">Скачать CSV (все '+rs.length+' строк со всеми показателями)</button></div>';\n  h+='<div class=\"tw\"><table><thead><tr><th class=\"l ns\">Время</th><th class=\"l ns\">Ячейка</th><th class=\"l ns\">Монета</th><th class=\"l ns\">Сторона</th><th class=\"ns\">Цена</th><th class=\"l ns\">Итог</th><th class=\"ns\">z</th><th class=\"ns\">до конца, с</th></tr></thead><tbody>';\n  sorted.slice(0,S.tradeN).forEach((r,i)=>{\n    const k=r[XK],ro=roiOf(r);\n    const res=k==='cr'?'обвал, продали '+sgn(ro*100,0)+'%':k==='sl'?'стоп '+sgn(ro*100,0)+'%':(k==='tp'?'тейк '+sgn(ro*100,0)+'%':(k==='add'?(r[C.won]?'победа с добором ':'проигрыш с добором ')+sgn(ro*100,0)+'%':(r[C.won]?'победа '+sgn(ro*100,0)+'%':'проигрыш −100%')));\n    h+='<tr class=\"click\" data-act=\"trade\" data-k=\"'+i+'\"><td class=\"l\">'+tz(r[C.ts])+'</td><td class=\"l\">'+esc(D.combos[r[C.combo]])+'</td><td class=\"l\">'+esc(COIN_SHORT[D.coins[r[C.coin]]]||D.coins[r[C.coin]])+'</td><td class=\"l\">'+(r[C.side]?'Down':'Up')+'</td><td>'+fmt(r[CI.px],3)+'</td><td class=\"l '+(ro>0?'pos':'neg')+'\">'+res+'</td><td>'+fmt(r[CI.z],2)+'</td><td>'+fmt(r[CI.sec],0)+'</td></tr>';});\n  h+='</tbody></table></div>';\n  if(rs.length>S.tradeN)h+='<div class=\"bar\"><button data-act=\"moreT\">Показать ещё 200</button><span class=\"mut small\">показано '+Math.min(S.tradeN,rs.length)+' из '+rs.length+'</span></div>';\n  return h;\n}\nfunction downloadCsv(rs){\n  const head=D.idCols.concat(COLS.map(c=>c.k)),lines=[head.join(',')];\n  rs.forEach(r=>{lines.push(r.slice(0,head.length).map((v,i)=>{if(v===null)return '';if(i===C.coin)return D.coins[v];if(i===C.idea)return D.ideas[v];if(i===C.combo)return '\"'+String(D.combos[v]).replace(/\"/g,'\"\"')+'\"';if(i===C.ts)return new Date(v*1000).toISOString();return v;}).join(','));});\n  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\\n')],{type:'text/csv;charset=utf-8'}));a.download='lab-trades.csv';document.body.appendChild(a);a.click();setTimeout(()=>document.body.removeChild(a),500);\n}\n\n// ---------- АВТОПОДБОР ФИЛЬТРОВ ----------\n// Правила ищутся на первых 60% сделок (по времени) и проверяются на последних 40%, которые при поиске не использовались.\nfunction ruleText(r){\n  return r.conds.map(c=>{const nf=NUMF_BY[c.col];const d=nf?nf.d:2;const lab=nf?nf.label:c.col;\n    if(c.lo!==null&&c.hi!==null){return c.lo===c.hi?lab+' = '+fmt(c.lo,d):lab+' от '+fmt(c.lo,d)+' до '+fmt(c.hi,d);}\n    return c.lo!==null?lab+' ≥ '+fmt(c.lo,d):lab+' ≤ '+fmt(c.hi,d);}).join('  И  ');\n}\n// ---------- карточка стратегии ----------\nfunction renderDetail(){\n  const rs=selRows();\n  const st=stats(rs),hv=halves(rs);\n  const backL={top:'← к лучшим стратегиям',fav:'← к избранным',chain:'← к согласиям'}[S.back]||'← к списку';\n  const ttl=S.sel.title||BY[S.sel.by].name(S.sel.key);\n  let h='<div class=\"card\"><div class=\"bar\" style=\"margin:0\"><button data-act=\"back\">'+backL+'</button><b style=\"font-size:16px\">'+esc(ttl)+'</b>'+(S.sel.favId?'<button data-act=\"favex\" title=\"запомнить текущие тейк/стоп/добор и умные условия для этого избранного\">💾 запомнить выходы</button><button data-act=\"favdel\" data-id=\"'+esc(S.sel.favId)+'\">★ убрать из избранного</button>':'<button data-act=\"favsave\">⭐ В избранное</button>')+'</div>';\n  h+='<div class=\"bar\" style=\"margin:6px 0 0\"><button data-act=\"flip\"'+(S.sel.flip?' style=\"border-color:var(--bad);color:var(--bad)\"':'')+'>🔄 '+(S.sel.flip?'Вернуть как есть':'Перевернуть (торговать наоборот)')+'</button><span class=\"mut small\">'+(S.sel.flip?'':'проверка: что было бы, если бы на каждом входе мы покупали противоположную сторону')+'</span></div>';\n  if(S.sel.flip)h+='<div class=\"note warn\"><b>🔄 Показана обратная торговля.</b> На каждом входе стратегии мы покупаем <b>противоположный</b> токен по цене ≈ 1 − bid нашей стороны (то есть с учётом спреда). Выигрыш — когда оригинал проиграл. График пути токена после входа здесь недоступен. Это приблизительный расчёт по записанным ценам, не реальная торговля.</div>';\n  if(S.sel.favId)h+='<div class=\"note small\">Эта выборка считается со своими фильтрами избранной (они указаны в списке избранных); фильтры сверху на неё не действуют, кроме периода.</div>';\n  h+=entryPanel(rs);\n  h+=exPanel(rs);\n  h+=smartPanel(rs);\n  h+='<div class=\"kpis\">';\n  const kp=(v,l,c)=>'<div class=\"kpi\"><b class=\"'+(c||'')+'\">'+v+'</b><span>'+l+'</span></div>';\n  h+=kp(st.n,'сделок ('+st.mk+' рынков)')+kp(pct(st.wr),'побед ('+st.w+')')+kp(fmt(st.apx,3),'средняя цена входа')+kp(sgn(st.edge*100,1)+' п.п.','Edge (побед − цена)',cls(st.edge))+kp(money(st.roi*st.n*S.stake),'прибыль на ставку $'+S.stake,cls(st.roi))+kp(sgn(st.roi*100,1)+'%','ROI',cls(st.roi))+kp(pct(st.lo),'нижняя граница побед ('+st.verdict+')')+(hv?kp(sgn(hv[0]*100,1)+'% / '+sgn(hv[1]*100,1)+'%','ROI 1-й / 2-й половины',(hv[0]>0&&hv[1]>0)?'pos':''):'');\n  const sq=seqInfo(rs);\n  h+=kp(sq.wmode?sq.wmode+' подряд':'—','самый частый винстрик'+(sq.wmode?' ('+sq.wmodeN+' раз)':''))+kp(sq.wmax||'—','самый длинный винстрик'+(sq.wruns?' (в среднем '+fmt(sq.wavg,1)+', типичный '+sq.wmed+')':''))+kp(sq.lmax,'макс. проигрышей подряд')+kp(sq.smooth==null?'—':Math.round(sq.smooth*100)+'%','ровность роста (100% — идеальная прямая вверх)');\n  h+='</div>';\n  if(sq.dist.length){const top=sq.dist.slice().sort((x,y)=>y[1]-x[1]||y[0]-x[0]).slice(0,8);h+='<div class=\"small mut\" style=\"margin:4px 0\">Серии побед подряд — длина × сколько раз такая была: '+top.map(e=>'<b>'+e[0]+'</b> × '+e[1]).join(' · ')+(sq.dist.length>8?' · …':'')+'</div>';}\n  if(!S.one&&st.n>st.mk*1.3)h+='<div class=\"note warn\"><b>Сделки повторяются по рынкам:</b> '+st.n+' сделок на '+st.mk+' рынков. Надёжность (нижняя граница, вердикт) и прибыль завышены. Включи «один вход на рынок» в списке стратегий.</div>';\n  if(st.n<30)h+='<div class=\"note warn\">Меньше 30 сделок — смотри как на описание, а не как на вывод.</div>';\n  const SEC=[['s-cum','📈 Кумулятив'],['s-path','📊 Цена после входа'],['s-loss','📉 Проигрыши'],['s-win','📈 Победы'],['s-cdl','🕯 Свеча'],['s-bk','🧮 По показателям'],['s-days','📅 Дни'],['s-tr','🧾 Сделки']];\n  h+='<div class=\"snav\">'+SEC.map(x=>'<button data-act=\"jump\" data-id=\"'+x[0]+'\">'+x[1]+'</button>').join('')+'</div>';\n  h+='<div class=\"sec\" id=\"s-cum\">'+cumChart(rs)+'</div><div class=\"sec\" id=\"s-path\">'+pathChart(rs)+'</div><div class=\"sec\" id=\"s-loss\">'+lossBlock()+'</div><div class=\"sec\" id=\"s-win\">'+winBlock()+'</div><div class=\"sec\" id=\"s-cdl\">'+candleBlock()+'</div><div class=\"sec\" id=\"s-bk\">'+bucketTable(rs)+'</div>';\n  h+='<div class=\"sec\" id=\"s-days\">'+dayTable(rs)+'</div><div class=\"sec\" id=\"s-tr\">'+tradesTable(rs)+'</div></div>';\n  return h;\n}\n\nfunction renderHelp(){\n  return '<div class=\"card\"><h3>Как читать</h3><div class=\"small\"><p><b>Побед</b> — доля выигранных сделок. На малом числе сделок она обманывает: 3 из 3 это не 100% навсегда.</p><p><b>Нижн. гр.</b> — осторожная оценка доли побед (95%). Сравнивай её со <b>средней ценой входа</b>: цена 0.95 значит, что нужно выигрывать больше 95 из 100 сделок, чтобы не быть в минусе. Если нижняя граница выше цены — ✅, плюс доказан. Если ниже — ⚠️, пока не доказан.</p><p><b>Edge</b> — побед минус цена в п.п. Размер преимущества, но без поправки на малую выборку.</p><p><b>Прибыль</b> — сколько получилось бы со ставкой из поля «ставка $». При дорогих входах (0.95+) победа даёт копейки, а проигрыш стоит всю ставку.</p><p><b>Устойчивость</b> — ROI первой и второй половины периода. Если одна половина в плюсе, а другая в минусе, правило, вероятно, случайное.</p><p><b>Подбор фильтров</b> — перебирает условия на первых 60% сделок и проверяет на последних 40%. Это защита от подгонки: правило, найденное перебором, редко держится на новых данных. Смотри на строку «Проверка».</p></div><div class=\"bar\"><button data-act=\"helpclose\">Закрыть</button></div></div>';\n}\n\n// ---------- ВКЛАДКА «ЛУЧШИЕ СТРАТЕГИИ» ----------\nconst DAYS=86400;\nconst dayOf=ts=>Math.floor(ts/DAYS);\nconst dStr=d=>new Date(d*DAYS*1000).toISOString().slice(0,10);\nlet TOPLO=0,TOPND=0;\nfunction dataDayBounds(){\n  const m=D.meta||{};let a=m.firstTs?dayOf(m.firstTs/1000):null,b=m.lastTs?dayOf(m.lastTs/1000):null;\n  if(a===null||b===null){a=Infinity;b=-Infinity;for(let i=0;i<N;i++){const d=dayOf(ROWS[i][C.ts]);if(d<a)a=d;if(d>b)b=d;}}\n  if(!isFinite(a)||!isFinite(b))return[0,0];\n  return[a,b];\n}\nfunction dayRange(){\n  const ab=dataDayBounds(),a=ab[0],b=ab[1],T=S.top;let lo=a,hi=b;\n  if(T.trim&&b-a>=3){lo=a+1;hi=b-1;}\n  if(S.dFrom){const t=Date.parse(S.dFrom+'T00:00:00Z');if(isFinite(t))lo=dayOf(t/1000);}\n  if(S.dTo){const t=Date.parse(S.dTo+'T00:00:00Z');if(isFinite(t))hi=dayOf(t/1000);}\n  if(hi<lo){lo=a;hi=b;}\n  return[lo,hi];\n}\n// mode: 'ms' — один вход на (рынок, сторона); 'm' — один на рынок (как в боте); 'none' — все сделки\nfunction prepGroup(rs,lo,nD,mode,noGoal){\n  let a=rs.slice().sort((x,y)=>x[C.ts]-y[C.ts]);\n  if(mode!=='none'){\n    const seen=new Set(),o=[];\n    for(const r of a){const k=mode==='m'?r[C.mk]:r[C.mk]*2+r[C.side];if(seen.has(k))continue;seen.add(k);o.push(r);}\n    a=o;\n  }\n  if(!noGoal)a=cutAll(a);\n  const g={rows:a,n:a.length,w:0,px:0,roi:0,dRoi:new Float64Array(nD),dN:new Int32Array(nD),dd:0,streak:0,mk:0};\n  let cum=0,peak=0,cur=0;const mk=new Set();\n  for(const r of a){\n    const won=r[C.won],p=r[CI.px],ro=roiOf(r);\n    g.w+=won;g.px+=p;g.roi+=ro;\n    const d=dayOf(r[C.ts])-lo;\n    if(d>=0&&d<nD){g.dRoi[d]+=ro;g.dN[d]++;}\n    cum+=ro;if(cum>peak)peak=cum;if(peak-cum>g.dd)g.dd=peak-cum;\n    if(won)cur=0;else{cur++;if(cur>g.streak)g.streak=cur;}\n    mk.add(r[C.mk]);\n  }\n  g.mk=mk.size;\n  g.seq=seqInfo(a,true);\n  return g;\n}\nfunction metrics(g,nD,stake){\n  const n=g.n,wr=n?g.w/n:0,apx=n?g.px/n:0,wl=wilson(g.w,n);\n  let plus=0,minus=0,act=0,worst=Infinity,best=-Infinity;\n  const k=nD>=5?Math.max(2,Math.round(nD*0.6)):nD;\n  let trU=0,teU=0,teMinus=0,teN=0;\n  for(let d=0;d<nD;d++){\n    const v=g.dRoi[d]*stake;\n    if(g.dN[d])act++;\n    if(v>1e-9)plus++;else if(v<-1e-9)minus++;\n    if(v<worst)worst=v;if(v>best)best=v;\n    if(d<k)trU+=v;else{teU+=v;teN+=g.dN[d];if(v<-1e-9)teMinus++;}\n  }\n  if(!isFinite(worst)){worst=0;best=0;}\n  const usd=g.roi*stake,usdd=nD?usd/nD:0;\n  let verdict='мало';if(n>=30)verdict=wl[0]>apx?'✅':(wl[1]<apx?'❌':'⚠️');\n  const hasTest=nD>=5&&k<nD;\n  return{seq:g.seq,g:g,n:n,w:g.w,wr:wr,apx:apx,edge:wr-apx,lo:wl[0],verdict:verdict,roi:n?g.roi/n:0,usd:usd,usdd:usdd,plus:plus,minus:minus,act:act,empty:nD-act,cover:nD?act/nD:0,worst:worst,best:best,tpd:nD?n/nD:0,dd:g.dd*stake,streak:g.streak,mk:g.mk,\n    train:k?trU/k:0,test:hasTest?{usdd:teU/(nD-k),minus:teMinus,n:teN,days:nD-k}:null,\n    oosOk:hasTest&&teU>0&&teN>=3,\n    stakeNeed:(g.roi>0&&nD)?S.top.goal/(g.roi/nD):null};\n}\nconst topGroupCache={};\nfunction getGroups(by,lo,hi){\n  const key=JSON.stringify([S.flt,S.dFrom,S.dTo,S.one,by,lo,hi,S.goalP,S.goalL,S.stake]);\n  const c=topGroupCache[by];if(c&&c.key===key)return c.groups;\n  const nD=hi-lo+1,kf=BY[by].key,m=new Map();\n  for(const r of rowsF){const d=dayOf(r[C.ts]);if(d<lo||d>hi)continue;const k=kf(r);let a=m.get(k);if(!a){a=[];m.set(k,a);}a.push(r);}\n  const groups=[];\n  m.forEach((rs,k)=>{const g=prepGroup(rs,lo,nD,S.one?'ms':'none');g.key=k;groups.push(g);});\n  topGroupCache[by]={key:key,groups:groups};\n  return groups;\n}\nfunction itemsOf(groups,by,nD,stake){\n  return groups.map(g=>{const m=metrics(g,nD,stake);m.key=g.key;m.by=by;m.name=BY[by].name(g.key);if(by==='cellcoin')m.coin=+String(g.key).split('|')[2];return m;});\n}\nconst TOP_SORTS={usdd:['Прибыль в день',x=>x.usdd],worst:['Худший день',x=>x.worst],wr:['Винрейт',x=>x.wr],tpd:['Сделок в день',x=>x.tpd],test:['Проверка ($ в день)',x=>x.test?x.test.usdd:-1e9],edge:['Edge',x=>x.edge],roi:['ROI на сделку',x=>x.roi],smooth:['Ровность роста',x=>x.seq&&x.seq.smooth!=null?x.seq.smooth:-1],wmode:['Частый винстрик',x=>x.seq?x.seq.wmode:0]};\nfunction critBad(x,T,nD){\n  const bad=[];\n  if(x.usdd<T.goal)bad.push('прибыль '+money(x.usdd)+'/день < $'+T.goal);\n  if(x.minus>T.maxLoss)bad.push('убыточных дней: '+x.minus);\n  if(x.cover*100<T.cover)bad.push('торговала в '+x.act+' из '+nD+' дн.');\n  if(x.n<T.minN)bad.push('сделок '+x.n+' < '+T.minN);\n  if(T.needOos&&!x.oosOk)bad.push('на проверке не в плюсе');\n  if(T.minSm>0&&!(x.seq&&x.seq.smooth!=null&&x.seq.smooth*100>=T.minSm))bad.push('ровность роста '+(x.seq&&x.seq.smooth!=null?Math.round(x.seq.smooth*100)+'%':'—')+' < '+T.minSm+'%');\n  return bad;\n}\nfunction dayBars(g,stake,w,h){\n  const n=g.dRoi.length;if(!n)return'';\n  let mx=0;for(let i=0;i<n;i++){const a=Math.abs(g.dRoi[i]*stake);if(a>mx)mx=a;}\n  if(mx<1e-9)mx=1;\n  const bw=(w-2)/n,zero=h/2;\n  let s='<svg class=\"spark\" viewBox=\"0 0 '+w+' '+h+'\" width=\"'+w+'\" height=\"'+h+'\" role=\"img\"><line x1=\"0\" x2=\"'+w+'\" y1=\"'+zero+'\" y2=\"'+zero+'\" stroke=\"var(--line)\"/>';\n  for(let i=0;i<n;i++){\n    const v=g.dRoi[i]*stake,x=1+i*bw,ww=Math.max(1.5,bw-(bw>6?2:1));\n    if(!g.dN[i]){s+='<rect x=\"'+x.toFixed(1)+'\" y=\"'+(zero-1)+'\" width=\"'+ww.toFixed(1)+'\" height=\"2\" fill=\"var(--mut)\" opacity=\".45\"><title>'+dStr(TOPLO+i)+': сделок не было</title></rect>';continue;}\n    const bh=Math.max(2,Math.abs(v)/mx*(h/2-2));\n    s+='<rect x=\"'+x.toFixed(1)+'\" y=\"'+(v>=0?zero-bh:zero).toFixed(1)+'\" width=\"'+ww.toFixed(1)+'\" height=\"'+bh.toFixed(1)+'\" rx=\"1.5\" fill=\"'+(v>=0?'var(--good)':'var(--bad)')+'\"><title>'+dStr(TOPLO+i)+': '+money(v)+' ('+g.dN[i]+' сд.)</title></rect>';\n  }\n  return s+'</svg>';\n}\nconst MEDAL=['🥇','🥈','🥉'];\nfunction topTable(list,id,opts){\n  opts=opts||{};const T=S.top,show=opts.limit||T.show[id]||8,stake=S.stake,nD=TOPND;\n  const sw=Math.max(80,Math.min(220,nD*14));\n  let h='<div class=\"tw\"><table><thead><tr><th class=\"l ns\">#</th><th class=\"l ns\">Стратегия</th><th class=\"ns\">$ в день</th><th class=\"l ns\">По дням</th><th class=\"l ns\" title=\"накопленная прибыль по каждой сделке\">Накопленная</th><th class=\"ns\" title=\"дней в плюсе / в минусе / без сделок\">+ / − / пусто</th><th class=\"ns\">Худший день</th><th class=\"ns\">Сделок/день</th><th class=\"ns\">Побед · цена</th><th class=\"l ns\">Вердикт</th><th class=\"ns\" title=\"самая частая длина серии побед подряд / самая длинная серия\">Винстрик (частый / макс)</th><th class=\"ns\" title=\"насколько кумулятивная прибыль похожа на ровную линию вверх: 100% — идеальная прямая, 0% — нет роста\">Ровность роста</th><th class=\"ns\" title=\"последние ~40% дней периода: поиск их не видел\">Проверка</th>'+(opts.head?'<th class=\"l ns\">'+opts.head+'</th>':'')+(opts.extra&&!opts.head?'<th class=\"ns\"></th>':'')+'</tr></thead><tbody>';\n  list.slice(0,show).forEach((x,i)=>{\n    const t=x.test?'<span class=\"'+cls(x.test.usdd)+'\">'+money(x.test.usdd)+'/д</span>'+(x.test.minus?' <span class=\"neg\">('+x.test.minus+' дн. в минусе)</span>':''):'—';\n    const attrs=opts.attrs?opts.attrs(x):' data-act=\"opentop\" data-by=\"'+x.by+'\" data-k=\"'+esc(x.key)+'\"';\n    const star=(opts.star===false)?'':'<button class=\"star\" title=\"В избранное (сохранятся и текущие фильтры сверху)\" data-act=\"favadd\" data-by=\"'+x.by+'\" data-k=\"'+esc(x.key)+'\">☆</button> ';\n    h+='<tr class=\"click\"'+attrs+'><td class=\"l\">'+(i<3&&!opts.nomedal?MEDAL[i]:(i+1))+'</td><td class=\"l nm\">'+star+esc(x.name)+(opts.sub?'<div class=\"mut small\" style=\"font-weight:400\">'+opts.sub(x)+'</div>':'')+'</td><td class=\"'+cls(x.usdd)+'\"><b>'+money(x.usdd)+'</b></td><td class=\"l\">'+dayBars(x.g,stake,sw,30)+'</td><td class=\"l\">'+cumSpark(x.g.rows,90,30)+'</td><td><span class=\"pos\">'+x.plus+'</span> / <span class=\"'+(x.minus?'neg':'mut')+'\">'+x.minus+'</span> / <span class=\"mut\">'+x.empty+'</span></td><td class=\"'+cls(x.worst)+'\">'+money(x.worst)+'</td><td>'+fmt(x.tpd,1)+'</td><td>'+pct(x.wr)+' · '+fmt(x.apx,3)+'</td><td class=\"l\">'+x.verdict+'</td><td>'+(x.seq&&x.seq.wmode?x.seq.wmode+' <span class=\"mut small\">×'+x.seq.wmodeN+'</span> / '+x.seq.wmax:'—')+'</td><td>'+(x.seq&&x.seq.smooth!=null?Math.round(x.seq.smooth*100)+'%':'—')+'</td><td>'+t+'</td>'+(opts.extra?'<td class=\"l small\">'+opts.extra(x)+'</td>':'')+'</tr>';\n  });\n  h+='</tbody></table></div>';\n  if(list.length>show)h+='<div class=\"bar\"><button data-act=\"topmore\" data-id=\"'+id+'\">Показать ещё 10</button><span class=\"mut small\">показано '+Math.min(show,list.length)+' из '+list.length+'</span></div>';\n  return h;\n}\nfunction topSection(id,title,sub,list,opts){\n  let h='<div class=\"card top\"><div class=\"th\"><b>'+title+'</b> <span class=\"mut small\">'+sub+'</span></div>';\n  if(!list.length)h+='<div class=\"mut small\" style=\"padding:6px 2px\">Ничего не нашлось по этому признаку.</div>';\n  else h+=topTable(list,id,opts);\n  return h+'</div>';\n}\n// ----- команда -----\nfunction teamMetrics(members,nD,stake){\n  const arrs=members.map(m=>m.g.rows);\n  const rows=Array.prototype.concat.apply([],arrs);\n  const g=prepGroup(rows,TOPLO,nD,'m',true);\n  const m=metrics(g,nD,stake);m.raw=rows.length;return m;\n}\nfunction buildTeam(pool,K,nD,stake){\n  const sel=[];let cur=null,curObj=-Infinity;\n  const objOf=m=>{let neg=0;for(let d=0;d<nD;d++){const v=m.g.dRoi[d]*stake;if(v<0)neg+=v;}return m.usdd+(nD?neg/nD:0);};\n  while(sel.length<K){\n    let bi=-1,bm=null,bo=curObj;\n    for(let i=0;i<pool.length;i++){\n      if(sel.indexOf(pool[i])>=0)continue;\n      const m=teamMetrics(sel.concat([pool[i]]),nD,stake),o=objOf(m);\n      if(o>bo+1e-9){bo=o;bi=i;bm=m;}\n    }\n    if(bi<0)break;\n    sel.push(pool[bi]);cur=bm;curObj=bo;\n  }\n  if(!sel.length)return null;\n  const contrib=sel.map((s,i)=>{if(sel.length<2)return cur.usdd;const w=teamMetrics(sel.filter((_,j)=>j!==i),nD,stake);return cur.usdd-w.usdd;});\n  return{members:sel,m:cur,contrib:contrib};\n}\nfunction renderTeam(pool,strictN){\n  const T=S.top,stake=S.stake,nD=TOPND;\n  let h='<div class=\"card top\"><div class=\"th\"><b>👥 Команда стратегий</b> <span class=\"mut small\">подбирает набор, который вместе даёт больше всего прибыли в день и меньше всего убыточных дней</span></div>';\n  h+='<div class=\"bar\"><label class=\"small\">Сколько стратегий в команде <select id=\"tp_team\">'+[2,3,4].map(k=>'<option value=\"'+k+'\"'+(T.team===k?' selected':'')+'>'+k+'</option>').join('')+'</select></label><span class=\"mut small\">берём из '+(strictN>=T.team?'подошедших под условия':'самых прибыльных (условия не прошёл никто)')+'; на одном рынке торгует одна — как бот</span></div>';\n  if(pool.length<2){return h+'<div class=\"note\">Для команды нужно хотя бы 2 подходящих варианта.</div></div>';}\n  const tm=buildTeam(pool,T.team,nD,stake);\n  if(!tm)return h+'<div class=\"note\">Не получилось собрать команду.</div></div>';\n  const m=tm.m;\n  h+='<div class=\"kpis\">'+kp(money(m.usdd),'прибыль в день на ставке $'+stake,cls(m.usdd))+kp('<span class=\"pos\">'+m.plus+'</span> / <span class=\"'+(m.minus?'neg':'')+'\">'+m.minus+'</span> / '+m.empty,'дней плюс / минус / пусто')+kp(money(m.worst),'худший день',cls(m.worst))+kp(m.n,'сделок ('+fmt(m.tpd,1)+' в день)')+kp(pct(m.wr)+' · '+fmt(m.apx,3),'побед · средняя цена')+kp('−$'+fmt(m.dd,2),'макс. просадка')+kp(m.streak,'проигрышей подряд (макс.)')+'</div>';\n  h+='<div style=\"margin:4px 0 10px\">'+dayBars(m.g,stake,Math.max(260,Math.min(640,nD*40)),64)+'<div class=\"mut small\">общая прибыль по дням (зелёный — плюс, красный — минус)</div></div>';\n  h+='<div class=\"tw\"><table><thead><tr><th class=\"l ns\">Стратегия</th><th class=\"ns\">$ в день (сама по себе)</th><th class=\"ns\">Вклад в команду</th><th class=\"ns\">Сделок</th><th class=\"l ns\">Вердикт</th></tr></thead><tbody>';\n  tm.members.forEach((x,i)=>{h+='<tr class=\"click\" data-act=\"opentop\" data-by=\"'+x.by+'\" data-k=\"'+esc(x.key)+'\"><td class=\"l nm\">'+esc(x.name)+'</td><td class=\"'+cls(x.usdd)+'\">'+money(x.usdd)+'</td><td class=\"'+cls(tm.contrib[i])+'\">'+money(tm.contrib[i])+'</td><td>'+x.n+'</td><td class=\"l\">'+x.verdict+'</td></tr>';});\n  h+='</tbody></table></div>';\n  const lost=m.raw-m.n;\n  h+='<div class=\"note small\">Сумма сделок отдельных стратегий — '+m.raw+', в команде — '+m.n+(lost>0?' ('+lost+' отпало: несколько стратегий вошли в один рынок, бот берёт только первую)':'')+'. Если «вклад» близок к нулю, эта стратегия почти повторяет остальные.</div></div>';\n  return h;\n}\nconst kp=(v,l,c)=>'<div class=\"kpi\"><b class=\"'+(c||'')+'\">'+v+'</b><span>'+l+'</span></div>';\n// ----- вкладка целиком -----\nfunction renderTop(){\n  const T=S.top,stake=S.stake;\n  const lr=dayRange(),lo=lr[0],hi=lr[1],nD=hi-lo+1;TOPLO=lo;TOPND=nD;\n  const q=S.q.trim().toLowerCase();\n  const groups=getGroups(T.by,lo,hi);\n  let items=itemsOf(groups,T.by,nD,stake);\n  if(q)items=items.filter(x=>x.name.toLowerCase().indexOf(q)>=0);\n  const total=items.length;\n  const sortF=(TOP_SORTS[T.sort]||TOP_SORTS.usdd)[1];\n  const evald=items.map(x=>({x:x,bad:critBad(x,T,nD)}));\n  const strict=evald.filter(e=>e.bad.length===0).map(e=>e.x).sort((a,b)=>sortF(b)-sortF(a));\n  const near=evald.filter(e=>e.bad.length===1&&e.x.usd>0).sort((a,b)=>b.x.usdd-a.x.usdd);\n  const base=items.filter(x=>x.n>=T.minN);\n  const pos=base.filter(x=>x.usd>0&&x.verdict!=='❌');\n  let h='<div class=\"card hero\"><div class=\"bar\" style=\"margin:0 0 8px\"><b style=\"font-size:17px\">🏆 Лучшие стратегии</b><span class=\"mut small\">автопоиск по всем вариантам: какие приносят прибыль каждый день</span></div>';\n  h+='<div class=\"goal\">';\n  h+='<label>Искать среди<select id=\"tp_by\">'+[['cell','ячеек (идея + ячейка)'],['idea','идей целиком'],['cellcoin','ячейка + монета'],['cellside','ячейка + сторона']].map(o=>'<option value=\"'+o[0]+'\"'+(T.by===o[0]?' selected':'')+'>'+o[1]+'</option>').join('')+'</select></label>';\n  h+='<label>Ставка на сделку, $<input type=\"number\" id=\"stake\" min=\"1\" value=\"'+stake+'\"></label>';\n  h+='<label>Цель: прибыль в день от, $<input type=\"number\" id=\"tp_goal\" min=\"0\" step=\"any\" value=\"'+T.goal+'\"></label>';\n  h+='<label>Убыточных дней не больше<input type=\"number\" id=\"tp_loss\" min=\"0\" value=\"'+T.maxLoss+'\"></label>';\n  h+='<label>Торговала в % дней не меньше<input type=\"number\" id=\"tp_cover\" min=\"0\" max=\"100\" value=\"'+T.cover+'\"></label>';\n  h+='<label>Мин. сделок за период<input type=\"number\" id=\"tp_minn\" min=\"1\" value=\"'+T.minN+'\"></label>';\n  h+='<label>Ровность роста не ниже, %<input type=\"number\" id=\"tp_sm\" min=\"0\" max=\"100\" value=\"'+(T.minSm||0)+'\"></label>';\n  h+='<label>Сортировать подошедшие по<select id=\"tp_sort\">'+Object.keys(TOP_SORTS).map(k=>'<option value=\"'+k+'\"'+(T.sort===k?' selected':'')+'>'+TOP_SORTS[k][0]+'</option>').join('')+'</select></label>';\n  h+='</div><div class=\"bar\" style=\"margin:8px 0 0\">';\n  h+='<label class=\"small\"><input type=\"checkbox\" id=\"one\"'+(S.one?' checked':'')+'> один вход на рынок</label>';\n  h+='<label class=\"small\" title=\"Первые и последние сутки в данных обычно неполные: в них нет сделок просто потому, что парсер ещё не работал или ещё не доработал.\"><input type=\"checkbox\" id=\"tp_trim\"'+(T.trim?' checked':'')+'> не считать неполные крайние дни</label>';\n  h+='<label class=\"small\" title=\"Показывать как «подошла» только стратегию, которая и на последних ~40% дней периода в плюсе.\"><input type=\"checkbox\" id=\"tp_oos\"'+(T.needOos?' checked':'')+'> требовать плюс на проверке (последние дни)</label>';\n  h+='<button data-act=\"topcsv\">Скачать все варианты в CSV</button></div></div>';\n  h+='<div class=\"kpis\"><div class=\"kpi\"><b>'+nD+'</b><span>дней в расчёте ('+dStr(lo)+' — '+dStr(hi)+', UTC)</span></div><div class=\"kpi\"><b>'+total+'</b><span>вариантов проверено</span></div><div class=\"kpi\"><b class=\"'+(strict.length?'pos':'neg')+'\">'+strict.length+'</b><span>подошли под все условия</span></div><div class=\"kpi\"><b>'+near.length+'</b><span>не хватает одного условия</span></div></div>';\n  if(nD<5)h+='<div class=\"note warn\">В расчёте всего <b>'+nD+'</b> дн. Фраза «прибыль каждый день» на таком коротком отрезке почти ничего не доказывает, а колонка «Проверка» не считается (нужно хотя бы 5 дней).</div>';\n  h+='<div class=\"note warn small\"><b>Как не обмануться.</b> Это поиск лучшего по прошлому среди '+total+' вариантов: часть найдётся просто от везения, чем больше вариантов, тем больше «идеальных» случайно. Доверия добавляют три вещи: колонка «Проверка» (последние ~40% дней в плюсе), ✅ в «Вердикте» и то, что соседние ячейки тоже в плюсе. Настоящий тест — следующая неделя новых данных (фильтр «Период» вверху).</div>';\n  // команда\n  const pool=(strict.length>=T.team?strict:pos.slice().sort((a,b)=>b.usdd-a.usdd)).slice(0,T.by==='idea'?12:24);\n  h+=renderTeam(pool,strict.length);\n  // подошедшие\n  h+=topSection('strict','✅ Подходят под все мои условия','прибыль в день ≥ $'+T.goal+', убыточных дней ≤ '+T.maxLoss+', торговала ≥ '+T.cover+'% дней, сделок ≥ '+T.minN+(T.needOos?', плюс на проверке':''),strict,{extra:x=>x.stakeNeed?'ставка для цели ≈ $'+fmt(x.stakeNeed,1):'',head:'Для цели в $'+T.goal+'/день'});\n  if(strict.length<8){\n    const nl=near.map(e=>{e.x.__bad=e.bad[0];return e.x;});\n    h+=topSection('near','🔶 Почти подошли','не хватает ровно одного условия — смотри последнюю колонку',nl,{head:'Чего не хватает',extra:x=>esc(x.__bad),nomedal:true});\n  }\n  // топы\n  h+=topSection('usd','💰 Больше всего $ в день','с положительным результатом и без ❌, сделок ≥ '+T.minN,pos.slice().sort((a,b)=>b.usdd-a.usdd));\n  h+=topSection('even','🛡 Самые ровные по дням','меньше всего убыточных дней, затем лучший «худший день»; торговали минимум в половине дней',pos.filter(x=>x.cover>=0.5).sort((a,b)=>a.minus-b.minus||b.worst-a.worst||b.usdd-a.usdd));\n  h+=topSection('smooth','📈 Ровнее всего растут','кумулятивная ближе всего к прямой линии вверх (R² прямой), прибыль > 0, сделок ≥ '+Math.max(T.minN,30),pos.filter(x=>x.n>=Math.max(T.minN,30)&&x.seq&&x.seq.smooth!=null).sort((a,b)=>b.seq.smooth-a.seq.smooth),{head:'Ровность роста',extra:x=>Math.round(x.seq.smooth*100)+'%'});\n  h+=topSection('calm','😌 Самые спокойные психологически','короче всего серия проигрышей подряд (при ROI > 0.5%)',pos.filter(x=>x.roi>0.005).sort((a,b)=>a.streak-b.streak||b.wr-a.wr),{head:'Макс. серия минусов',extra:x=>x.streak+' подряд (−$'+fmt(x.streak*stake,0)+')'});\n  h+=topSection('freq','⚡ Самые частые прибыльные','больше всего сделок в день при ROI > 1%',pos.filter(x=>x.roi>0.01).sort((a,b)=>b.tpd-a.tpd));\n  h+=topSection('rare','💎 Редкие, но сильные','8–60 сделок и преимущество над ценой ≥ 8 п.п.: мало данных, смотри как на кандидата на минимальную ставку',items.filter(x=>x.n>=8&&x.n<=60&&x.edge>=0.08&&x.usd>0).sort((a,b)=>b.roi-a.roi),{head:'Edge',extra:x=>sgn(x.edge*100,1)+' п.п.'});\n  h+=topSection('proved','🔬 С доказательством (✅)','нижняя граница винрейта выше цены входа, отсортированы по запасу',items.filter(x=>x.verdict==='✅'&&x.usd>0).sort((a,b)=>(b.lo-b.apx)-(a.lo-a.apx)),{head:'Нижн. гр. − цена',extra:x=>sgn((x.lo-x.apx)*100,1)+' п.п.'});\n  h+=topSection('oos','🧪 Держатся на проверке','в плюсе и в первой части периода, и в последних ~40% дней',pos.filter(x=>x.oosOk&&x.train>0).sort((a,b)=>b.test.usdd-a.test.usdd));\n  // по монетам\n  const cc=T.by==='cellcoin'?items:itemsOf(getGroups('cellcoin',lo,hi),'cellcoin',nD,stake).filter(x=>!q||x.name.toLowerCase().indexOf(q)>=0);\n  const perCoin=[];\n  D.coins.forEach((c,ci)=>{cc.filter(x=>x.coin===ci&&x.n>=T.minN&&x.usd>0&&x.verdict!=='❌').sort((a,b)=>b.usdd-a.usdd).slice(0,2).forEach(x=>perCoin.push(x));});\n  h+=topSection('coin','🪙 Лучшие по каждой монете','по две лучшие ячейки для каждой монеты',perCoin);\n  h+='<div class=\"note small\">Как читать таблицу: «$ в день» — средняя прибыль за сутки на ставку из поля «ставка» (по всем дням периода, включая дни без сделок). «+ / − / пусто» — сколько суток закончилось в плюсе, в минусе и без единой сделки. Столбики — прибыль каждого дня: зелёный плюс, красный минус, серая точка — не было сделок. «Худший день» — самая слабая сутки. «Проверка» — прибыль в день на последних ~40% дней периода. Клик по строке открывает подробный разбор.</div>';\n  return h;\n}\nfunction downloadTopCsv(){\n  const lr=dayRange(),lo=lr[0],hi=lr[1],nD=hi-lo+1,T=S.top;\n  const items=itemsOf(getGroups(T.by,lo,hi),T.by,nD,S.stake);\n  const head=['стратегия','сделок','побед','винрейт','ср_цена','edge_пп','roi','прибыль_$','прибыль_в_день_$','дней_плюс','дней_минус','дней_пусто','худший_день_$','просадка_$','макс_серия_минусов','вердикт','проверка_$_в_день','проверка_дней_в_минусе','ставка_для_цели_$'];\n  const lines=[head.join(',')];\n  items.sort((a,b)=>b.usdd-a.usdd).forEach(x=>{lines.push(['\"'+x.name.replace(/\"/g,'\"\"')+'\"',x.n,x.w,x.wr.toFixed(4),x.apx.toFixed(4),(x.edge*100).toFixed(2),x.roi.toFixed(4),x.usd.toFixed(2),x.usdd.toFixed(2),x.plus,x.minus,x.empty,x.worst.toFixed(2),x.dd.toFixed(2),x.streak,x.verdict,x.test?x.test.usdd.toFixed(2):'',x.test?x.test.minus:'',x.stakeNeed?x.stakeNeed.toFixed(1):''].join(','));});\n  const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([lines.join('\\n')],{type:'text/csv;charset=utf-8'}));a.download='lab-top-strategies.csv';document.body.appendChild(a);a.click();setTimeout(()=>document.body.removeChild(a),500);\n}\nfunction renderTabs(){\n  const tb=(t,l)=>'<button class=\"tab'+(S.tab===t?' on':'')+'\" data-act=\"tab\" data-t=\"'+t+'\">'+l+'</button>';\n  return '<div class=\"tabs\">'+tb('an','📊 Разбор стратегий')+tb('top','🏆 Лучшие стратегии')+tb('fav','⭐ Избранные ('+FAVS.length+')')+tb('chain','🔗 Согласия')+'</div>';\n}\n// ---------- график накопленной прибыли (по каждой сделке) ----------\nconst CUMREG={};let cumSeq=0;\nfunction rowName(r){return (COIN_SHORT[D.coins[r[C.coin]]]||D.coins[r[C.coin]])+' '+(r[C.side]?'Down':'Up');}\nfunction cumSeries(rs,sorted){\n  const s=sorted?rs:rs.slice().sort((a,b)=>a[C.ts]-b[C.ts]);\n  const ys=new Array(s.length);let cum=0;\n  for(let i=0;i<s.length;i++){cum+=roiOf(s[i])*S.stake;ys[i]=cum;}\n  return{s:s,ys:ys};\n}\nfunction cumStats(sr){\n  let peak=0,dd=0,cur=0,mx=0,best=-Infinity,worst=Infinity;\n  for(let i=0;i<sr.s.length;i++){\n    const y=sr.ys[i];if(y>peak)peak=y;if(peak-y>dd)dd=peak-y;\n    const r=sr.s[i],v=roiOf(r)*S.stake;if(v>best)best=v;if(v<worst)worst=v;\n    if(r[C.won])cur=0;else{cur++;if(cur>mx)mx=cur;}\n  }\n  return{dd:dd,streak:mx,best:best,worst:worst};\n}\nfunction cumChart(rs,opt){\n  opt=opt||{};\n  const sr=cumSeries(rs),n=sr.s.length;\n  if(n<2)return '<div class=\"note\">Для графика нужно хотя бы 2 сделки.</div>';\n  const mode=S.cumMode;\n  const W=opt.w||920,H=opt.h||270,pl=58,pr=14,pt=14,pb=30;\n  const xs=new Array(n);\n  for(let i=0;i<n;i++)xs[i]=mode==='time'?sr.s[i][C.ts]:i;\n  const x0=xs[0],x1=xs[n-1];\n  let mn=0,mx=0;for(let i=0;i<n;i++){const y=sr.ys[i];if(y<mn)mn=y;if(y>mx)mx=y;}\n  if(mx-mn<0.5){mx+=0.25;mn-=0.25;}\n  const X=v=>pl+(W-pl-pr)*((v-x0)/((x1-x0)||1)),Y=v=>pt+(H-pt-pb)*(1-(v-mn)/(mx-mn));\n  let d='';\n  if(n<=6000){for(let i=0;i<n;i++)d+=(i?'L':'M')+X(xs[i]).toFixed(1)+' '+Y(sr.ys[i]).toFixed(1);}\n  else{\n    const b=Math.ceil(n/3000);let first=true;\n    for(let i=0;i<n;i+=b){\n      let lo=i,hi=i;\n      for(let j=i;j<Math.min(n,i+b);j++){if(sr.ys[j]<sr.ys[lo])lo=j;if(sr.ys[j]>sr.ys[hi])hi=j;}\n      const a=Math.min(lo,hi),c=Math.max(lo,hi);\n      d+=(first?'M':'L')+X(xs[a]).toFixed(1)+' '+Y(sr.ys[a]).toFixed(1);first=false;\n      if(c!==a)d+='L'+X(xs[c]).toFixed(1)+' '+Y(sr.ys[c]).toFixed(1);\n    }\n  }\n  const end=sr.ys[n-1],col=end>=0?'var(--good)':'var(--bad)';\n  let s='<svg class=\"cumsvg\" data-cum=\"c'+(cumSeq+1)+'\" viewBox=\"0 0 '+W+' '+H+'\" width=\"100%\" style=\"max-width:'+W+'px\" role=\"img\">';\n  for(let g=0;g<=4;g++){const v=mn+(mx-mn)*g/4,y=Y(v);s+='<line x1=\"'+pl+'\" x2=\"'+(W-pr)+'\" y1=\"'+y.toFixed(1)+'\" y2=\"'+y.toFixed(1)+'\" stroke=\"var(--line)\"/><text x=\"'+(pl-6)+'\" y=\"'+(y+4).toFixed(1)+'\" text-anchor=\"end\">'+(v>=0?'+':'−')+'$'+Math.abs(v).toFixed(Math.abs(v)>=100?0:1)+'</text>';}\n  s+='<line x1=\"'+pl+'\" x2=\"'+(W-pr)+'\" y1=\"'+Y(0).toFixed(1)+'\" y2=\"'+Y(0).toFixed(1)+'\" stroke=\"var(--mut)\" stroke-dasharray=\"4 3\"/>';\n  // границы суток\n  const marks=[];\n  for(let i=1;i<n;i++){const a=dayOf(sr.s[i-1][C.ts]),b=dayOf(sr.s[i][C.ts]);if(a!==b)marks.push([i,b]);}\n  const stride=Math.max(1,Math.ceil(marks.length/10));\n  marks.forEach((m,k)=>{const x=X(xs[m[0]]).toFixed(1);s+='<line x1=\"'+x+'\" x2=\"'+x+'\" y1=\"'+pt+'\" y2=\"'+(H-pb)+'\" stroke=\"var(--line)\" stroke-dasharray=\"2 4\"/>';if(k%stride===0)s+='<text x=\"'+x+'\" y=\"'+(H-10)+'\" text-anchor=\"middle\">'+dStr(m[1]).slice(5)+'</text>';});\n  s+='<path d=\"'+d+' L'+X(xs[n-1]).toFixed(1)+' '+Y(0).toFixed(1)+' L'+X(xs[0]).toFixed(1)+' '+Y(0).toFixed(1)+' Z\" fill=\"'+col+'\" opacity=\".09\"/>';\n  s+='<path d=\"'+d+'\" fill=\"none\" stroke=\"'+col+'\" stroke-width=\"1.8\" stroke-linejoin=\"round\"/>';\n  s+='<circle cx=\"'+X(xs[n-1]).toFixed(1)+'\" cy=\"'+Y(end).toFixed(1)+'\" r=\"3.5\" fill=\"'+col+'\"/>';\n  s+='<line class=\"cl\" x1=\"0\" x2=\"0\" y1=\"'+pt+'\" y2=\"'+(H-pb)+'\" stroke=\"var(--fg)\" stroke-width=\"1\" opacity=\".5\" style=\"display:none\"/></svg>';\n  const id='c'+(++cumSeq);\n  CUMREG[id]={s:sr.s,ys:sr.ys,xs:xs,x0:x0,x1:x1,W:W,pl:pl,pr:pr};\n  const cs=cumStats(sr);\n  let h='<div class=\"cum\"><div class=\"bar\" style=\"margin:0 0 4px\"><b>Накопленная прибыль по каждой сделке</b><span class=\"mut small\">ставка $'+S.stake+', все '+n+' сделок · ось X:</span>';\n  h+='<button class=\"tg'+(mode==='trade'?' on':'')+'\" data-act=\"cummode\" data-m=\"trade\">по сделкам</button><button class=\"tg'+(mode==='time'?' on':'')+'\" data-act=\"cummode\" data-m=\"time\">по времени</button></div>';\n  h+=s;\n  h+='<div class=\"cumtip small mut\">наведи курсор на график — увидишь каждую сделку</div>';\n  h+='<div class=\"small mut\">итог <b class=\"'+cls(end)+'\">'+money(end)+'</b> · макс. просадка −$'+cs.dd.toFixed(2)+' · проигрышей подряд (макс.) '+cs.streak+' · лучшая сделка '+money(cs.best)+' · худшая '+money(cs.worst)+'</div></div>';\n  return h;\n}\n// маленькая линия накопленной прибыли для таблиц\n\n\n// ---------- ПРОГРЕССИЯ СТАВКИ ПО ДНЯМ ----------\n// ---------- ПРОГНОЗ ВПЕРЁД (пролонгация кумулятивной) ----------\nconst PROJC={};\nfunction cumSpark(rows,w,h){\n  const n=rows.length;if(n<2)return '';\n  let cum=0;const ys=new Array(n);\n  for(let i=0;i<n;i++){cum+=roiOf(rows[i]);ys[i]=cum;}\n  let mn=0,mx=0;for(let i=0;i<n;i++){if(ys[i]<mn)mn=ys[i];if(ys[i]>mx)mx=ys[i];}\n  if(mx-mn<1e-9)mx=mn+1;\n  const step=Math.max(1,Math.ceil(n/(w*1.5)));\n  let d='';for(let i=0;i<n;i+=step){const x=(w-2)*i/(n-1)+1,y=2+(h-4)*(1-(ys[i]-mn)/(mx-mn));d+=(d?'L':'M')+x.toFixed(1)+' '+y.toFixed(1);}\n  const x=w-1,y=2+(h-4)*(1-(ys[n-1]-mn)/(mx-mn));d+='L'+x.toFixed(1)+' '+y.toFixed(1);\n  const z=2+(h-4)*(1-(0-mn)/(mx-mn));\n  return '<svg class=\"spark\" viewBox=\"0 0 '+w+' '+h+'\" width=\"'+w+'\" height=\"'+h+'\"><line x1=\"0\" x2=\"'+w+'\" y1=\"'+z.toFixed(1)+'\" y2=\"'+z.toFixed(1)+'\" stroke=\"var(--line)\"/><path d=\"'+d+'\" fill=\"none\" stroke=\"'+(ys[n-1]>=0?'var(--good)':'var(--bad)')+'\" stroke-width=\"1.6\"/></svg>';\n}\n\n// ---------- ИЗБРАННЫЕ ----------\nconst FAV_KEY='lab-favs-v2';\nconst FAV_DEFAULT=[\n  {id:'live-fair2',type:'cell',name:'fair2 — в торговле (σ120с, edge 2-4%, 0.93-0.96)',idea:'fair2',combo:'edge 2-4% / 60-120с / 0.93-0.96',flt:[],cats:{},live:'fair2'},\n  {id:'live-fair85',type:'cell',name:'fair85 = №1 — в торговле (σ120с, edge 4-6%, 0.85-0.90)',idea:'fair2',combo:'edge 4-6% / 60-120с / 0.85-0.90',flt:[{col:'sec',lo:null,hi:89},{col:'c10',lo:0,hi:0}],cats:{},live:'fair85'},\n  {id:'live-model93',type:'cell',name:'model93 = №3 — в торговле (Модель 1-1.5, 0.93-0.96)',idea:'model',combo:'сила 1-1.5 / 60-120с / 0.93-0.96',flt:[{col:'tb60',lo:0.48,hi:null}],cats:{},live:'model93'},\n  {id:'live-bot7b0',type:'cell',name:'bot7b0 — в торговле (профиль 7 + Binance против; приблизительно)',idea:'bot7',combo:null,flt:[{col:'bk',lo:0,hi:0}],cats:{},live:'bot7b0'},\n  {id:'u2',type:'cell',name:'№2 σ60с, edge 4-6%, 30-60с, 0.70-0.80',idea:'fair1',combo:'edge 4-6% / 30-60с / 0.70-0.80',flt:[],cats:{}},\n  {id:'u4',type:'cell',name:'№4 σ60с, edge <0, 120-180с, 0.60-0.70 + Coinbase/поток',idea:'fair1',combo:'edge <0 / 120-180с / 0.60-0.70',flt:[{col:'cbr',lo:3.44,hi:17.07}],cats:{}},\n  {id:'u5',type:'cell',name:'№5 σ60с, edge <0, 120-180с, 0.70-0.80 + 3 фильтра',idea:'fair1',combo:'edge <0 / 120-180с / 0.70-0.80',flt:[{col:'tb60',lo:0.15,hi:0.38},{col:'asz',lo:10,hi:49},{col:'rv2',lo:null,hi:0.28}],cats:{}},\n  {id:'n-ts1',type:'cell',name:'ТС1 · fair2, edge<0, 180-240с, ask 0.80-0.90, TP +15¢ / SL −20¢',idea:'fair2',combo:null,flt:[{col:'fe',lo:null,hi:-0.0001},{col:'sec',lo:180,hi:240},{col:'px',lo:0.8,hi:0.9}],cats:{},ex:{x:{tp:{on:true,v:15,u:'c'},sl:{on:true,v:20,u:'c'}}}},\n  {id:'n-ts1nd',type:'cell',name:'ТС1 без DOGE · fair2, edge<0, 180-240с, ask 0.80-0.90, TP +15¢ / SL −20¢',idea:'fair2',combo:null,flt:[{col:'fe',lo:null,hi:-0.0001},{col:'sec',lo:180,hi:240},{col:'px',lo:0.8,hi:0.9}],cats:{coin:['Bitcoin','Ethereum','Solana','XRP']},ex:{x:{tp:{on:true,v:15,u:'c'},sl:{on:true,v:20,u:'c'}}}},\n  {id:'n-ts1h',type:'cell',name:'ТС1 без выходов (держим до расчёта) — для сравнения',idea:'fair2',combo:null,flt:[{col:'fe',lo:null,hi:-0.0001},{col:'sec',lo:180,hi:240},{col:'px',lo:0.8,hi:0.9}],cats:{}},\n  {id:'n-ts2',type:'cell',name:'ТС2 · fair1, edge 4-6%, 60-120с, ask 0.80-0.85',idea:'fair1',combo:null,flt:[{col:'fe',lo:0.04,hi:0.0599},{col:'sec',lo:60,hi:120},{col:'px',lo:0.8,hi:0.85}],cats:{}},\n  {id:'n-ts3',type:'cell',name:'ТС3 · Модель, сила 1-3, 180-240с, ask 0.80-0.90',idea:'model',combo:null,flt:[{col:'z',lo:1,hi:3},{col:'sec',lo:180,hi:240},{col:'px',lo:0.8,hi:0.9}],cats:{}},\n  {id:'n-ts4a',type:'cell',name:'ТС4 · fair2, edge 0-4%, 60-180с, ask 0.80-0.90',idea:'fair2',combo:null,flt:[{col:'fe',lo:0,hi:0.0399},{col:'sec',lo:60,hi:180},{col:'px',lo:0.8,hi:0.9}],cats:{}},\n  {id:'n-ts4b',type:'cell',name:'ТС4 · fair1, edge 0-4%, 60-180с, ask 0.80-0.90',idea:'fair1',combo:null,flt:[{col:'fe',lo:0,hi:0.0399},{col:'sec',lo:60,hi:180},{col:'px',lo:0.8,hi:0.9}],cats:{}},\n  {id:'u6',type:'cell',name:'№6 σ60с, edge 2-4%, 120-180с, 0.70-0.80 + bid токена +0.48',idea:'fair1',combo:'edge 2-4% / 120-180с / 0.70-0.80',flt:[{col:'tb60',lo:0.48,hi:null}],cats:{}}\n];\nlet FAVS=[],FAV_REMOVED=[];\nfunction loadFavs(){\n  let saved=null;\n  try{const t=localStorage.getItem(FAV_KEY);if(t)saved=JSON.parse(t);}catch(e){}\n  if(saved&&Array.isArray(saved.favs)){FAVS=saved.favs;FAV_REMOVED=Array.isArray(saved.removed)?saved.removed:[];}\n  const have=new Set(FAVS.map(f=>f.id));\n  FAV_DEFAULT.forEach(d=>{if(!have.has(d.id)&&FAV_REMOVED.indexOf(d.id)<0)FAVS.push(JSON.parse(JSON.stringify(d)));});\n}\nfunction saveFavs(){try{localStorage.setItem(FAV_KEY,JSON.stringify({favs:FAVS,removed:FAV_REMOVED}));}catch(e){}}\nloadFavs();\n// настройки выходов/умных условий, которые запоминаются вместе с избранным\nfunction exSnap(){\n  const o={};\n  const x={};\n  if(X.tp.on)x.tp=JSON.parse(JSON.stringify(X.tp));\n  if(X.sl.on)x.sl=JSON.parse(JSON.stringify(X.sl));\n  if(X.add.on)x.add=JSON.parse(JSON.stringify(X.add));\n  if(Object.keys(x).length)o.x=x;\n  if(CR.on)o.cr=JSON.parse(JSON.stringify(CR));\n  if(RE.b.on||RE.c.on)o.re=JSON.parse(JSON.stringify(RE));\n  return Object.keys(o).length?o:null;\n}\nfunction exApply(ex){\n  X.tp.on=false;X.sl.on=false;X.add.on=false;CR.on=false;RE.b.on=false;RE.c.on=false;EN.on=false;\n  if(!ex)return;\n  if(ex.x){if(ex.x.tp)Object.assign(X.tp,ex.x.tp);if(ex.x.sl)Object.assign(X.sl,ex.x.sl);if(ex.x.add)Object.assign(X.add,ex.x.add);}\n  if(ex.cr)Object.assign(CR,ex.cr);\n  if(ex.re){Object.assign(RE.b,ex.re.b||{});Object.assign(RE.c,ex.re.c||{});}\n}\nfunction exText(ex){\n  if(!ex)return'';\n  const p=[];\n  if(ex.x&&ex.x.tp)p.push('TP '+ex.x.tp.v+({c:'¢',pct:'%',usd:'$'}[ex.x.tp.u]||''));\n  if(ex.x&&ex.x.sl)p.push('SL '+ex.x.sl.v+({c:'¢',pct:'%',usd:'$'}[ex.x.sl.u]||''));\n  if(ex.x&&ex.x.add)p.push('добор');\n  if(ex.cr)p.push('обвал '+ex.cr.h+'→'+ex.cr.l+'¢');\n  if(ex.re&&ex.re.b&&ex.re.b.on)p.push('вынос');\n  if(ex.re&&ex.re.c&&ex.re.c.on)p.push('дно');\n  return p.join(', ');\n}\nlet favIdSeq=Date.now();\nconst newFavId=()=>'f'+(favIdSeq++).toString(36);\nfunction fltText(flt,cats){\n  const parts=(flt||[]).map(f=>{\n    const nf=NUMF_BY[f.col],lab=nf?nf.label:f.col,d=nf?nf.d:2;\n    let t;\n    if(f.lo!==null&&f.lo!==undefined&&f.hi!==null&&f.hi!==undefined)t=f.lo===f.hi?lab+' = '+fmt(f.lo,d):lab+' '+fmt(f.lo,d)+'…'+fmt(f.hi,d);\n    else if(f.lo!==null&&f.lo!==undefined)t=lab+' ≥ '+fmt(f.lo,d);\n    else if(f.hi!==null&&f.hi!==undefined)t=lab+' ≤ '+fmt(f.hi,d);\n    else t=lab;\n    return (f.neg?'кроме: ':'')+t;\n  });\n  if(cats){\n    if(cats.coin&&cats.coin.length)parts.push('монета: '+cats.coin.map(c=>COIN_SHORT[c]||c).join('/'));\n    if(cats.side&&cats.side.length)parts.push('сторона: '+cats.side.map(x=>x?'Down':'Up').join('/'));\n    if(cats.wm&&cats.wm.length)parts.push('окно: '+cats.wm.join('/')+' мин');\n  }\n  return parts.join(' · ');\n}\n// ---- строки избранной ----\nlet IDX=null;\nfunction buildIdx(){\n  IDX={cell:new Map(),idea:new Map()};\n  for(const r of ROWS){\n    const k=r[C.idea]+'|'+r[C.combo];let a=IDX.cell.get(k);if(!a){a=[];IDX.cell.set(k,a);}a.push(r);\n    let b=IDX.idea.get(r[C.idea]);if(!b){b=[];IDX.idea.set(r[C.idea],b);}b.push(r);\n  }\n}\nfunction rowPred(flt,cats){\n  const num=(flt||[]).filter(f=>CI[f.col]!==undefined).map(f=>({ci:CI[f.col],lo:f.lo===undefined?null:f.lo,hi:f.hi===undefined?null:f.hi,neg:!!f.neg,nul:!!f.nul}));\n  const coinSet=cats&&cats.coin&&cats.coin.length?new Set(cats.coin.map(n=>D.coins.indexOf(n))):null;\n  const sideSet=cats&&cats.side&&cats.side.length?new Set(cats.side):null;\n  const wmSet=cats&&cats.wm&&cats.wm.length?new Set(cats.wm):null;\n  return r=>{\n    if(coinSet&&!coinSet.has(r[C.coin]))return false;\n    if(sideSet&&!sideSet.has(r[C.side]))return false;\n    if(wmSet&&!wmSet.has(r[C.wm]))return false;\n    for(let i=0;i<num.length;i++){\n      const f=num[i],v=r[f.ci];\n      if(v===null){if(f.nul)continue;return false;}\n      const inr=(f.lo===null||v>=f.lo)&&(f.hi===null||v<=f.hi);\n      if(f.neg?inr:!inr)return false;\n    }\n    return true;\n  };\n}\nfunction periodBounds(){\n  let tlo=null,thi=null;\n  if(S.dFrom){const t=Date.parse(S.dFrom+'T00:00:00Z');if(isFinite(t))tlo=t/1000;}\n  if(S.dTo){const t=Date.parse(S.dTo+'T00:00:00Z');if(isFinite(t))thi=t/1000+86400;}\n  return[tlo,thi];\n}\nconst periodCache={key:'',rows:null};\nfunction periodRows(){\n  const pb=periodBounds();if(pb[0]===null&&pb[1]===null)return ROWS;\n  const key=pb[0]+'|'+pb[1];\n  if(periodCache.key===key)return periodCache.rows;\n  const rows=ROWS.filter(r=>(pb[0]===null||r[C.ts]>=pb[0])&&(pb[1]===null||r[C.ts]<pb[1]));\n  periodCache.key=key;periodCache.rows=rows;return rows;\n}\n// «сырые» строки избранной ячейки (без дедупликации)\nfunction favRowsRaw(f){\n  if(!IDX)buildIdx();\n  const ii=D.ideas.indexOf(f.idea);if(ii<0)return[];\n  let base;\n  if(f.combo){const ci=D.combos.indexOf(f.combo);if(ci<0)return[];base=IDX.cell.get(ii+'|'+ci)||[];}\n  else base=IDX.idea.get(ii)||[];\n  const pb=periodBounds(),pred=rowPred(f.flt,f.cats);\n  return base.filter(r=>(pb[0]===null||r[C.ts]>=pb[0])&&(pb[1]===null||r[C.ts]<pb[1])&&pred(r));\n}\nfunction favRows(f){\n  if(f.type==='chain'){const res=chainCompute(f.steps,f.gap,periodRows());return res.chain;}\n  const rs=favRowsRaw(f);\n  return cutAll(S.one?dedupe(rs):rs);\n}\nfunction favRowsX(f){\n  const rs=favRows(f);\n  if(!f.ex||f.type==='chain')return rs;\n  const sv=exSnap(),en=EN.on;\n  exApply(f.ex);\n  try{return applyExit(applyRe(rs));}finally{exApply(sv);EN.on=en;}\n}\nfunction favSub(f){\n  let t='';\n  if(f.live)t+='<span class=\"badge live\">🟢 торгует: '+esc(f.live)+'</span> ';\n  if(f.type==='chain')t+='цепочка: '+esc(chainLabel(f.steps)+(f.gap?' · пауза ≤ '+f.gap+'с':''));\n  else{const ft=fltText(f.flt,f.cats);t+=esc((f.idea?ideaTitle(f.idea):'')+(f.combo?' · '+f.combo:'')+(ft?' · '+ft:'')+(f.ex?' · выходы: '+exText(f.ex):''));}\n  return t;\n}\n// ---- добавление в избранное ----\nfunction favFromKey(by,key){\n  const p=String(key).split('|');\n  const f={id:newFavId(),type:'cell',name:'',idea:null,combo:null,flt:[],cats:{}};\n  if(by==='idea'){f.idea=D.ideas[+p[0]];}\n  else if(by==='cell'||by==='cellcoin'||by==='cellside'){\n    f.idea=D.ideas[+p[0]];f.combo=D.combos[+p[1]];\n    if(by==='cellcoin')f.cats.coin=[D.coins[+p[2]]];\n    if(by==='cellside')f.cats.side=[+p[2]];\n  }else return null;\n  S.flt.forEach(x=>{\n    if(x.t==='num'&&CI[x.col]!==undefined)f.flt.push({col:x.col,lo:x.lo,hi:x.hi,neg:!!x.neg,nul:!!x.nul});\n    else if(x.t==='cat'&&x.vals.length){\n      if(x.f==='coin')f.cats.coin=(f.cats.coin||[]).concat(x.vals.map(i=>D.coins[i]));\n      else if(x.f==='side')f.cats.side=(f.cats.side||[]).concat(x.vals);\n      else if(x.f==='wm')f.cats.wm=x.vals.slice();\n    }\n  });\n  const nm=BY[by].name(key);\n  const ft=fltText(f.flt,f.cats);\n  f.name=nm+(ft?' + '+ft:'');\n  return f;\n}\nfunction addFav(f){\n  const nm=window.prompt('Название для избранного:',f.name);\n  if(nm===null)return false;\n  f.name=nm.trim()||f.name;\n  FAVS.push(f);saveFavs();return true;\n}\nfunction delFav(id){\n  const k=FAVS.findIndex(f=>f.id===id);if(k<0)return;\n  FAVS.splice(k,1);\n  if(FAV_DEFAULT.some(d=>d.id===id)&&FAV_REMOVED.indexOf(id)<0)FAV_REMOVED.push(id);\n  saveFavs();\n}\nfunction renderFav(){\n  const T=S.top,stake=S.stake;\n  const lr=dayRange(),lo=lr[0],hi=lr[1],nD=hi-lo+1;TOPLO=lo;TOPND=nD;\n  const items=[];\n  FAVS.forEach(f=>{\n    let rs=favRowsX(f).filter(r=>{const d=dayOf(r[C.ts]);return d>=lo&&d<=hi;});\n    const g=prepGroup(rs,lo,nD,'none',true);\n    const m=metrics(g,nD,stake);m.key=f.id;m.by='fav';m.name=f.name;m.fav=f;\n    items.push(m);\n  });\n  const sk=S.favSort;\n  if(sk==='usdd')items.sort((a,b)=>b.usdd-a.usdd);\n  else if(sk==='roi')items.sort((a,b)=>b.roi-a.roi);\n  else if(sk==='worst')items.sort((a,b)=>b.worst-a.worst);\n  else if(sk==='smooth')items.sort((a,b)=>((b.seq&&b.seq.smooth)||0)-((a.seq&&a.seq.smooth)||0));\n  let h='<div class=\"card hero\"><div class=\"bar\" style=\"margin:0 0 8px\"><b style=\"font-size:17px\">⭐ Избранные</b><span class=\"mut small\">стратегии, которые ты отметил: считаются со своими фильтрами; общий «Период» вверху учитывается</span></div>';\n  h+='<div class=\"bar\" style=\"margin:0\"><label class=\"small\">Ставка, $ <input type=\"number\" id=\"stake\" min=\"1\" value=\"'+stake+'\" style=\"width:70px\"></label>';\n  h+='<label class=\"small\">Сортировка <select id=\"fav_sort\">'+[['manual','как добавлены'],['usdd','по прибыли в день'],['roi','по ROI'],['smooth','по ровности роста'],['worst','по худшему дню']].map(o=>'<option value=\"'+o[0]+'\"'+(sk===o[0]?' selected':'')+'>'+o[1]+'</option>').join('')+'</select></label>';\n  h+='<label class=\"small\"><input type=\"checkbox\" id=\"one\"'+(S.one?' checked':'')+'> один вход на рынок</label>';\n  h+='<label class=\"small\"><input type=\"checkbox\" id=\"tp_trim\"'+(T.trim?' checked':'')+'> не считать неполные крайние дни</label></div>';\n  h+='<div class=\"mut small\" style=\"margin-top:6px\">В расчёте '+nD+' дн. ('+dStr(lo)+' — '+dStr(hi)+', UTC). Чтобы добавить сюда стратегию, нажми ☆ в списке «Лучшие» или ⭐ в карточке стратегии (сохранятся и её фильтры). В браузере избранные запоминаются; чтобы перенести в другой файл страницы, используй экспорт/импорт ниже.</div></div>';\n  if(!items.length)h+='<div class=\"note\">Пока пусто. Открой любую стратегию и нажми «⭐ В избранное».</div>';\n  else{\n    h+='<div class=\"card top\"><div class=\"th\"><b>Сравнение избранных</b> <span class=\"mut small\">клик по строке — полный разбор с графиком накопленной прибыли</span></div>';\n    h+=topTable(items,'fav',{nomedal:true,limit:999,attrs:x=>' data-act=\"openfav\" data-id=\"'+esc(x.fav.id)+'\"',sub:x=>favSub(x.fav),cum:true,head:'',extra:x=>'<button class=\"x\" title=\"переименовать\" data-act=\"favren\" data-id=\"'+esc(x.fav.id)+'\">✎</button><button class=\"x\" title=\"убрать из избранного\" data-act=\"favdel\" data-id=\"'+esc(x.fav.id)+'\">🗑</button>',star:false});\n    h+='</div>';\n  }\n  h+='<div class=\"card\"><details><summary>Экспорт / импорт / сброс</summary><div class=\"bar\"><button data-act=\"favexp\">Показать текст для копирования</button><button data-act=\"favimp\">Загрузить из текста</button><button data-act=\"favreset\">Вернуть стандартные</button></div><textarea id=\"favio\" rows=\"6\" style=\"width:100%;font:12px monospace;background:var(--card);color:var(--fg);border:1px solid var(--line);border-radius:8px\" placeholder=\"Здесь появится JSON избранных; вставь сюда JSON и нажми «Загрузить из текста»\"></textarea></details></div>';\n  return h;\n}\n\n// ---------- СОГЛАСИЯ: цепочки стратегий ----------\n// Идея: стратегия A (например, вход по 0.60-0.70) уже купила монету в эту сторону; потом в тот же рынок и в ту же сторону\n// срабатывает стратегия B (например, 0.80-0.90); потом C (0.93-0.98). Покупаем на ПОСЛЕДНЕМ шаге, когда все предыдущие уже были.\nconst bandText=b=>b[0].toFixed(2)+'–'+b[1].toFixed(2);\nconst GCACHE=new WeakMap();\nfunction groupsOf(pool){\n  let g=GCACHE.get(pool);if(g)return g;\n  const m=new Map();\n  for(const r of pool){const k=r[C.mk]*2+r[C.side];let a=m.get(k);if(!a){a=[];m.set(k,a);}a.push(r);}\n  g=[];m.forEach(a=>{a.sort((x,y)=>x[C.ts]-y[C.ts]);g.push(a);});\n  GCACHE.set(pool,g);return g;\n}\nfunction stepPred(st){\n  if(st.kind==='fav'){\n    const f=FAVS.find(x=>x.id===st.favId);\n    if(!f||f.type==='chain')return()=>false;\n    const set=new Set(favRowsRaw(f));\n    return r=>set.has(r);\n  }\n  const lo=(st.lo===null||st.lo===undefined||st.lo==='')?-Infinity:+st.lo,hi=(st.hi===null||st.hi===undefined||st.hi==='')?Infinity:+st.hi;\n  const fam=st.fam||'';\n  return r=>{\n    const p=r[CI.px];\n    if(p<lo-1e-9||p>=hi-1e-9)return false;\n    if(fam&&famOf(D.ideas[r[C.idea]])!==fam)return false;\n    return true;\n  };\n}\nfunction stepText(st){\n  if(st.kind==='fav'){const f=FAVS.find(x=>x.id===st.favId);return f?'«'+f.name+'»':'(избранная удалена)';}\n  return (st.lo===''||st.lo==null?'…':(+st.lo).toFixed(2))+'–'+(st.hi===''||st.hi==null?'…':(+st.hi).toFixed(2))+(st.fam?' ['+st.fam+']':'');\n}\nconst chainLabel=steps=>steps.map(stepText).join(' → ');\nfunction chainCompute(steps,gap,pool){\n  const preds=steps.map(stepPred),groups=groupsOf(pool),last=preds.length-1;\n  const g=(gap===''||gap===null||gap===undefined||!(+gap>0))?Infinity:+gap;\n  const chain=[],base=[],noch=[];\n  if(last<0)return{chain,base,noch};\n  for(const rs of groups){\n    let b=null;\n    for(const r of rs){if(preds[last](r)){b=r;break;}}\n    if(!b)continue;\n    base.push(b);\n    let t=-Infinity,ok=true,fin=null;\n    for(let si=0;si<=last;si++){\n      let hit=null;\n      for(const r of rs){if(si>0&&r[C.ts]<=t)continue;if(preds[si](r)){hit=r;break;}}\n      if(!hit){ok=false;break;}\n      if(si>0&&hit[C.ts]-t>g){ok=false;break;}\n      t=hit[C.ts];fin=hit;\n    }\n    if(ok)chain.push(fin);else noch.push(b);\n  }\n  return{chain:chain,base:base,noch:noch};\n}\nfunction statsRow(label,st,stake){\n  if(!st.n)return '<tr><td class=\"l\">'+label+'</td><td colspan=\"6\" class=\"mut\">нет сделок</td></tr>';\n  return '<tr><td class=\"l\">'+label+'</td><td>'+st.n+'</td><td>'+pct(st.wr)+'</td><td>'+fmt(st.apx,3)+'</td><td class=\"'+cls(st.roi)+'\">'+sgn(st.roi*100,1)+'%</td><td class=\"'+cls(st.roi)+'\">'+money(st.roi*st.n*stake)+'</td><td class=\"l\">'+st.verdict+'</td></tr>';\n}\nfunction renderChain(){\n  const ch=S.ch,stake=S.stake;\n  const pool=rowsF;\n  let h='<div class=\"card hero\"><div class=\"bar\" style=\"margin:0 0 6px\"><b style=\"font-size:17px\">🔗 Согласия: цепочки стратегий</b></div>';\n  h+='<div class=\"small mut\" style=\"margin-bottom:8px\">Ищем случаи, когда в одном рынке и в одну сторону подряд сработали несколько стратегий: например, одна купила по 0.60-0.70, потом другая по 0.80-0.90, потом третья по 0.93-0.98. Покупаем на <b>последнем</b> шаге. Фильтры сверху (монета, период, окно и др.) действуют на все шаги.</div>';\n  ch.steps.forEach((st,i)=>{\n    h+='<div class=\"fl\" data-st=\"'+i+'\"><b>Шаг '+(i+1)+(i===ch.steps.length-1?' (вход)':'')+'</b> <select data-ch=\"kind\"><option value=\"band\"'+(st.kind==='band'?' selected':'')+'>любая стратегия с ценой входа</option><option value=\"fav\"'+(st.kind==='fav'?' selected':'')+'>избранная стратегия</option></select>';\n    if(st.kind==='fav'){\n      h+=' <select data-ch=\"fav\">'+FAVS.filter(f=>f.type!=='chain').map(f=>'<option value=\"'+esc(f.id)+'\"'+(st.favId===f.id?' selected':'')+'>'+esc(f.name)+'</option>').join('')+'</select>';\n    }else{\n      h+=' от <input type=\"number\" step=\"0.01\" data-ch=\"lo\" value=\"'+(st.lo===null||st.lo===undefined?'':st.lo)+'\" style=\"width:76px\"> до <input type=\"number\" step=\"0.01\" data-ch=\"hi\" value=\"'+(st.hi===null||st.hi===undefined?'':st.hi)+'\" style=\"width:76px\"> <span class=\"mut small\">(до — не включая)</span> <select data-ch=\"fam\"><option value=\"\">все семейства</option>'+FAMS.map(f=>'<option value=\"'+esc(f)+'\"'+(st.fam===f?' selected':'')+'>'+esc(f)+'</option>').join('')+'</select>';\n    }\n    h+=(ch.steps.length>1?' <button class=\"x\" data-act=\"chdel\" title=\"убрать шаг\">×</button>':'')+'</div>';\n  });\n  h+='<div class=\"bar\" style=\"margin:8px 0 0\">'+(ch.steps.length<4?'<button data-act=\"chadd\">+ добавить шаг</button>':'')+'<label class=\"small\">Макс. пауза между шагами, с <input type=\"number\" min=\"0\" id=\"ch_gap\" value=\"'+esc(ch.gap)+'\" style=\"width:76px\" placeholder=\"любая\"></label>';\n  h+='<span class=\"mut small\">быстро: </span>'+[[[0.6,0.7],[0.8,0.9]],[[0.6,0.7],[0.8,0.9],[0.93,0.98]],[[0.7,0.8],[0.9,0.95]]].map((p,i)=>'<span class=\"chip\" data-act=\"chpreset\" data-i=\"'+i+'\">'+p.map(b=>b[0].toFixed(2)+'–'+b[1].toFixed(2)).join(' → ')+'</span>').join('')+'</div></div>';\n  // результат конструктора\n  const res=chainCompute(ch.steps,ch.gap,pool);\n  const stC=stats(res.chain),stN=stats(res.noch),stB=stats(res.base);\n  h+='<div class=\"card\"><div class=\"bar\" style=\"margin:0 0 6px\"><b>Результат цепочки: '+esc(chainLabel(ch.steps))+'</b>';\n  if(res.chain.length)h+='<button data-act=\"chopen\">Открыть полный разбор</button><button data-act=\"chfav\">⭐ В избранное</button>';\n  h+='</div>';\n  h+='<div class=\"tw\"><table><thead><tr><th class=\"l ns\">Вариант</th><th class=\"ns\">Сделок</th><th class=\"ns\">Побед</th><th class=\"ns\">Ср. цена</th><th class=\"ns\">ROI</th><th class=\"ns\">Прибыль</th><th class=\"l ns\">Вердикт</th></tr></thead><tbody>';\n  h+=statsRow('<b>С согласием</b> (все шаги сработали)',stC,stake)+statsRow('Последний шаг БЕЗ согласия (раньше ничего не было)',stN,stake)+statsRow('Последний шаг целиком (с согласием и без)',stB,stake);\n  h+='</tbody></table></div>';\n  if(stC.n&&stN.n){\n    const lift=(stC.roi-stN.roi)*100;\n    h+='<div class=\"note small\">'+(lift>2?'<b>Согласие помогает:</b> ROI с согласием выше, чем у того же входа без него, на '+lift.toFixed(1)+' п.п.':(lift<-2?'<b>Согласие не помогает:</b> без него вход даже лучше на '+(-lift).toFixed(1)+' п.п. ROI.':'<b>Заметной разницы нет:</b> ROI с согласием и без почти одинаковый ('+sgn(lift,1)+' п.п.).'))+' Сравнивай и число сделок: если с согласием их стало в разы меньше, прибыль в долларах может упасть.</div>';\n  }\n  if(stC.n>=2)h+=cumChart(res.chain);\n  h+='</div>';\n  return h;\n}\nfunction renderPeriodBar(){\n  const g=PRESET_GROUPS[PRESET_GROUPS.length-1],gi=PRESET_GROUPS.length-1;\n  let h='<div class=\"card\"><div class=\"bar\" style=\"margin:0\"><b>Период</b>'+g.p.map((p,i)=>'<span class=\"chip'+(presetOn(p)?' on':'')+'\" data-act=\"preset\" data-g=\"'+gi+'\" data-i=\"'+i+'\">'+esc(p.t)+'</span>').join('');\n  h+='<label class=\"small\">с <input type=\"date\" id=\"dFrom\" value=\"'+esc(S.dFrom)+'\"></label><label class=\"small\">по <input type=\"date\" id=\"dTo\" value=\"'+esc(S.dTo)+'\"></label><button data-act=\"fclear\">Сбросить период</button></div></div>';\n  return h;\n}\nlet helpOpen=false;\nfunction render(){\n  const m=D.meta;\n  const d0=m.firstTs?new Date(m.firstTs).toLocaleString():'—',d1=m.lastTs?new Date(m.lastTs).toLocaleString():'—';\n  document.getElementById('meta').innerHTML='Период: '+esc(m.periodLabel)+' ('+d0+' — '+d1+') · рынков '+m.markets+' · сделок '+N+(TEMKA.size?' (без «темок»)':'')+(m.sampled?' · <span class=\"neg\">в странице выборка '+m.rowsEmbedded+' (файл не влез по размеру)</span>':' · в странице <b>все сделки</b>')+' · собрано '+new Date(m.generatedAt).toLocaleString();\n  applyFilters();saveHash();\n  for(const k in CUMREG)delete CUMREG[k];cumSeq=0;\n  const ae=document.activeElement,aid=ae&&ae.id;\n  let h=(S.tab==='fav')?renderPeriodBar():renderFilters();\n  if(helpOpen)h+=renderHelp();\n  if(S.sel)h+=renderDetail();else h+=renderTabs()+(S.tab==='top'?renderTop():S.tab==='fav'?renderFav():S.tab==='chain'?renderChain():renderTable());\n  document.getElementById('app').innerHTML=h;\n  if(aid){const e=document.getElementById(aid);if(e&&e.focus)e.focus();}\n}\n\n// ---------- панель «Выходы и добор» (минимализм: три независимые строки) ----------\nconst UNITS=[['pct','% от цены входа'],['usd','$ на ставку'],['c','центов']];\nfunction unitSel(id,cur){return '<select id=\"'+id+'\">'+UNITS.map(u=>'<option value=\"'+u[0]+'\"'+(u[0]===cur?' selected':'')+'>'+u[1]+'</option>').join('')+'</select>';}\nconst sw=(id,on)=>'<label class=\"swt\"><input type=\"checkbox\" id=\"'+id+'\"'+(on?' checked':'')+'><i></i></label>';\nfunction smartPanel(rs){\n  if(S.sel&&S.sel.flip)return'';\n  if(!exHave())return'';\n  if(entryOn())return'<div class=\"card xp\"><b>Умные условия</b> <span class=\"mut small\">— отключены, пока включён «особый вход»</span></div>';\n  const num=(id,v,mn,mx)=>'<input type=\"number\" id=\"'+id+'\" min=\"'+mn+'\" max=\"'+mx+'\" step=\"1\" value=\"'+v+'\" style=\"width:70px\">';\n  const row=(on,swid,title,hint,body)=>'<div class=\"xr'+(on?' on':'')+'\">'+sw(swid,on)+'<span class=\"xt\">'+title+'</span>'+(on?body:'<span class=\"mut small\">'+hint+'</span>')+'</div>';\n  let h='<div class=\"card xp\"><div class=\"xh\"><b>Умные условия</b><span class=\"mut small\">отдельные галочки: включай любые — кумулятив и статистика пересчитаются</span></div>';\n  h+=row(CR.on,'x_cr_on','Выход при обвале','продать, если цена дошла до верха и резко упала…','<span class=\"small\">если bid дошёл до</span>'+num('x_cr_h',CR.h,2,99)+'<span class=\"small\">¢ и потом упал до</span>'+num('x_cr_l',CR.l,1,98)+'<span class=\"small\">¢ — продать сразу, не ждать проигрыша</span>');\n  h+=row(RE.b.on,'x_rb_on','Вход после выноса','«рост, рост, вынос вниз, потом возврат» — купить на возврате…','<span class=\"small\">цена дошла до</span>'+num('x_rb_p',RE.b.peak,2,99)+'<span class=\"small\">¢, потом упала до</span>'+num('x_rb_l',RE.b.low,1,98)+'<span class=\"small\">¢, потом вернулась до</span>'+num('x_rb_b',RE.b.buy,2,98)+'<span class=\"small\">¢ — купить по этой цене</span>');\n  h+=row(RE.c.on,'x_rc_on','Вход после дна','упала до нижней границы, потом отросла — купить на отскоке…','<span class=\"small\">цена упала до</span>'+num('x_rc_l',RE.c.low,1,98)+'<span class=\"small\">¢, потом отросла до</span>'+num('x_rc_b',RE.c.buy,2,98)+'<span class=\"small\">¢ — купить по этой цене</span>');\n  if(CR.on&&exOn()){\n    let n=0,sv=0,ls=0;for(const r of rs){if(r[XK]==='cr'){n++;if(r[XK+1])ls++;else sv++;}}\n    h+='<div class=\"small\" style=\"margin-top:6px\">Выход при обвале сработал <b>'+n+'</b> раз: спас <b>'+sv+'</b> проигрышей, срезал <b>'+ls+'</b> побед (они бы выиграли).</div>';\n  }\n  if(reOn()){\n    const sig=selRowsNoRe().filter(hasPath),b=stats(sig),n=stats(rs),sb=b.roi*b.n*S.stake,sn=n.roi*n.n*S.stake;\n    h+='<div class=\"xres\"><div><span class=\"mut small\">сигналов по условиям ТС</span><b>'+b.n+'</b></div><div><span class=\"mut small\">условие входа сработало</span><b>'+n.n+' <span class=\"small mut\">('+(b.n?Math.round(n.n/b.n*100):0)+'%)</span></b></div><div><span class=\"mut small\">итог обычным входом</span><b class=\"'+cls(sb)+'\">'+money(sb)+'</b></div><div class=\"xar\">→</div><div><span class=\"mut small\">итог с новым входом</span><b class=\"'+cls(sn)+'\">'+money(sn)+'</b></div></div>';\n    h+='<div class=\"small mut\" style=\"margin-top:6px\">Покупка по цене «возврата» + спред, держим до конца рынка. Тейк/стоп/добор при этом отключены. Если сделки в новом входе нет — цена не прошла нужный путь. </div>';\n  }\n  if(CR.on||reOn()){\n    const all=selRowsNoRe();let np=0;for(const r of all)if(hasPath(r))np++;\n    h+='<div class=\"small\" style=\"margin-top:8px;padding:8px 10px;border-radius:8px;background:rgba(240,180,60,.12)\"><b>⚠ Точный путь цены есть у '+np+' из '+all.length+' сделок.</b> Эти условия считаются только по ним: нужно знать, что цена делала каждую секунду. '+(reOn()?'Остальные сделки в расчёт «входа после выноса/дна» не берутся. ':'У остальных сделок выход при обвале не применяется. ')+(np<30?'Сделок с путём слишком мало — выводам верить нельзя. ':'')+'Путь по секундам бот пишет только для ТС, которые он торгует; по остальным честно посчитать нельзя (по ключевым точкам результат получался нереально красивым — это была ошибка расчёта, а не находка).</div>';\n  }\n  return h+'</div>';\n}\nfunction exPanel(rs){\n  if(entryOn()||reOn())return'<div class=\"card xp\"><b>Тейк-профит · Стоп · Добор</b> <span class=\"mut small\">— отключены, пока включён «особый вход» или «вход после выноса/дна»</span></div>';\n  if(S.sel&&S.sel.flip)return'<div class=\"card xp\"><div class=\"small mut\">Для перевёрнутой торговли выходы не считаются.</div></div>';\n  if(!exHave())return'<div class=\"card xp\"><b>Тейк-профит · Стоп · Добор</b><div class=\"note warn small\" style=\"margin-top:8px\">В этом файле нет данных о пути цены после входа (нужен LAB v4.4+). Обнови бота и выгрузи страницу заново — старые сделки тоже пересчитаются.</div></div>';\n  const row=(key,title,hint,body)=>'<div class=\"xr'+(X[key].on?' on':'')+'\">'+sw('x_'+key+'_on',X[key].on)+'<span class=\"xt\">'+title+'</span>'+(X[key].on?body:'<span class=\"mut small\">'+hint+'</span>')+'</div>';\n  let h='<div class=\"card xp\"><div class=\"xh\"><b>Тейк-профит · Стоп · Добор</b><span class=\"mut small\">включай что нужно — всё ниже пересчитается</span></div>';\n  h+=row('tp','Тейк-профит','продать, когда прибыль достигла…','<span class=\"small\">продать при прибыли</span><input type=\"number\" id=\"x_tp_v\" min=\"0.5\" step=\"0.5\" value=\"'+X.tp.v+'\">'+unitSel('x_tp_u',X.tp.u));\n  h+=row('sl','Стоп','выйти, когда убыток достиг…','<span class=\"small\">выйти при убытке</span><input type=\"number\" id=\"x_sl_v\" min=\"0.5\" step=\"0.5\" value=\"'+X.sl.v+'\">'+unitSel('x_sl_u',X.sl.u));\n  let ab='<div class=\"xsteps\">';\n  X.add.steps.forEach((a,i)=>{ab+='<div class=\"xs\" data-xs=\"'+i+'\"><span class=\"small\">когда цена</span><select id=\"x_am_'+i+'\"><option value=\"c\"'+(a.m==='c'?' selected':'')+'>выросла на ¢</option><option value=\"p\"'+(a.m==='p'?' selected':'')+'>дошла до</option></select><input type=\"number\" id=\"x_av_'+i+'\" min=\"1\" max=\"99\" step=\"1\" value=\"'+a.v+'\"><span class=\"small\">'+(a.m==='p'?'(цена в центах, напр. 75)':'¢ от входа')+'</span><span class=\"small\">докупить на $</span><input type=\"number\" id=\"x_au_'+i+'\" min=\"0.5\" step=\"0.5\" value=\"'+a.usd+'\"><button class=\"x\" data-act=\"xdel\" data-i=\"'+i+'\" title=\"убрать\">✕</button></div>';});\n  ab+='<button class=\"xadd\" data-act=\"xadd\">+ заявка</button></div>';\n  h+=row('add','Добор','докупать, когда сделка пошла вверх…',ab);\n  if(exOn()){\n    const base=selRowsPlain(),sb=stats(base),sx=stats(rs),st=S.stake;\n    const a0=sb.roi*sb.n*st,a1=sx.roi*sx.n*st;\n    let sl=0,slS=0,slN=0,slV=0,tp=0,tpW=0,tpL=0,tpWv=0,tpLv=0,ad=0;const stp=[];\n    for(const r of rs){\n      const k=r[XK];if(k===undefined||k===null)continue;\n      const was=r[XK+1],dl=r[XI]-r[XK+3];\n      if(k==='sl'){sl++;if(was){slN++;}else slS++;}\n      else if(k==='tp'){tp++;if(was){tpW++;tpWv+=dl;}else{tpL++;tpLv+=dl;}}\n      const ss=r[XK+2]||[];if(ss.length)ad++;ss.forEach(q=>{const o=stp[q[0]]||(stp[q[0]]={n:0,p:0});o.n++;o.p+=q[1];});\n    }\n    h+='<div class=\"xres\"><div><span class=\"mut small\">без выходов</span><b class=\"'+cls(a0)+'\">'+money(a0)+'</b></div><div class=\"xar\">→</div><div><span class=\"mut small\">с настройками</span><b class=\"'+cls(a1)+'\">'+money(a1)+'</b></div><div><span class=\"mut small\">разница</span><b class=\"'+cls(a1-a0)+'\">'+money(a1-a0)+'</b></div></div>';\n    const bits=[];\n    if(X.tp.on)bits.push('тейк сработал <b>'+tp+'</b> раз (из них <b>'+tpW+'</b> и так выиграли бы — недобрали '+money(tpWv*st)+'; <b>'+tpL+'</b> потом проиграли бы — сохранили '+money(tpLv*st)+')');\n    if(X.sl.on)bits.push('стоп сработал <b>'+sl+'</b> раз (спас <b>'+slS+'</b> проигрышей, выбил шумом <b>'+slN+'</b> побед)');\n    if(X.add.on)bits.push('добор в <b>'+ad+'</b> сделках'+(X.add.steps.length>1?' ('+X.add.steps.map((a,i)=>'заявка '+(i+1)+': '+((stp[i]&&stp[i].n)||0)).join(', ')+')':''));\n    h+='<div class=\"small\" style=\"margin-top:6px\">'+bits.join(' · ')+'</div>';\n    h+='<div class=\"small mut\" style=\"margin-top:4px\">Считается по bid (по чему реально можно продать); стоп — с проскальзыванием 2¢. Если за секунду сработало несколько условий, порядок определяется по записанному времени касания цены. «Побед» и ROI ниже — уже с учётом выходов; Edge и вердикт ✅/❌ в этом режиме не показываются.</div>';\n  }\n  return h+'</div>';\n}\nfunction xChange(t){\n  const id=t.id;let m;\n  if(id==='x_en_on'){EN.on=t.checked;}\n  else if(id==='x_cr_on'){CR.on=t.checked;}\n  else if(id==='x_cr_h'){CR.h=Math.max(2,Math.min(99,+t.value||90));}\n  else if(id==='x_cr_l'){CR.l=Math.max(1,Math.min(98,+t.value||50));}\n  else if(id==='x_rb_on'){RE.b.on=t.checked;}\n  else if(id==='x_rb_p'){RE.b.peak=Math.max(2,Math.min(99,+t.value||85));}\n  else if(id==='x_rb_l'){RE.b.low=Math.max(1,Math.min(98,+t.value||50));}\n  else if(id==='x_rb_b'){RE.b.buy=Math.max(2,Math.min(98,+t.value||80));}\n  else if(id==='x_rc_on'){RE.c.on=t.checked;}\n  else if(id==='x_rc_l'){RE.c.low=Math.max(1,Math.min(98,+t.value||50));}\n  else if(id==='x_rc_b'){RE.c.buy=Math.max(2,Math.min(98,+t.value||85));}\n  else if(id==='x_en_p'){EN.p=Math.max(2,Math.min(98,+t.value||89));}\n  else if((m=/^x_(tp|sl|add)_on$/.exec(id))){X[m[1]].on=t.checked;}\n  else if((m=/^x_(tp|sl)_v$/.exec(id))){X[m[1]].v=Math.max(0,+t.value||0);}\n  else if((m=/^x_(tp|sl)_u$/.exec(id))){X[m[1]].u=t.value;}\n  else if((m=/^x_a([mvu])_(\\d+)$/.exec(id))){const a=X.add.steps[+m[2]];if(a){if(m[1]==='m'){a.m=t.value;a.v=t.value==='p'?75:10;}else if(m[1]==='v')a.v=Math.max(1,+t.value||1);else a.usd=Math.max(0.5,+t.value||1);}}\n  render();\n}\n// ---------- график: как идёт цена токена после входа (усреднённый) ----------\nfunction pctl(a,p){if(!a.length)return null;const s=a.slice().sort((x,y)=>x-y);return s[Math.min(s.length-1,Math.floor(p*s.length))];}\nfunction pathChart(rs){\n  const base=EXOFF?rs:selRowsPlain();rs=base;\n  const cols=OFF.map(o=>({o:o,ci:CI['d'+o]})).filter(c=>c.ci!==undefined);\n  const W=[],L=[];\n  cols.forEach(c=>{const w=[],l=[];for(const r of rs){const v=r[c.ci];if(isNul(v))continue;(r[C.won]?w:l).push(v);}W.push(w);L.push(l);});\n  const avg=a=>a.length?a.reduce((x,y)=>x+y,0)/a.length:null;\n  let fw=0,nw=0,fl=0,nl=0,pxs=0,mfs=0,mas=0,nm=0;\n  for(const r of rs){if(r[C.won]){fw+=1-r[CI.px];nw++;}else{fl+=-r[CI.px];nl++;}pxs+=r[CI.px];if(!isNul(r[CI.mfe])){mfs+=r[CI.mfe];mas+=r[CI.mae];nm++;}}\n  const apx=rs.length?pxs/rs.length:0.5;\n  const pts=(arr,fin,nfin)=>{const o=arr.map(a=>a.length>=3?{m:avg(a),lo:pctl(a,.25),hi:pctl(a,.75),n:a.length}:null);o.push(nfin>=3?{m:fin/nfin,lo:null,hi:null,n:nfin}:null);return o;};\n  const PW=pts(W,fw,nw),PL=pts(L,fl,nl);\n  const vals=[];PW.concat(PL).forEach(p=>{if(p){vals.push(p.m);if(p.lo!==null){vals.push(p.lo,p.hi);}}});\n  if(!vals.length)return '';\n  const extra=[];if(X.tp.on&&exOn())extra.push(['тейк',xDist(X.tp.u,X.tp.v,apx,S.stake),'var(--w)']);if(X.sl.on&&exOn())extra.push(['стоп',-xDist(X.sl.u,X.sl.v,apx,S.stake),'var(--l)']);\n  extra.forEach(e=>vals.push(e[1]));\n  let mn=Math.min(...vals,0),mx=Math.max(...vals,0);const pad=(mx-mn)*0.06||0.01;mn-=pad;mx+=pad;\n  const w=1000,h=380,pl=56,pr=18,pt=16,pb=40,n=PW.length;\n  const X_=i=>pl+(w-pl-pr)*i/(n-1),Y=v=>pt+(h-pt-pb)*(1-(v-mn)/(mx-mn));\n  let s='<svg viewBox=\"0 0 '+w+' '+h+'\" width=\"100%\" class=\"pch\">';\n  for(let g=0;g<=5;g++){const v=mn+(mx-mn)*g/5,y=Y(v);s+='<line x1=\"'+pl+'\" x2=\"'+(w-pr)+'\" y1=\"'+y+'\" y2=\"'+y+'\" stroke=\"var(--line)\"/><text x=\"'+(pl-6)+'\" y=\"'+(y+4)+'\" text-anchor=\"end\">'+(v>=0?'+':'−')+Math.abs(v*100).toFixed(0)+'¢</text>';}\n  s+='<line x1=\"'+pl+'\" x2=\"'+(w-pr)+'\" y1=\"'+Y(0)+'\" y2=\"'+Y(0)+'\" stroke=\"var(--mut)\" stroke-dasharray=\"5 4\"/><text x=\"'+(w-pr)+'\" y=\"'+(Y(0)-5)+'\" text-anchor=\"end\">цена входа</text>';\n  extra.forEach(e=>{s+='<line x1=\"'+pl+'\" x2=\"'+(w-pr)+'\" y1=\"'+Y(e[1])+'\" y2=\"'+Y(e[1])+'\" stroke=\"'+e[2]+'\" stroke-dasharray=\"2 4\" opacity=\".8\"/><text x=\"'+(pl+4)+'\" y=\"'+(Y(e[1])-4)+'\" style=\"fill:'+e[2]+'\">'+e[0]+' (≈ '+(e[1]>=0?'+':'−')+Math.abs(e[1]*100).toFixed(0)+'¢ при средней цене входа)</text>';});\n  cols.forEach((c,i)=>{s+='<text x=\"'+X_(i)+'\" y=\"'+(h-18)+'\" text-anchor=\"middle\">'+c.o+'с</text>';});\n  s+='<text x=\"'+X_(n-1)+'\" y=\"'+(h-18)+'\" text-anchor=\"middle\">итог</text><text x=\"'+((pl+w-pr)/2)+'\" y=\"'+(h-2)+'\" text-anchor=\"middle\">секунд после входа</text>';\n  const band=(P,color)=>{const up=[],dn=[];P.forEach((p,i)=>{if(p&&p.lo!==null){up.push(X_(i).toFixed(1)+' '+Y(p.hi).toFixed(1));dn.unshift(X_(i).toFixed(1)+' '+Y(p.lo).toFixed(1));}});return up.length>1?'<path d=\"M'+up.join('L')+'L'+dn.join('L')+'Z\" fill=\"'+color+'\" opacity=\".13\"/>':'';};\n  const line=(P,color)=>{let d='',pen=false,dots='';P.forEach((p,i)=>{if(!p){pen=false;return;}d+=(pen?'L':'M')+X_(i).toFixed(1)+' '+Y(p.m).toFixed(1)+' ';pen=true;dots+='<circle cx=\"'+X_(i)+'\" cy=\"'+Y(p.m)+'\" r=\"4\" fill=\"'+color+'\"><title>'+(i<cols.length?cols[i].o+'с':'итог')+': в среднем '+(p.m>=0?'+':'−')+Math.abs(p.m*100).toFixed(1)+'¢ ('+p.n+' сделок)'+(p.lo!==null?'; у половины сделок от '+(p.lo*100).toFixed(0)+'¢ до '+(p.hi*100).toFixed(0)+'¢':'')+'</title></circle>';});return '<path d=\"'+d+'\" fill=\"none\" stroke=\"'+color+'\" stroke-width=\"2.5\"/>'+dots;};\n  s+=band(PL,'var(--l)')+band(PW,'var(--w)')+line(PL,'var(--l)')+line(PW,'var(--w)')+'</svg>';\n  const fn=v=>(v>=0?'+':'−')+Math.abs(v*100).toFixed(0)+'¢';\n  return '<h3>Как идёт цена токена после входа</h3><div class=\"small mut\" style=\"margin-bottom:4px\"><span style=\"color:var(--w)\">●</span> победы ('+nw+') &nbsp; <span style=\"color:var(--l)\">●</span> проигрыши ('+nl+') — линия это средний bid минус цена входа, полоса — где лежит середина сделок (25–75%). Наведи на точку — подробности.'\n   +(nm?' В среднем за сделку лучший bid был <b class=\"pos\">'+fn(mfs/nm)+'</b>, худший <b class=\"neg\">'+fn(mas/nm)+'</b>.':'')+'</div>'+s;\n}\n// ---------- окно одной сделки ----------\nconst pkey=r=>r[C.mk]+'.'+r[C.side]+'.'+r[C.ts];\nfunction tradeSvg(r){\n  const px=r[CI.px],sec=r[CI.sec],won=r[C.won];\n  const origWon=(r[XK+1]!==undefined&&r[XK+1]!==null)?r[XK+1]:won;\n  const dense=D.paths&&D.paths[pkey(r)];\n  const T=isNul(sec)?300:Math.max(30,sec);\n  let pts=[];const marks=[];\n  if(dense){dense.forEach((b,i)=>{if(b!==null&&b>=0)pts.push([i*2,b/100]);});}\n  else{\n    pts.push([0,px]);\n    OFF.forEach(o=>{const v=r[CI['d'+o]];if(!isNul(v)&&o<=T)pts.push([o,px+v]);});\n    if(!isNul(r[CI.end10])&&T>20)pts.push([T-10,px+r[CI.end10]]);\n    UPL.forEach(L=>{const t=r[CI['tp'+L]];if(!isNul(t)){pts.push([t,px+L/100]);marks.push([t,px+L/100,'bid впервые ≥ вход+'+L+'¢','w']);}});\n    DNL.forEach(L=>{const t=r[CI['dn'+L]];if(!isNul(t)){pts.push([t,px-L/100]);marks.push([t,px-L/100,'bid впервые ≤ вход−'+L+'¢','l']);}});\n    if(!isNul(r[CI.tmae])&&!isNul(r[CI.mae])){pts.push([r[CI.tmae],px+r[CI.mae]]);marks.push([r[CI.tmae],px+r[CI.mae],'худшая точка '+(r[CI.mae]*100).toFixed(0)+'¢','l']);}\n    pts.sort((a,b)=>a[0]-b[0]);\n  }\n  pts=pts.filter(p=>p[0]<=T+1);\n  const fin=origWon?1:0;\n  const lastT=pts.length?pts[pts.length-1][0]:0;\n  pts.push([Math.max(T,lastT+1),fin]);\n  const lv=[];\n  if(!isNul(r[CI.mfe]))lv.push([px+r[CI.mfe],'лучший bid','var(--w)']);\n  if(!isNul(r[CI.mae]))lv.push([px+r[CI.mae],'худший bid','var(--l)']);\n  const ex=exOn()&&!(S.sel&&S.sel.flip);\n  if(ex){\n    const st=S.stake;\n    if(X.tp.on)lv.push([Math.min(0.995,px+xDist(X.tp.u,X.tp.v,px,st)),'тейк','var(--good)']);\n    if(X.sl.on)lv.push([Math.max(0.01,px-xDist(X.sl.u,X.sl.v,px,st)),'стоп','var(--bad)']);\n    if(X.add.on)X.add.steps.forEach((a,i)=>{const g=a.m==='p'?a.v/100:px+a.v/100;lv.push([g,'добор '+(i+1)+' ($'+a.usd+')','var(--acc)']);});\n  }\n  const ys=pts.map(p=>p[1]).concat(lv.map(l=>l[0]),[px]);\n  let mn=Math.max(0,Math.min(...ys)-0.03),mx=Math.min(1.02,Math.max(...ys)+0.03);if(mx-mn<0.1){mx=mn+0.1;}\n  const w=1000,h=420,pl=58,pr=24,pt=20,pb=44;\n  const Xs=t=>pl+(w-pl-pr)*t/Math.max(T,lastT+1),Y=v=>pt+(h-pt-pb)*(1-(v-mn)/(mx-mn));\n  let s='<svg viewBox=\"0 0 '+w+' '+h+'\" width=\"100%\" class=\"pch\">';\n  for(let g=0;g<=5;g++){const v=mn+(mx-mn)*g/5,y=Y(v);s+='<line x1=\"'+pl+'\" x2=\"'+(w-pr)+'\" y1=\"'+y+'\" y2=\"'+y+'\" stroke=\"var(--line)\"/><text x=\"'+(pl-6)+'\" y=\"'+(y+4)+'\" text-anchor=\"end\">'+v.toFixed(2)+'</text>';}\n  const tk=Math.max(10,Math.round(T/8/10)*10);\n  for(let t=0;t<=T;t+=tk){s+='<line x1=\"'+Xs(t)+'\" x2=\"'+Xs(t)+'\" y1=\"'+pt+'\" y2=\"'+(h-pb)+'\" stroke=\"var(--line)\" opacity=\".5\"/><text x=\"'+Xs(t)+'\" y=\"'+(h-24)+'\" text-anchor=\"middle\">'+t+'с</text>';}\n  s+='<text x=\"'+((pl+w-pr)/2)+'\" y=\"'+(h-6)+'\" text-anchor=\"middle\">секунд после входа (закрытие рынка справа)</text>';\n  s+='<rect x=\"'+pl+'\" y=\"'+Y(px)+'\" width=\"'+(w-pl-pr)+'\" height=\"'+Math.max(0,(h-pb)-Y(px))+'\" fill=\"var(--bad)\" opacity=\".05\"/><rect x=\"'+pl+'\" y=\"'+pt+'\" width=\"'+(w-pl-pr)+'\" height=\"'+Math.max(0,Y(px)-pt)+'\" fill=\"var(--good)\" opacity=\".05\"/>';\n  s+='<line x1=\"'+pl+'\" x2=\"'+(w-pr)+'\" y1=\"'+Y(px)+'\" y2=\"'+Y(px)+'\" stroke=\"var(--fg)\" stroke-dasharray=\"6 4\"/><text x=\"'+(w-pr)+'\" y=\"'+(Y(px)-5)+'\" text-anchor=\"end\" style=\"fill:var(--fg)\">вход '+px.toFixed(2)+'</text>';\n  lv.forEach((l,i)=>{s+='<line x1=\"'+pl+'\" x2=\"'+(w-pr)+'\" y1=\"'+Y(l[0])+'\" y2=\"'+Y(l[0])+'\" stroke=\"'+l[2]+'\" stroke-dasharray=\"2 4\" opacity=\".85\"/><text x=\"'+(pl+4+(i%3)*150)+'\" y=\"'+(Y(l[0])-4)+'\" style=\"fill:'+l[2]+'\">'+l[1]+' '+l[0].toFixed(2)+'</text>';});\n  let d='';pts.forEach((p,i)=>{d+=(i?'L':'M')+Xs(p[0]).toFixed(1)+' '+Y(p[1]).toFixed(1)+' ';});\n  s+='<path d=\"'+d+'\" fill=\"none\" stroke=\"var(--acc)\" stroke-width=\"2.5\" stroke-linejoin=\"round\"/>';\n  if(!dense)pts.slice(0,-1).forEach(p=>{s+='<circle cx=\"'+Xs(p[0])+'\" cy=\"'+Y(p[1])+'\" r=\"3.5\" fill=\"var(--acc)\"><title>'+Math.round(p[0])+'с: bid '+p[1].toFixed(3)+'</title></circle>';});\n  marks.forEach(m=>{s+='<circle cx=\"'+Xs(m[0])+'\" cy=\"'+Y(m[1])+'\" r=\"5\" fill=\"'+(m[3]==='w'?'var(--good)':'var(--bad)')+'\" stroke=\"var(--card)\" stroke-width=\"1.5\"><title>'+m[2]+' — '+Math.round(m[0])+'с</title></circle>';});\n  s+='<circle cx=\"'+Xs(Math.max(T,lastT+1))+'\" cy=\"'+Y(fin)+'\" r=\"6\" fill=\"'+(origWon?'var(--good)':'var(--bad)')+'\"/><text x=\"'+(Xs(Math.max(T,lastT+1))-8)+'\" y=\"'+(Y(fin)+(fin?16:-10))+'\" text-anchor=\"end\" style=\"fill:'+(origWon?'var(--good)':'var(--bad)')+'\">итог рынка: '+(origWon?'победа (1.00)':'проигрыш (0.00)')+'</text>';\n  let note='';\n  if(ex&&r[XK]){\n    const tt=r[XK]==='cr'?'обвал':(r[XK]==='sl'?'стоп':(r[XK]==='tp'?'тейк':'добор'));\n    note='<div class=\"note small\" style=\"margin:0 0 8px\"><b>С твоими настройками:</b> '+tt+' → <b class=\"'+(r[XI]>=0?'pos':'neg')+'\">'+(r[XI]>=0?'+':'−')+'$'+Math.abs(r[XI]*S.stake).toFixed(2)+'</b> (без них: '+(origWon?'победа':'проигрыш')+')</div>';\n  }\n  return note+s+'</svg>'+(dense?'':'<div class=\"small mut\">Для этой сделки сохранены ключевые точки пути цены (не каждая секунда). Полный путь по секундам записывается для стратегий, которые торгует бот.</div>');\n}\nfunction openTrade(r){\n  closeTrade();\n  const px=r[CI.px],won=(r[XK+1]!==undefined&&r[XK+1]!==null)?r[XK+1]:r[C.won];\n  const f=(k,d)=>isNul(r[CI[k]])?'—':r[CI[k]].toFixed(d);\n  const kv=(a,b)=>'<div class=\"kv\"><span>'+a+'</span><b>'+b+'</b></div>';\n  let info=kv('Время',tz(r[C.ts]))+kv('Ячейка',esc(D.combos[r[C.combo]]))+kv('Монета / сторона',esc(COIN_SHORT[D.coins[r[C.coin]]]||D.coins[r[C.coin]])+' · '+(r[C.side]?'Down':'Up'))\n   +kv('Цена входа (ask)',px.toFixed(3))+kv('До закрытия на входе',f('sec',0)+' с')+kv('Итог рынка',won?'<span class=\"pos\">победа</span>':'<span class=\"neg\">проигрыш</span>')\n   +kv('Лучший bid после входа',isNul(r[CI.mfe])?'—':'+'+(r[CI.mfe]*100).toFixed(0)+'¢')+kv('Худший bid после входа',isNul(r[CI.mae])?'—':(r[CI.mae]*100).toFixed(0)+'¢ (через '+f('tmae',0)+' с)')\n   +kv('Монета на входе',f('pm',1)+' bps')+kv('z',f('z',2));\n  if(r[XK+4])info=kv(r[XK+4][2]||'Особый вход','сигнал был на '+r[XK+4][0].toFixed(2)+', вход по '+px.toFixed(2)+' через '+r[XK+4][1]+' с')+info;\n  const el=document.createElement('div');el.id='tmodal';el.className='tm';\n  el.innerHTML='<div class=\"tmc\"><div class=\"tmh\"><b>Сделка: как двигалась цена после входа</b><button class=\"x\" data-act=\"tclose\">✕</button></div>'+tradeSvg(r)+'<div class=\"kvs\">'+info+'</div></div>';\n  el.addEventListener('click',e=>{if(e.target===el)closeTrade();});\n  document.body.appendChild(el);\n}\nfunction closeTrade(){const e=document.getElementById('tmodal');if(e)e.remove();}\ndocument.addEventListener('keydown',e=>{if(e.key==='Escape')closeTrade();});\n\n// ---------- ОСОБЫЕ УСЛОВИЯ ВХОДА: сигнал по условиям ТС, а покупка — только когда цена дойдёт до заданной ----------\nconst EN={on:false,p:89};\nlet ENOFF=false;\nfunction entryOn(){return !ENOFF&&EN.on&&EN.p>=2&&EN.p<=98&&exHave();}\nfunction applyEntry(rs){\n  if(!entryOn()||(S.sel&&S.sel.flip))return rs;\n  const P=EN.p/100,out=[];\n  for(const r of rs){\n    const px0=r[CI.px],mf=r[CI.mfe],ma=r[CI.mae];\n    if(isNul(mf)||isNul(ma))continue;\n    const sp=r[CI.spr],spr=isNul(sp)?0.01:Math.max(0,sp);\n    let ta=0,rise=false;\n    if(P>px0+0.0049){\n      const g=P-spr-px0;rise=true;\n      if(g>0){if(mf<g-1e-9)continue;ta=tLevel(r,'tp',UPL,g*100);}\n    }else if(P<px0-0.0049){\n      const s=px0-P+spr;\n      if(ma>-s+1e-9)continue;ta=tLevel(r,'dn',DNL,s*100);\n    }\n    const np=(P>px0+0.0049||P<px0-0.0049)?P:px0;\n    const c=r.slice();while(c.length<XK+5)c.push(null);\n    c[CI.px]=np;c[C.ts]=r[C.ts]+Math.round(ta);\n    if(!isNul(r[CI.sec]))c[CI.sec]=Math.max(0,r[CI.sec]-ta);\n    c[CI.mfe]=rise?(px0+mf-np):null;c[CI.mae]=null;\n    for(const k of Object.keys(CI)){if(/^(d\\d+|tp\\d+|dn\\d+|tmae|end10)$/.test(k))c[CI[k]]=null;}\n    c[XK+4]=[px0,Math.round(ta)];\n    out.push(c);\n  }\n  return out;\n}\nfunction selRowsNoEntry(){const o=ENOFF;ENOFF=true;try{return selRows();}finally{ENOFF=o;}}\nfunction entryPanel(rs){\n  let h='<div class=\"card xp\"><div class=\"xr'+(EN.on?' on':'')+'\" style=\"border:0;padding:0\">'+sw('x_en_on',EN.on)+'<span class=\"xt\" style=\"min-width:0\">Особые новые условия</span>';\n  if(!exHave())return h+'<span class=\"mut small\">нужны данные о пути цены (LAB v4.4+)</span></div></div>';\n  if(!EN.on)return h+'<span class=\"mut small\">входить не сразу по сигналу, а когда цена дойдёт до нужной</span></div></div>';\n  h+='<span class=\"small\">сигнал по условиям ТС, а покупать, только когда цена токена дойдёт до</span><input type=\"number\" id=\"x_en_p\" min=\"2\" max=\"98\" step=\"1\" value=\"'+EN.p+'\" style=\"width:78px\"><span class=\"small\">¢ (покупка по '+(EN.p/100).toFixed(2)+')</span></div>';\n  const sig=selRowsNoEntry(),b=stats(sig),n=stats(rs);\n  const sb=b.roi*b.n*S.stake,sn=n.roi*n.n*S.stake;\n  h+='<div class=\"xres\"><div><span class=\"mut small\">сигналов было (по условиям ТС)</span><b>'+b.n+'</b></div><div><span class=\"mut small\">цена дошла, вход состоялся</span><b>'+n.n+' <span class=\"small mut\">('+(b.n?Math.round(n.n/b.n*100):0)+'%)</span></b></div>'\n   +'<div><span class=\"mut small\">итог обычным входом</span><b class=\"'+cls(sb)+'\">'+money(sb)+'</b></div><div class=\"xar\">→</div><div><span class=\"mut small\">итог с особым входом</span><b class=\"'+cls(sn)+'\">'+money(sn)+'</b></div></div>';\n  h+='<div class=\"small mut\" style=\"margin-top:6px\">Если цена за оставшееся время так и не дошла до '+EN.p+'¢, сделки нет (в кумулятив не попадает). Вход считается по цене '+(EN.p/100).toFixed(2)+', время входа сдвигается на момент, когда цена до неё дошла. Если сигнал пришёл по цене выше заданной, ждём отката вниз. Пока включён особый вход, тейк/стоп/добор отключены (путь цены после нового входа неизвестен). Win-rate, Edge и ROI ниже уже пересчитаны на новую цену входа.</div>';\n  return h+'</div>';\n}\n// ---------- Проигрышные сделки: как высоко поднимался bid ----------\nlet LOSSTOP=[];\nfunction lossBlock(){\n  const base=selRowsPlain();\n  if(!exHave())return'';\n  const L=[],Wn=[];\n  for(const r of base){const m=r[CI.mfe];if(isNul(m))continue;(r[C.won]?Wn:L).push(r);}\n  let h='<div class=\"card\"><h3 style=\"margin-top:0\">📉 Проигрышные сделки: как высоко поднимался bid после входа</h3>';\n  if(L.length<3)return h+'<div class=\"small mut\">Проигрышей с данными о пути цены меньше трёх — анализировать нечего.</div></div>';\n  const mv=L.map(r=>r[CI.mfe]),ab=L.map(r=>r[CI.px]+r[CI.mfe]);\n  const srt=mv.slice().sort((a,b)=>a-b),med=srt[srt.length>>1],avg=mv.reduce((a,b)=>a+b,0)/mv.length;\n  let top=L.slice().sort((a,b)=>b[CI.mfe]-a[CI.mfe]);LOSSTOP=top.slice(0,8);\n  const never=mv.filter(v=>v<=0.005).length;\n  const BINS=[[-1,0.005,'не поднимался выше входа'],[0.005,0.03,'до +3¢'],[0.03,0.05,'+3…+5¢'],[0.05,0.1,'+5…+10¢'],[0.1,0.15,'+10…+15¢'],[0.15,0.2,'+15…+20¢'],[0.2,0.3,'+20…+30¢'],[0.3,2,'выше +30¢']];\n  const cnt=BINS.map(b=>mv.filter(v=>v>b[0]&&v<=b[1]).length);\n  const mode=cnt.indexOf(Math.max(...cnt)),mx=Math.max(...cnt,1);\n  const f=v=>(v>=0?'+':'−')+Math.abs(v*100).toFixed(0)+'¢';\n  h+='<div class=\"kpis\">'\n   +'<div class=\"kpi\"><b>'+L.length+'</b><span>проигрышных сделок</span></div>'\n   +'<div class=\"kpi\"><b class=\"neg\">'+Math.max(...ab).toFixed(2)+'</b><span>самый высокий bid среди проигрышей ('+f(top[0][CI.mfe])+' от входа) — до него доходили <b>'+ab.filter(v=>Math.round(v*100)>=Math.round(Math.max(...ab)*100)).length+'</b> раз</span></div>'\n   +'<div class=\"kpi\"><b>'+f(med)+'</b><span>медиана: типичный максимум bid у проигрыша</span></div>'\n   +'<div class=\"kpi\"><b>'+f(avg)+'</b><span>среднее</span></div>'\n   +'<div class=\"kpi\"><b>'+BINS[mode][2]+'</b><span>самая частая высота ('+cnt[mode]+' из '+L.length+')</span></div>'\n   +'<div class=\"kpi\"><b>'+Math.round(never/L.length*100)+'%</b><span>проигрышей сразу пошли вниз и не поднимались выше входа</span></div></div>';\n  h+='<h3>Как высоко доходил bid</h3><div class=\"tw\"><table><thead><tr><th class=\"l ns\">Высота максимума bid от цены входа</th><th class=\"ns\">проигрышей</th><th class=\"ns\">доля</th><th class=\"l ns\" style=\"width:40%\"></th></tr></thead><tbody>';\n  BINS.forEach((b,i)=>{h+='<tr><td class=\"l'+(i===mode?' pos':'')+'\"><b>'+b[2]+'</b></td><td>'+cnt[i]+'</td><td>'+Math.round(cnt[i]/L.length*100)+'%</td><td class=\"l\"><div style=\"height:10px;border-radius:5px;background:'+(i===mode?'var(--acc)':'var(--l)')+';width:'+Math.round(cnt[i]/mx*100)+'%;opacity:.8\"></div></td></tr>';});\n  h+='</tbody></table></div>';\n  const cp=new Map();ab.forEach(v=>{const k=Math.round(v*100);cp.set(k,(cp.get(k)||0)+1);});\n  const keys=[...cp.keys()].sort((a,b)=>b-a);let cum=0;\n  h+='<h3>До какой цены токена доходил bid (по точной цене)</h3><div class=\"small mut\" style=\"margin:0 0 4px\">Максимальная цена, до которой дошёл bid после входа, у каждой проигрышной сделки. «Дошли не ниже» — сколько проигрышей достигали этой цены или выше.</div><div class=\"tw\"><table><thead><tr><th class=\"l ns\">Макс. цена bid</th><th class=\"ns\">проигрышей (ровно)</th><th class=\"ns\">дошли не ниже</th><th class=\"ns\">доля от всех проигрышей</th></tr></thead><tbody>';\n  keys.slice(0,25).forEach(k=>{cum+=cp.get(k);h+='<tr><td class=\"l\"><b>'+(k/100).toFixed(2)+'</b></td><td>'+cp.get(k)+'</td><td>'+cum+'</td><td>'+Math.round(cum/L.length*100)+'%</td></tr>';});\n  h+='</tbody></table></div>'+(keys.length>25?'<div class=\"small mut\">показаны 25 самых высоких цен из '+keys.length+'</div>':'');\n  h+='<h3>Если бы продавали на этом уровне</h3><div class=\"tw\"><table><thead><tr><th class=\"l ns\">Уровень (bid ≥ вход +)</th><th class=\"ns\">проигрышей дошли</th><th class=\"ns\">% проигрышей</th><th class=\"ns\">побед дошли, %</th><th class=\"l ns\">что это значит</th></tr></thead><tbody>';\n  [3,5,10,15,20,30,40].forEach(lv=>{\n    const a=L.filter(r=>r[CI.mfe]>=lv/100-1e-9).length,w=Wn.filter(r=>r[CI.mfe]>=lv/100-1e-9).length;\n    const pl=a/L.length,pw=Wn.length?w/Wn.length:0;\n    h+='<tr><td class=\"l\">+'+lv+'¢</td><td>'+a+'</td><td class=\"neg\">'+Math.round(pl*100)+'%</td><td class=\"pos\">'+Math.round(pw*100)+'%</td><td class=\"l small mut\">тейк на +'+lv+'¢ сработал бы у '+Math.round(pl*100)+'% проигрышей (спас бы) и у '+Math.round(pw*100)+'% побед</td></tr>';\n  });\n  h+='</tbody></table></div>';\n  h+='<h3>8 проигрышей с самым высоким bid <span class=\"mut small\" style=\"font-weight:400\">— нажми, чтобы увидеть график</span></h3><div class=\"tw\"><table><thead><tr><th class=\"l ns\">Время</th><th class=\"l ns\">Ячейка</th><th class=\"l ns\">Монета</th><th class=\"ns\">Вход</th><th class=\"ns\">Макс. bid</th><th class=\"ns\">от входа</th></tr></thead><tbody>';\n  LOSSTOP.forEach((r,i)=>{h+='<tr class=\"click\" data-act=\"ltrade\" data-k=\"'+i+'\"><td class=\"l\">'+tz(r[C.ts])+'</td><td class=\"l\">'+esc(D.combos[r[C.combo]])+'</td><td class=\"l\">'+esc(COIN_SHORT[D.coins[r[C.coin]]]||D.coins[r[C.coin]])+'</td><td>'+r[CI.px].toFixed(2)+'</td><td>'+(r[CI.px]+r[CI.mfe]).toFixed(2)+'</td><td class=\"pos\">'+f(r[CI.mfe])+'</td></tr>';});\n  h+='</tbody></table></div><div class=\"small mut\" style=\"margin-top:6px\">Максимум bid — это лучшая цена, по которой после входа можно было продать токен. Это знание задним числом: для анализа, не для входа.</div></div>';\n  return h;\n}\n\n// ---------- Выигранные сделки: до какой минимальной цены падал bid, но сделка всё равно выиграна ----------\nlet WINLOW=[];\nfunction winBlock(){\n  const base=selRowsPlain();\n  if(!exHave())return'';\n  const W=[];\n  for(const r of base){if(r[C.won]&&!isNul(r[CI.mae]))W.push(r);}\n  let h='<div class=\"card\"><h3 style=\"margin-top:0\">📈 Выигранные сделки: насколько глубоко падал bid, но сделка всё равно выиграна</h3>';\n  if(W.length<3)return h+'<div class=\"small mut\">Выигрышей с данными о пути цены меньше трёх.</div></div>';\n  const dv=W.map(r=>-r[CI.mae]),ab=W.map(r=>r[CI.px]+r[CI.mae]);\n  const srt=dv.slice().sort((a,b)=>a-b),med=srt[srt.length>>1],avg=dv.reduce((a,b)=>a+b,0)/dv.length;\n  WINLOW=W.slice().sort((a,b)=>a[CI.mae]-b[CI.mae]).slice(0,8);\n  const minAb=Math.min(...ab),minK=Math.round(minAb*100);\n  const never=dv.filter(v=>v<=0.005).length;\n  const BINS=[[-1,0.005,'не падал ниже входа'],[0.005,0.03,'до −3¢'],[0.03,0.05,'−3…−5¢'],[0.05,0.1,'−5…−10¢'],[0.1,0.15,'−10…−15¢'],[0.15,0.2,'−15…−20¢'],[0.2,0.3,'−20…−30¢'],[0.3,0.4,'−30…−40¢'],[0.4,2,'глубже −40¢']];\n  const cnt=BINS.map(b=>dv.filter(v=>v>b[0]&&v<=b[1]).length);\n  const mode=cnt.indexOf(Math.max(...cnt)),mx=Math.max(...cnt,1);\n  const f=v=>'−'+Math.abs(v*100).toFixed(0)+'¢';\n  h+='<div class=\"kpis\">'\n   +'<div class=\"kpi\"><b>'+W.length+'</b><span>выигранных сделок</span></div>'\n   +'<div class=\"kpi\"><b class=\"pos\">'+minAb.toFixed(2)+'</b><span>самая низкая цена bid среди выигрышей ('+f(Math.max(...dv))+' от входа) — до неё падали <b>'+ab.filter(v=>Math.round(v*100)<=minK).length+'</b> раз</span></div>'\n   +'<div class=\"kpi\"><b>'+f(med)+'</b><span>медиана: типичная глубина просадки у победы</span></div>'\n   +'<div class=\"kpi\"><b>'+f(avg)+'</b><span>среднее</span></div>'\n   +'<div class=\"kpi\"><b>'+BINS[mode][2]+'</b><span>самая частая глубина ('+cnt[mode]+' из '+W.length+')</span></div>'\n   +'<div class=\"kpi\"><b>'+Math.round(never/W.length*100)+'%</b><span>побед ни разу не опускались ниже входа</span></div></div>';\n  h+='<h3>Как глубоко падал bid</h3><div class=\"tw\"><table><thead><tr><th class=\"l ns\">Глубина просадки от цены входа</th><th class=\"ns\">побед</th><th class=\"ns\">доля</th><th class=\"l ns\" style=\"width:40%\"></th></tr></thead><tbody>';\n  BINS.forEach((b,i)=>{h+='<tr><td class=\"l'+(i===mode?' pos':'')+'\"><b>'+b[2]+'</b></td><td>'+cnt[i]+'</td><td>'+Math.round(cnt[i]/W.length*100)+'%</td><td class=\"l\"><div style=\"height:10px;border-radius:5px;background:'+(i===mode?'var(--acc)':'var(--w)')+';width:'+Math.round(cnt[i]/mx*100)+'%;opacity:.8\"></div></td></tr>';});\n  h+='</tbody></table></div>';\n  const cp=new Map();ab.forEach(v=>{const k=Math.round(v*100);cp.set(k,(cp.get(k)||0)+1);});\n  const keys=[...cp.keys()].sort((a,b)=>a-b);let cum=0;\n  h+='<h3>До какой минимальной цены падал bid (по точной цене)</h3><div class=\"small mut\" style=\"margin:0 0 4px\">Самая низкая цена bid после входа у каждой выигранной сделки. «Падали не выше» — сколько побед опускались до этой цены <b>или ниже</b> и всё равно выиграли.</div><div class=\"tw\"><table><thead><tr><th class=\"l ns\">Мин. цена bid</th><th class=\"ns\">побед (ровно)</th><th class=\"ns\">падали не выше</th><th class=\"ns\">доля от всех побед</th></tr></thead><tbody>';\n  keys.slice(0,25).forEach(k=>{cum+=cp.get(k);h+='<tr><td class=\"l\"><b>'+(k/100).toFixed(2)+'</b></td><td>'+cp.get(k)+'</td><td>'+cum+'</td><td>'+Math.round(cum/W.length*100)+'%</td></tr>';});\n  h+='</tbody></table></div>'+(keys.length>25?'<div class=\"small mut\">показаны 25 самых низких цен из '+keys.length+'</div>':'');\n  h+='<h3>8 побед с самой глубокой просадкой <span class=\"mut small\" style=\"font-weight:400\">— нажми, чтобы увидеть график</span></h3><div class=\"tw\"><table><thead><tr><th class=\"l ns\">Время</th><th class=\"l ns\">Ячейка</th><th class=\"l ns\">Монета</th><th class=\"ns\">Вход</th><th class=\"ns\">Мин. bid</th><th class=\"ns\">от входа</th></tr></thead><tbody>';\n  WINLOW.forEach((r,i)=>{h+='<tr class=\"click\" data-act=\"wtrade\" data-k=\"'+i+'\"><td class=\"l\">'+tz(r[C.ts])+'</td><td class=\"l\">'+esc(D.combos[r[C.combo]])+'</td><td class=\"l\">'+esc(COIN_SHORT[D.coins[r[C.coin]]]||D.coins[r[C.coin]])+'</td><td>'+r[CI.px].toFixed(2)+'</td><td>'+(r[CI.px]+r[CI.mae]).toFixed(2)+'</td><td class=\"neg\">'+f(-r[CI.mae])+'</td></tr>';});\n  h+='</tbody></table></div><div class=\"small mut\" style=\"margin-top:6px\">Это показывает, какой стоп выбил бы эти победы: стоп ближе к входу, чем «мин. цена», срезал бы такие сделки. Знание задним числом — для анализа.</div></div>';\n  return h;\n}\nfunction candleBlock(){\n  const base=selRowsPlain();\n  const FE=[['crg','Размах монеты до входа, bps','entry'],['cbd','Тело ÷ размах до входа (0 = доджи)','entry'],['chi','Макс. в нашу сторону до входа, bps','entry'],['clo','Макс. против нас до входа, bps','entry'],['wrg','Размах всей свечи, bps','post'],['wbd','Тело ÷ размах всей свечи','post'],['wup','Тень в нашу сторону (задним числом), bps','post'],['wdn','Тень против нас (задним числом), bps','post']].filter(f=>CI[f[0]]!==undefined);\n  let h='<div class=\"card\"><h3 style=\"margin-top:0\">🕯 Свеча рынка: чем победы отличаются от проигрышей</h3>';\n  if(!FE.length)return h+'<div class=\"small mut\">В этом файле нет данных о свече монеты — они появятся в новых данных после обновления бота.</div></div>';\n  const Wn=base.filter(r=>r[C.won]),Ls=base.filter(r=>!r[C.won]);\n  if(Wn.length<5||Ls.length<3)return h+'<div class=\"small mut\">Мало сделок для сравнения (нужно хотя бы 5 побед и 3 проигрыша).</div></div>';\n  const med=a=>{if(!a.length)return null;const q=a.slice().sort((x,y)=>x-y);return q[q.length>>1];};\n  const auc=(w,l)=>{ // доля пар, где у победы значение больше\n    if(!w.length||!l.length)return null;const all=[];w.forEach(v=>all.push([v,1]));l.forEach(v=>all.push([v,0]));all.sort((a,b)=>a[0]-b[0]);\n    let rk=0,sw=0,i=0;while(i<all.length){let j=i;while(j<all.length&&all[j][0]===all[i][0])j++;const avg=(i+j+1)/2;for(let k=i;k<j;k++)if(all[k][1])sw+=avg;i=j;}\n    return (sw-w.length*(w.length+1)/2)/(w.length*l.length);};\n  const f1=v=>v===null?'—':(Math.abs(v)>=10?v.toFixed(0):v.toFixed(2));\n  h+='<div class=\"small mut\" style=\"margin:0 0 6px\">Монета считается в нашу сторону (если играем Up — рост это «+»). Свеча — от открытия окна. «Сила различия» — 50% значит признак ничего не отличает, 70%+ / 30%− уже что-то значит. <b>Признаки со словом «задним числом» знать при входе нельзя</b> — они только объясняют, что произошло.</div>';\n  h+='<div class=\"tw\"><table><thead><tr><th class=\"l ns\">Признак</th><th class=\"ns\">победы (медиана)</th><th class=\"ns\">проигрыши (медиана)</th><th class=\"ns\">сила различия</th><th class=\"ns\">знать при входе</th></tr></thead><tbody>';\n  FE.forEach(f=>{const k=CI[f[0]];const w=Wn.map(r=>r[k]).filter(v=>!isNul(v)),l=Ls.map(r=>r[k]).filter(v=>!isNul(v));const a=auc(w,l);\n    const st=a===null?'':Math.round(a*100)+'%';const strong=a!==null&&Math.abs(a-.5)>=.2;\n    h+='<tr><td class=\"l\">'+esc(f[1])+'</td><td>'+f1(med(w))+' <span class=\"mut small\">('+w.length+')</span></td><td>'+f1(med(l))+' <span class=\"mut small\">('+l.length+')</span></td><td class=\"'+(strong?'pos':'')+'\"><b>'+st+'</b></td><td>'+(f[2]==='entry'?'да':'нет')+'</td></tr>';});\n  h+='</tbody></table></div>';\n  const kb=CI.cbd;\n  if(kb!==undefined){\n    const B=[[-9,-0.1,'идёт против нас'],[-0.1,0.2,'доджи (тело < 20% размаха)'],[0.2,0.5,'тело 20–50%'],[0.5,0.8,'тело 50–80%'],[0.8,99,'тело 80%+ (шла одним движением)']];\n    h+='<h3>Доджи или нет — как торговалось</h3><div class=\"small mut\" style=\"margin:0 0 4px\">Берём «тело ÷ размах» монеты на момент входа: чем меньше — тем больше монета топталась у открытия.</div><div class=\"tw\"><table><thead><tr><th class=\"l ns\">Свеча к моменту входа</th><th class=\"ns\">сделок</th><th class=\"ns\">% побед</th><th class=\"ns\">ROI</th></tr></thead><tbody>';\n    B.forEach(b=>{const rr=base.filter(r=>!isNul(r[kb])&&r[kb]>b[0]&&r[kb]<=b[1]);if(!rr.length)return;const wn=rr.filter(r=>r[C.won]).length;const s=stats(rr);\n      h+='<tr><td class=\"l\">'+b[2]+'</td><td>'+rr.length+'</td><td>'+Math.round(wn/rr.length*100)+'%</td><td class=\"'+(s.roi>=0?'pos':'neg')+'\">'+(s.roi*100).toFixed(1)+'%</td></tr>';});\n    h+='</tbody></table></div>';\n  }\n  h+='<div class=\"small mut\" style=\"margin-top:6px\">Осторожно: если сделок в строке мало (десятки), красивая разница может быть случайной. Сначала смотри, что вывод держится на разных днях и ТС, потом верь.</div></div>';\n  return h;\n}\n// ---------- события ----------\nconst app=document.getElementById('app');\nfunction fltIdx(el){const r=el.closest('.fl');return r?+r.getAttribute('data-i'):-1;}\napp.addEventListener('click',e=>{\n  const t=e.target.closest('[data-act]');if(!t)return;\n  const a=t.getAttribute('data-act');\n  if(t.tagName==='A')e.preventDefault();\n  if(a==='fdel'){S.flt.splice(fltIdx(t),1);render();}\n  else if(a==='fclear'){S.goalP=0;S.goalL=0;S.flt=[];S.dFrom='';S.dTo='';S.q='';render();}\n  else if(a==='preset'){presetClick(PRESET_GROUPS[+t.getAttribute('data-g')].p[+t.getAttribute('data-i')]);render();}\n  else if(a==='tab'){S.tab=t.getAttribute('data-t');S.sel=null;S.back=null;render();}\n  else if(a==='opentop'){S.sel={by:t.getAttribute('data-by'),key:t.getAttribute('data-k')};S.back='top';S.tradeN=100;render();window.scrollTo(0,0);}\n  else if(a==='topmore'){const id=t.getAttribute('data-id');S.top.show[id]=(S.top.show[id]||8)+10;render();}\n  else if(a==='topcsv'){downloadTopCsv();}\n  else if(a==='cummode'){S.cumMode=t.getAttribute('data-m');render();}\n  else if(a==='favadd'){const f=favFromKey(t.getAttribute('data-by'),t.getAttribute('data-k'));if(!f)window.alert('Эту строку нельзя сохранить в избранное.');else if(addFav(f))render();}\n  else if(a==='favsave'){let f=null;if(S.sel.chain){f={id:newFavId(),type:'chain',name:S.sel.title||'Цепочка',steps:JSON.parse(JSON.stringify(S.sel.chain.steps)),gap:S.sel.chain.gap};}else f=favFromKey(S.sel.by,S.sel.key);if(!f)window.alert('Эту выборку нельзя сохранить в избранное.');else{const sn=exSnap();if(sn)f.ex=sn;if(addFav(f))render();}}\n  else if(a==='favex'){const f=FAVS.find(x=>x.id===S.sel.favId);if(f){const sn=exSnap();if(sn)f.ex=sn;else delete f.ex;saveFavs();render();}}\n  else if(a==='favdel'){const id=t.getAttribute('data-id');const f=FAVS.find(x=>x.id===id);if(f&&window.confirm('Убрать из избранного: '+f.name+'?')){delFav(id);if(S.sel&&S.sel.favId===id){S.sel=null;S.back=null;}render();}}\n  else if(a==='favren'){const id=t.getAttribute('data-id');const f=FAVS.find(x=>x.id===id);if(f){const nm=window.prompt('Новое название:',f.name);if(nm&&nm.trim()){f.name=nm.trim();saveFavs();render();}}}\n  else if(a==='openfav'){const f=FAVS.find(x=>x.id===t.getAttribute('data-id'));if(f){exApply(f.ex||null);S.sel={by:'fav',key:f.id,title:f.name,favId:f.id,rows:favRows(f)};S.back='fav';S.tradeN=100;render();window.scrollTo(0,0);}}\n  else if(a==='favexp'){document.getElementById('favio').value=JSON.stringify({favs:FAVS,removed:FAV_REMOVED});}\n  else if(a==='favimp'){try{const o=JSON.parse(document.getElementById('favio').value);const arr=Array.isArray(o)?o:(o.favs||[]);arr.forEach(f=>{if(!f.id)f.id=newFavId();const k=FAVS.findIndex(x=>x.id===f.id);if(k>=0)FAVS[k]=f;else FAVS.push(f);});saveFavs();render();}catch(err){window.alert('Не удалось прочитать текст: '+err.message);}}\n  else if(a==='favreset'){if(window.confirm('Вернуть стандартные избранные? Свои останутся, удалённые стандартные вернутся.')){FAV_REMOVED=[];saveFavs();loadFavs();saveFavs();render();}}\n  else if(a==='chadd'){S.ch.steps.push({kind:'band',lo:0.9,hi:0.99,fam:''});render();}\n  else if(a==='chdel'){const i=+t.closest('.fl').getAttribute('data-st');S.ch.steps.splice(i,1);render();}\n  else if(a==='chpreset'){const P=[[[0.6,0.7],[0.8,0.9]],[[0.6,0.7],[0.8,0.9],[0.93,0.98]],[[0.7,0.8],[0.9,0.95]]][+t.getAttribute('data-i')];S.ch.steps=P.map(b=>({kind:'band',lo:b[0],hi:b[1],fam:''}));render();}\n  else if(a==='chopen'){const res=chainCompute(S.ch.steps,S.ch.gap,rowsF);S.sel={by:'chain',key:'chain',title:'Цепочка: '+chainLabel(S.ch.steps),rows:res.chain,chain:{steps:JSON.parse(JSON.stringify(S.ch.steps)),gap:S.ch.gap}};S.back='chain';S.tradeN=100;render();window.scrollTo(0,0);}\n  else if(a==='chfav'){const f={id:newFavId(),type:'chain',name:'Цепочка: '+chainLabel(S.ch.steps),steps:JSON.parse(JSON.stringify(S.ch.steps)),gap:S.ch.gap};if(addFav(f))render();}\n  else if(a==='fval'){const f=S.flt[fltIdx(t)];let v=t.getAttribute('data-v');const num=CATF[f.f].vals.some(x=>typeof x[0]==='number');if(num)v=+v;const k=f.vals.indexOf(v);if(k>=0)f.vals.splice(k,1);else f.vals.push(v);render();}\n  else if(a==='sort'){const k=t.getAttribute('data-k');if(S.sort===k)S.dir=-S.dir;else{S.sort=k;S.dir=k==='name'?1:-1;}render();}\n  else if(a==='open'){S.back=null;S.sel={by:S.by,key:t.getAttribute('data-k')};S.tradeN=100;render();window.scrollTo(0,0);}\n  else if(a==='back'){if(S.back)S.tab=S.back;S.back=null;S.sel=null;render();window.scrollTo(0,0);}\n  else if(a==='more'){S.show+=200;render();}\n  else if(a==='moreT'){S.tradeN+=200;render();}\n  else if(a==='help'){helpOpen=true;render();window.scrollTo(0,0);}\n  else if(a==='helpclose'){helpOpen=false;render();}\n  else if(a==='flip'){S.sel.flip=!S.sel.flip;render();window.scrollTo(0,0);}\n  else if(a==='jump'){const el=document.getElementById(t.getAttribute('data-id'));if(el)el.scrollIntoView({behavior:'smooth',block:'start'});}\n  else if(a==='csv'){downloadCsv(selRows());}\n  else if(a==='xadd'){const L2=X.add.steps,last=L2[L2.length-1];X.add.steps.push({m:'c',v:last?Math.min(90,last.v+10):10,usd:last?last.usd:S.stake});render();}\n  else if(a==='xdel'){X.add.steps.splice(+t.getAttribute('data-i'),1);if(!X.add.steps.length)X.add.on=false;render();}\n  else if(a==='trade'){const r=TRLIST[+t.getAttribute('data-k')];if(r)openTrade(r);}\n  else if(a==='tclose'){closeTrade();}\n  else if(a==='wtrade'){const r=WINLOW[+t.getAttribute('data-k')];if(r)openTrade(r);}\n  else if(a==='ltrade'){const r=LOSSTOP[+t.getAttribute('data-k')];if(r)openTrade(r);}\n});\napp.addEventListener('change',e=>{\n  const t=e.target;const a=t.getAttribute('data-act');\n  if(t.id==='addnum'&&t.value){S.flt.push({t:'num',col:t.value,lo:null,hi:null});render();return;}\n  if(t.id==='addcat'&&t.value){S.flt=S.flt.filter(x=>!(x.t==='cat'&&x.f===t.value));S.flt.push({t:'cat',f:t.value,vals:[]});render();return;}\n  if(t.id==='by'){S.by=t.value;S.sel=null;render();return;}\n  if(t.id==='fav_sort'){S.favSort=t.value;render();return;}\n  if(t.id==='ch_gap'){S.ch.gap=t.value;render();return;}\n  const dc=t.getAttribute('data-ch');\n  if(dc){const i=+t.closest('.fl').getAttribute('data-st');const st=S.ch.steps[i];if(st){if(dc==='kind'){st.kind=t.value;if(t.value==='fav'&&!st.favId){const f=FAVS.find(x=>x.type!=='chain');st.favId=f?f.id:null;}}else if(dc==='fav')st.favId=t.value;else if(dc==='fam')st.fam=t.value;else if(dc==='lo')st.lo=t.value===''?null:+t.value;else if(dc==='hi')st.hi=t.value===''?null:+t.value;}render();return;}\n  if(t.id&&t.id.indexOf('x_')===0){xChange(t);return;}\n  if(t.id==='dFrom'){S.dFrom=t.value;render();return;}\n  if(t.id==='dTo'){S.dTo=t.value;render();return;}\n  if(t.id==='q'){S.q=t.value;render();return;}\n  if(t.id==='tp_by'){S.top.by=t.value;S.top.show={};render();return;}\n  if(t.id==='tp_goal'){S.top.goal=Math.max(0,+t.value||0);render();return;}\n  if(t.id==='tp_sm'){S.top.minSm=Math.max(0,Math.min(100,+t.value||0));render();return;}\n  if(t.id==='minSm'){S.minSm=Math.max(0,Math.min(100,+t.value||0));render();return;}\n  if(t.id==='tp_loss'){S.top.maxLoss=Math.max(0,Math.floor(+t.value||0));render();return;}\n  if(t.id==='tp_cover'){S.top.cover=Math.min(100,Math.max(0,+t.value||0));render();return;}\n  if(t.id==='tp_minn'){S.top.minN=Math.max(1,Math.floor(+t.value||1));render();return;}\n  if(t.id==='tp_sort'){S.top.sort=t.value;render();return;}\n  if(t.id==='tp_team'){S.top.team=+t.value;render();return;}\n  if(t.id==='tp_trim'){S.top.trim=t.checked;render();return;}\n  if(t.id==='tp_oos'){S.top.needOos=t.checked;render();return;}\n  if(t.id==='minN'){S.minN=Math.max(1,+t.value||1);render();return;}\n  if(t.id==='one'){S.one=t.checked;render();return;}\n  if(t.id==='stake'){S.stake=Math.max(1,+t.value||5);render();return;}\n  if(t.id==='goalP'){S.goalP=Math.max(0,+t.value||0);render();return;}\n  if(t.id==='goalL'){S.goalL=Math.max(0,+t.value||0);render();return;}\n  if(t.id==='bcol'){S.bucket=t.value;render();return;}\n  if(a==='fneg'){S.flt[fltIdx(t)].neg=t.checked;render();}\n  else if(a==='fnul'){S.flt[fltIdx(t)].nul=t.checked;render();}\n  else if(a==='fcol'){S.flt[fltIdx(t)].col=t.value;render();}\n  else if(a==='flo'||a==='fhi'){const f=S.flt[fltIdx(t)];const v=t.value===''?null:+t.value;if(a==='flo')f.lo=v;else f.hi=v;render();}\n});\n\napp.addEventListener('mousemove',e=>{\n  const svg=e.target.closest?e.target.closest('svg[data-cum]'):null;if(!svg)return;\n  const R=CUMREG[svg.getAttribute('data-cum')];if(!R)return;\n  const rc=svg.getBoundingClientRect();if(!rc.width)return;\n  const x=(e.clientX-rc.left)/rc.width*R.W;\n  const f=Math.min(1,Math.max(0,(x-R.pl)/(R.W-R.pl-R.pr)));\n  const tx=R.x0+f*(R.x1-R.x0);\n  let lo=0,hi=R.xs.length-1;\n  while(lo<hi){const m=(lo+hi)>>1;if(R.xs[m]<tx)lo=m+1;else hi=m;}\n  let i=lo;if(i>0&&Math.abs(R.xs[i-1]-tx)<Math.abs(R.xs[i]-tx))i--;\n  const r=R.s[i],ln=svg.querySelector('.cl'),tip=svg.parentNode.querySelector('.cumtip');\n  const px=R.pl+(R.W-R.pl-R.pr)*((R.xs[i]-R.x0)/((R.x1-R.x0)||1));\n  if(ln){ln.setAttribute('x1',px);ln.setAttribute('x2',px);ln.style.display='';}\n  const v=roiOf(r)*S.stake;\n  if(tip)tip.innerHTML='сделка <b>#'+(i+1)+'</b> · '+tz(r[C.ts])+' · '+esc(rowName(r))+' по '+fmt(r[CI.px],3)+' · <span class=\"'+(r[C.won]?'pos':'neg')+'\">'+(r[C.won]?'победа ':'проигрыш ')+money(v)+'</span> · накоплено <b class=\"'+cls(R.ys[i])+'\">'+money(R.ys[i])+'</b>';\n});\n(function(){\n  try{const th=localStorage.getItem('lab-theme');if(th)document.documentElement.setAttribute('data-theme',th);}catch(e){}\n  const tb=document.getElementById('themebtn');\n  if(tb)tb.addEventListener('click',function(){const cur=document.documentElement.getAttribute('data-theme');const dark=cur?cur==='dark':window.matchMedia('(prefers-color-scheme:dark)').matches;const nx=dark?'light':'dark';document.documentElement.setAttribute('data-theme',nx);try{localStorage.setItem('lab-theme',nx);}catch(e){}});\n  render();\n})();\n}).catch(function(e){var v=document.getElementById('app');if(v)v.innerHTML='<div class=\"note warn\">Ошибка загрузки данных: '+(e&&e.message?e.message:e)+'</div>';console.error(e);});\n</script>\n</body>\n</html>\n";
